"""Context builder — formats game state into text for LLM prompts.

Key information isolation rules (section 3.10-3.11):
- Own cards: full suit+rank
- Other players' played cards: rank-only
- Dizhu cards: full suit+rank (public after bidding)
- Agent does NOT see other agents' reasoning
"""

from __future__ import annotations

from ..engine.card import Card, SEATS
from ..engine.trick import Trick
from .base import AgentContext


class ContextBuilder:
    """Builds text representations of game state for LLM prompts.

    All methods are static — they transform an AgentContext into
    formatted text strings suitable for inclusion in prompts.
    """

    # ── hand display ─────────────────────────────────────────────────────────

    @staticmethod
    def format_hand(cards: list[Card]) -> str:
        """Format hand in display order: rank desc, suit ♠>♥>♣>♦."""
        return " ".join(str(c) for c in cards)

    @staticmethod
    def format_dizhu_info(
        dizhu_cards: tuple[Card, ...] | None,
        hand_cards: list[Card],
    ) -> str:
        """Format dizhu card info with played/unplayed status."""
        if dizhu_cards is None:
            return "底牌：尚未公开（叫分进行中）"

        # Determine which dizhu cards are still in hand (unplayed)
        from ..engine.hand import Hand
        temp_hand = Hand.from_cards(hand_cards)
        temp_hand.mark_dizhu_cards(dizhu_cards)
        played_status = temp_hand.dizhu_played_status()

        lines = ["底牌内容："]
        for card in dizhu_cards:
            card_str = str(card)
            status = "已打出" if played_status.get(card_str, False) else "未打出"
            lines.append(f"  {card_str} — {status}")
        return "\n".join(lines)

    # ── bidding history ──────────────────────────────────────────────────────

    @staticmethod
    def format_bidding_history(bidding_history: list[dict]) -> str:
        """Format bidding history as text lines."""
        if not bidding_history:
            return "（尚无叫分记录）"
        lines = []
        for r in bidding_history:
            seat = r["seat"]
            bid = r["bid"]
            bid_str = "不叫" if bid == 0 else f"{bid}分"
            lines.append(f"  {seat}：{bid_str}")
        return "\n".join(lines)

    # ── play history (rank-only for others) ──────────────────────────────────

    @staticmethod
    def format_play_history(
        play_history: list[dict],
        own_seat: str,
    ) -> str:
        """Format play history per section 3.11 rules.

        Own plays show suit+rank. Others show rank-only.
        Rounds are marked [R1], [R2], etc.
        """
        if not play_history:
            return "（尚无出牌记录）"

        lines: list[str] = []
        current_round = 0
        current_line_parts: list[str] = []

        for record in play_history:
            rnd = record.get("round", 0)
            seat = record.get("seat", "?")
            action_type = record.get("action_type", "?")
            cards = record.get("cards") or []
            trick_display = record.get("trick_display")

            # Start new round marker
            if rnd != current_round:
                if current_line_parts:
                    lines.append("  ".join(current_line_parts))
                    current_line_parts = []
                current_round = rnd
                current_line_parts.append(f"[R{rnd}]")

            # Build action text
            if action_type == "pass":
                current_line_parts.append(f"{seat}：Pass")
            else:
                if seat == own_seat:
                    # Own cards: full suit+rank from raw cards
                    cards_str = "".join(str(c) for c in cards)
                    current_line_parts.append(f"你：{cards_str}")
                else:
                    # Others: rank-only display only (no suit!)
                    if trick_display:
                        current_line_parts.append(f"{seat}：{trick_display}")
                    else:
                        rank_str = "".join(c.rank_only if isinstance(c, Card) else str(c)[-1] for c in cards)
                        current_line_parts.append(f"{seat}：{rank_str}")

            # Check if this completes a round (trick_won is indicated by next round or end)
            # We flush on round change or at end

        if current_line_parts:
            lines.append("  ".join(current_line_parts))

        return "\n".join(lines)

    # ── player info ──────────────────────────────────────────────────────────

    @staticmethod
    def format_player_info(
        own_seat: str,
        role: str,
        landlord: str,
        active_players: list[str],
        player_hand_sizes: dict[str, int],
        seat_teams: dict[str, str] | None = None,
        effective_idle: str = "",
    ) -> str:
        """Format the player status section."""
        lines = [f"你的座位：{own_seat}"]
        lines.append(f"你的身份：{role}")
        if landlord:
            lines.append(f"地主座位：{landlord}")

        # List players
        for seat in SEATS:
            if seat == own_seat:
                continue
            if seat in player_hand_sizes:
                size = player_hand_sizes[seat]
                if seat == effective_idle:
                    lines.append(f"  {seat}：闲家（观战，{size}张手牌）")
                else:
                    role_str = "地主" if seat == landlord else "农民"
                    lines.append(f"  {seat}：{role_str}，剩余{size}张")
        return "\n".join(lines)

    # ── current trick info ───────────────────────────────────────────────────

    @staticmethod
    def format_current_trick(trick: Trick | None, trick_leader: str = "") -> str:
        """Format the current pattern to beat."""
        if trick is None:
            return "新一轮，自由出牌（场上无牌型需要跟）"
        # Clarify comparison rule for structured patterns
        comparison_hint = f"你需要出更大的{trick.pattern.value}"
        if trick.pattern.value in ("三带一", "三带二"):
            comparison_hint += f"（只需三条部分rank > {trick.main_rank.display if trick.main_rank else '?'}，带的牌任意）"
        elif trick.pattern.value in ("四带二单", "四带二同单", "四带二对"):
            comparison_hint += f"（只需四同rank部分rank > {trick.main_rank.display if trick.main_rank else '?'}，带的牌任意）"
        comparison_hint += "，或者出炸弹/火箭来压"
        return (
            f"场上牌型：{trick.display()}（{trick.pattern.value}）\n"
            f"  领出者：{trick_leader}\n"
            f"  {comparison_hint}"
        )

    # ── complete context builder methods ─────────────────────────────────────

    @staticmethod
    def build_play_context_text(ctx: AgentContext, seat_teams: dict[str, str] = None) -> str:
        """Build the full context text for a play decision prompt."""
        parts = []

        # Player info
        effective_idle = ""
        for seat, size in ctx.player_hand_sizes.items():
            if size == 0 and seat != ctx.seat:
                effective_idle = seat
        parts.append(ContextBuilder.format_player_info(
            ctx.seat, ctx.role, ctx.landlord,
            ctx.active_players, ctx.player_hand_sizes,
            seat_teams, effective_idle,
        ))

        # Hand
        parts.append(f"\n你的手牌（{ctx.hand_size}张）：\n{ContextBuilder.format_hand(ctx.hand_cards)}")

        # Dizhu cards
        if ctx.dizhu_cards is not None:
            parts.append(f"\n{ContextBuilder.format_dizhu_info(ctx.dizhu_cards, ctx.hand_cards)}")

        # Current trick
        parts.append(f"\n{ContextBuilder.format_current_trick(ctx.current_trick, ctx.trick_leader)}")

        # Bidding history
        parts.append(f"\n叫分历史：\n{ContextBuilder.format_bidding_history(ctx.bidding_history)}")

        # Play history
        parts.append(f"\n行牌历史：\n{ContextBuilder.format_play_history(ctx.play_history, ctx.seat)}")

        return "\n".join(parts)

    @staticmethod
    def build_bidding_context_text(ctx: AgentContext) -> str:
        """Build the full context text for a bidding decision prompt."""
        parts = []

        parts.append(f"你的座位：{ctx.seat}")
        bid_order_pos = "首家" if len(ctx.bidding_history) == 0 else \
                        "二家" if len(ctx.bidding_history) == 1 else "尾家"
        parts.append(f"叫分顺序位置：{bid_order_pos}")
        parts.append(f"\n你的手牌（{ctx.hand_size}张）：\n{ContextBuilder.format_hand(ctx.hand_cards)}")

        if ctx.current_high_bid > 0:
            parts.append(f"\n当前最高叫分：{ctx.current_high_bid}分（{ctx.current_high_bidder}）")
        else:
            parts.append("\n当前尚无叫分")

        parts.append(f"\n叫分历史：\n{ContextBuilder.format_bidding_history(ctx.bidding_history)}")

        return "\n".join(parts)

    @staticmethod
    def build_reflection_context_text(ctx: AgentContext) -> str:
        """Build the full context text for a reflection prompt."""
        parts = []

        parts.append(f"你的座位：{ctx.seat}")
        parts.append(f"你本副牌的身份：{ctx.agent_role or ctx.role}")

        if ctx.is_idle_observer:
            parts.append("你本副牌是闲家（观战者），未实际参与出牌。")

        # Original hand
        if ctx.initial_hand:
            parts.append(f"\n你的原始手牌：\n{ContextBuilder.format_hand(list(ctx.initial_hand))}")

        # Dizhu cards
        if ctx.dizhu_cards is not None:
            parts.append(f"\n{ContextBuilder.format_dizhu_info(ctx.dizhu_cards, ctx.hand_cards)}")

        # Bidding history
        parts.append(f"\n叫分历史：\n{ContextBuilder.format_bidding_history(ctx.bidding_history)}")

        # Full play history (rank-only for all, including self — reflection is full-info)
        parts.append(f"\n完整行牌历史（全场明牌视角）：")
        if ctx.play_history:
            for record in ctx.play_history:
                rnd = record.get("round", 0)
                seat = record.get("seat", "?")
                action_type = record.get("action_type", "?")
                cards = record.get("cards") or []
                trick_display = record.get("trick_display")
                if action_type == "pass":
                    parts.append(f"  [R{rnd}] {seat}：Pass")
                else:
                    cards_str = "".join(str(c) for c in cards)
                    display = trick_display or cards_str
                    parts.append(f"  [R{rnd}] {seat}：{display}")
        else:
            parts.append("  （无出牌记录）")

        # Remaining hands
        if ctx.remaining_hands:
            parts.append("\n全场剩余手牌：")
            for seat in SEATS:
                cards = ctx.remaining_hands.get(seat, ())
                if cards:
                    parts.append(f"  {seat}：{' '.join(str(c) for c in cards)}")
                else:
                    parts.append(f"  {seat}：（无剩余）")

        # Hand result
        if ctx.winner_role == "void":
            parts.append("\n本副牌结果：流局（所有参与叫分者均不叫），得分 0，无获胜方。")
        elif ctx.hand_score is not None:
            parts.append(f"\n本副牌结果：{ctx.winner_team}队 {ctx.winner_role} 获胜，得分 {ctx.hand_score}")

        return "\n".join(parts)

    @staticmethod
    def build_summary_context_text(ctx: AgentContext) -> str:
        """Build the full context text for a match summary prompt."""
        parts = []

        parts.append(f"你的座位：{ctx.seat}")
        parts.append(f"比赛ID：{ctx.match_id}")
        parts.append(f"实际完成副数：{len(ctx.match_summary or {})}")
        if ctx.winner_team == "tie":
            parts.append("比赛结果：平局")
        elif ctx.winner_team:
            parts.append(f"比赛获胜队：{ctx.winner_team}")

        if ctx.match_summary:
            parts.append("\n你在本场比赛中的每副牌角色：")
            for hand_num, info in sorted(ctx.match_summary.items()):
                if isinstance(info, dict):
                    parts.append(
                        f"  第{hand_num}副：{info.get('table', '')}桌 {info.get('seat', ctx.seat)}位，"
                        f"角色 {info.get('role', '?')}，结果 {info.get('outcome', '?')}，"
                        f"该桌结算分 {info.get('table_score', '?')}，"
                        f"本队差分积分 {info.get('team_score', '?')}"
                        + ("（加赛）" if info.get('is_tiebreaker') else "")
                    )

        return "\n".join(parts)

src/backend/arena/agent/llm_agent.py:
"""LLM Agent — wraps an LLM provider with prompt building, parsing, and retry logic.

Implements the full Agent protocol including reflect() and summarize().
"""

from __future__ import annotations

import hashlib
import json
import logging
import time
import uuid
from typing import Any

from ..engine.card import Card
from ..engine.trick import Trick
from ..llm.base import AbstractLLMProvider, LLMError as LLMProviderError
from .base import Agent, AgentContext, AgentError
from .context import ContextBuilder
from .memory import MemoryManager
from .parser import (
    ParseError,
    parse_bid_response,
    parse_play_response,
    parse_reflection_response,
    parse_summary_response,
)
from .prompts.bidding import build_bidding_prompt
from .prompts.playing import build_playing_prompt
from .prompts.reflection import build_reflection_prompt
from .prompts.summary import build_summary_prompt

logger = logging.getLogger(__name__)

MAX_RETRIES = 3


class LLMAgent:
    """An agent powered by an LLM provider.

    Builds prompts from templates, calls LLM, parses output, retries on failure.
    Tracks consecutive failures for the timeout manager.

    Usage:
        provider = create_provider("claude", "claude-opus-4-7", api_key)
        agent = LLMAgent("agent-1", provider, system_prompt_override="...")
        bid = await agent.decide_bid(ctx)
    """

    def __init__(
        self,
        agent_id: str,
        provider: AbstractLLMProvider,
        *,
        seat: str = "",
        system_prompt_override: str | None = None,
        long_term_memory: str = "",
        retry_limit: int = MAX_RETRIES,
        rule_feedback: bool = True,
        prompt_name: str | None = None,
        enable_tools: bool = False,
    ) -> None:
        self._agent_id = agent_id
        self._prompt_name = prompt_name or agent_id
        self._seat = seat
        self._provider = provider
        self._system_prompt_override = system_prompt_override
        self._memory = MemoryManager.with_long_term(agent_id, long_term_memory)
        self._consecutive_failures = 0
        self._seat_teams: dict[str, str] = {}
        self._last_reasoning = ""
        self._retry_limit = retry_limit
        self._rule_feedback = rule_feedback
        self._repo: Any | None = None
        self._decision_context: dict[str, str] = {}
        self._last_decision_meta: dict[str, int] = {"retry_count": 0, "latency_ms": 0}
        self.set_tools_enabled(enable_tools)

    # ── Agent Protocol ──────────────────────────────────────────────────────

    @property
    def agent_id(self) -> str:
        return self._agent_id

    @property
    def seat(self) -> str:
        return self._seat

    @seat.setter
    def seat(self, value: str) -> None:
        self._seat = value

    @property
    def memory(self) -> MemoryManager:
        return self._memory

    @property
    def consecutive_failures(self) -> int:
        return self._consecutive_failures

    def sync_failure_count(self, count: int) -> None:
        self._consecutive_failures = count

    def reset_failures(self) -> None:
        self._consecutive_failures = 0

    def get_last_reasoning(self) -> str:
        """Return the reasoning from the last LLM call. Used by TableRunner for WS thought_update."""
        return self._last_reasoning

    def set_seat_teams(self, seat_teams: dict[str, str]) -> None:
        """Provide team assignment info for context building."""
        self._seat_teams = dict(seat_teams)

    def set_observability_context(self, repo: Any | None, **context: str) -> None:
        """Attach the table-scoped sink for privacy-preserving decision events."""
        self._repo = repo
        if repo is None:
            self._decision_context.clear()
        for key, value in context.items():
            if value:
                self._decision_context[key] = value
            else:
                self._decision_context.pop(key, None)
        provider = self._provider
        if hasattr(provider, "set_observability_context"):
            provider.set_observability_context(
                repo, **{**self._decision_context, "agent_id": self._agent_id},
            )
        elif hasattr(provider, "set_context"):
            provider.set_context(**self._decision_context)

    def get_last_decision_meta(self) -> dict[str, Any]:
        return dict(self._last_decision_meta)

    def get_observability_context(self) -> dict[str, str]:
        return dict(self._decision_context)

    def begin_decision(self, decision_id: str) -> None:
        self._active_decision_id = decision_id
        self._last_reasoning = ""
        self._last_decision_meta = {"decision_id": decision_id, "retry_count": 0,
                                    "latency_ms": 0, "resolution": "failed_no_action"}

    async def decide_bid(self, ctx: AgentContext) -> int:
        system, user = build_bidding_prompt(ctx, self._memory, self._prompt_name, self._system_prompt_override)
        return await self._decide("bidding", system, user,
                                  lambda raw: parse_bid_response(raw, ctx.current_high_bid), 0)

    async def decide_play(self, ctx: AgentContext) -> list[Card]:
        system, user = build_playing_prompt(ctx, self._memory, self._prompt_name,
            seat_teams=self._seat_teams, system_prompt_override=self._system_prompt_override)
        if self._tools_enabled:
            from .tool_turn import decide_with_tools
            return await decide_with_tools(self, ctx, system, user)
        return await self._decide("playing", system, user,
            lambda raw: parse_play_response(raw, list(ctx.hand_cards), ctx.current_trick), [])

    def set_tools_enabled(self, enabled: bool) -> None:
        if type(enabled) is not bool:
            raise ValueError("enable_tools must be boolean")
        if enabled and not getattr(self._provider, "supports_tools", False):
            raise ValueError("provider does not support native tool calls")
        self._tools_enabled = enabled

    async def _decide(self, phase, system, user, parse, fallback):
        import asyncio
        decision_id = getattr(self, "_active_decision_id", None) or uuid.uuid4().hex
        self._active_decision_id = None
        self._last_reasoning = ""
        started = time.monotonic()
        for attempt in range(1, self._retry_limit + 2):
            response = None
            error = None
            self._set_provider_call_context(phase, decision_id, attempt)
            try:
                response = await self._provider.generate(user, system)
                action, reasoning = parse(response)
            except asyncio.CancelledError:
                self._last_decision_meta = {"decision_id": decision_id, "retry_count": attempt - 1,
                    "latency_ms": int((time.monotonic()-started)*1000), "resolution": "cancelled"}
                raise
            except (ParseError, LLMProviderError) as exc:
                error = exc
            elapsed = int((time.monotonic()-started)*1000)
            final = error is None or attempt == self._retry_limit + 1
            self._record_event(phase, attempt, decision_id=decision_id, response=response,
                error=error, is_illegal=isinstance(error, ParseError), is_retry=attempt > 1,
                is_fallback=bool(error and final), fallback_reason=self._classify_error(error) if error and final else None,
                latency_ms=elapsed if final else None)
            self._last_decision_meta = {"decision_id": decision_id, "retry_count": attempt - 1,
                "latency_ms": elapsed, "resolution": "system_fallback" if error else ("model_first" if attempt == 1 else "model_retry"),
                "reason": self._classify_error(error) if error else None}
            if error is None:
                self._consecutive_failures = 0
                self._last_reasoning = reasoning
                return action
            if final:
                self._consecutive_failures += 1  # once per exhausted decision, not per provider attempt
                return fallback
            user = self._append_retry_feedback(user, str(error), attempt) if self._rule_feedback else (
                user + "\n\n请重新独立生成一个完整 JSON 回复。")
        raise AssertionError("unreachable")

    async def reflect(self, ctx: AgentContext) -> dict[str, str]:
        """Post-hand reflection via LLM."""
        system, user = build_reflection_prompt(
            ctx, self._memory, self._prompt_name, self._system_prompt_override
        )

        started = time.monotonic()
        decision_id = uuid.uuid4().hex
        retries = 0
        for attempt in range(self._retry_limit + 1):
            try:
                self._set_provider_call_context("reflection", decision_id, attempt + 1)
                response = await self._provider.generate(user, system)
                result = parse_reflection_response(response)
                elapsed_ms = int((time.monotonic() - started) * 1000)
                self._record_event(
                    "reflection", attempt + 1, decision_id=decision_id,
                    response=response, is_retry=attempt > 0, latency_ms=elapsed_ms,
                    final_action="reflection_saved",
                )
                self._last_decision_meta = {"retry_count": retries, "latency_ms": elapsed_ms}
                logger.info(
                    "Agent %s reflection: %s",
                    self._agent_id, result["reflection"][:200],
                )
                return result
            except ParseError as e:
                is_final = attempt >= self._retry_limit
                elapsed_ms = int((time.monotonic() - started) * 1000)
                self._record_event(
                    "reflection", attempt + 1, decision_id=decision_id, error=e,
                    is_illegal=True, is_retry=attempt > 0, is_fallback=is_final,
                    fallback_reason="parse_error" if is_final else None,
                    latency_ms=elapsed_ms if is_final else None,
                    final_action="empty_reflection" if is_final else None,
                )
                if attempt < self._retry_limit:
                    retries += 1
                    if self._rule_feedback:
                        user = self._append_retry_feedback(user, str(e), attempt + 1)
                else:
                    self._last_decision_meta = {"retry_count": retries, "latency_ms": elapsed_ms}
                    logger.warning(
                        "Agent %s reflection parse failed: %s", self._agent_id, e
                    )
                    return {"reflection": "", "short_term_memory": ""}
            except LLMProviderError as e:
                is_final = attempt >= self._retry_limit
                elapsed_ms = int((time.monotonic() - started) * 1000)
                self._record_event(
                    "reflection", attempt + 1, decision_id=decision_id, error=e,
                    is_retry=attempt > 0, is_fallback=is_final,
                    fallback_reason="provider_error" if is_final else None,
                    latency_ms=elapsed_ms if is_final else None,
                    final_action="empty_reflection" if is_final else None,
                )
                logger.error("Agent %s LLM error during reflection: %s", self._agent_id, e)
                if attempt < self._retry_limit:
                    retries += 1
                    continue
                self._last_decision_meta = {"retry_count": retries, "latency_ms": elapsed_ms}
                return {"reflection": "", "short_term_memory": ""}

        return {"reflection": "", "short_term_memory": ""}

    async def summarize(self, ctx: AgentContext) -> dict[str, str]:
        """Post-match summary via LLM."""
        system, user = build_summary_prompt(
            ctx, self._memory, self._prompt_name, self._system_prompt_override
        )

        started = time.monotonic()
        decision_id = uuid.uuid4().hex
        retries = 0
        for attempt in range(self._retry_limit + 1):
            try:
                self._set_provider_call_context("summary", decision_id, attempt + 1)
                response = await self._provider.generate(user, system)
                result = parse_summary_response(response)
                elapsed_ms = int((time.monotonic() - started) * 1000)
                self._record_event(
                    "summary", attempt + 1, decision_id=decision_id,
                    response=response, is_retry=attempt > 0, latency_ms=elapsed_ms,
                    final_action="summary_saved",
                )
                self._last_decision_meta = {"retry_count": retries, "latency_ms": elapsed_ms}
                logger.info(
                    "Agent %s summary: %s",
                    self._agent_id, result["summary"][:200],
                )
                return result
            except ParseError as e:
                is_final = attempt >= self._retry_limit
                elapsed_ms = int((time.monotonic() - started) * 1000)
                self._record_event(
                    "summary", attempt + 1, decision_id=decision_id, error=e,
                    is_illegal=True, is_retry=attempt > 0, is_fallback=is_final,
                    fallback_reason="parse_error" if is_final else None,
                    latency_ms=elapsed_ms if is_final else None,
                    final_action="empty_summary" if is_final else None,
                )
                if attempt < self._retry_limit:
                    retries += 1
                    if self._rule_feedback:
                        user = self._append_retry_feedback(user, str(e), attempt + 1)
                else:
                    self._last_decision_meta = {"retry_count": retries, "latency_ms": elapsed_ms}
                    logger.warning(
                        "Agent %s summary parse failed: %s", self._agent_id, e
                    )
                    return {"summary": "", "long_term_memory": ""}
            except LLMProviderError as e:
                is_final = attempt >= self._retry_limit
                elapsed_ms = int((time.monotonic() - started) * 1000)
                self._record_event(
                    "summary", attempt + 1, decision_id=decision_id, error=e,
                    is_retry=attempt > 0, is_fallback=is_final,
                    fallback_reason="provider_error" if is_final else None,
                    latency_ms=elapsed_ms if is_final else None,
                    final_action="empty_summary" if is_final else None,
                )
                logger.error("Agent %s LLM error during summary: %s", self._agent_id, e)
                if attempt < self._retry_limit:
                    retries += 1
                    continue
                self._last_decision_meta = {"retry_count": retries, "latency_ms": elapsed_ms}
                return {"summary": "", "long_term_memory": ""}

        return {"summary": "", "long_term_memory": ""}

    # ── helpers ─────────────────────────────────────────────────────────────

    def _record_event(
        self, phase: str, attempt: int, decision_id: str,
        response: str | None = None,
        error: Exception | None = None, **flags: Any,
    ) -> None:
        if self._repo is None:
            return
        self._repo.add_decision_event(
            phase=phase, attempt=attempt, decision_id=decision_id,
            player_id=self._agent_id, seat=self._seat or None,
            output_sha256=hashlib.sha256(response.encode()).hexdigest() if response is not None else None,
            error_code=self._classify_error(error) if error else None,
            **self._decision_context, **flags,
        )

    def _set_provider_call_context(self, phase: str, decision_id: str, attempt: int) -> None:
        if hasattr(self._provider, "set_context"):
            self._provider.set_context(
                phase=phase, decision_id=decision_id, attempt=attempt,
                **self._decision_context,
            )

    @staticmethod
    def _classify_error(error: Exception) -> str:
        if isinstance(error, LLMProviderError):
            message = str(error).lower()
            if "empty response" in message:
                return "empty_response"
            return "provider_error"
        message = str(error)
        if "领出" in message:
            return "leader_pass"
        if "未找到 JSON" in message or "未正确闭合" in message or "JSON 解析错误" in message:
            return "json_format"
        if "缺少" in message or "必须是对象" in message or "必须是整数" in message or "必须是非空数组" in message:
            return "schema_error"
        if "不在你的手牌" in message:
            return "card_not_in_hand"
        if "无法识别牌型" in message or "合法牌型" in message:
            return "invalid_pattern"
        if "不能压过" in message:
            return "cannot_beat"
        if "叫分" in message or "'bid'" in message:
            return "invalid_bid"
        return "parse_error"

    @staticmethod
    def _append_retry_feedback(original_user: str, error: str, attempt: int) -> str:
        """Append error feedback to the user prompt for a retry attempt."""
        feedback = (
            f"\n\n---\n## 第{attempt}次重试反馈\n"
            f"上次回复有误：{error}\n"
            f"请修正错误，重新输出完整的 JSON 回复。"
        )
        return original_user + feedback

src/backend/arena/agent/memory.py:
"""MemoryManager — long-term and short-term memory for agents.

Long-term memory: persists across matches (personality, global strategy).
Short-term memory: per-match (mental state, opponent reads, self-assessment).

The tournament layer persists validated snapshots and records their provenance.
"""

from __future__ import annotations

from dataclasses import dataclass, field

MAX_SHORT_TERM_CHARS = 4000
MAX_LONG_TERM_CHARS = 8000
MAX_RETAINED_MATCHES = 8


def validate_memory_text(value: str, *, max_chars: int, allow_empty: bool = False) -> str:
    """Reject invalid updates without truncating or erasing existing experience."""
    if not isinstance(value, str):
        raise ValueError("memory must be text")
    value = value.strip()
    if not value and not allow_empty:
        raise ValueError("memory must not be empty")
    if len(value) > max_chars:
        raise ValueError("memory exceeds character limit")
    return value


@dataclass
class MemoryManager:
    """Manages short-term and long-term memory for an agent.

    Prompt memory is bounded; persistent versions live in the repository.
    """

    agent_id: str
    long_term: str = ""
    short_term: dict[str, str] = field(default_factory=dict)  # match_id → memory
    _current_match_id: str = ""
    long_term_version_id: str = ""

    def __post_init__(self) -> None:
        self.long_term = validate_memory_text(
            self.long_term, max_chars=MAX_LONG_TERM_CHARS, allow_empty=True,
        )

    # ── factory ───────────────────────────────────────────────────────────────

    @classmethod
    def with_long_term(cls, agent_id: str, long_term: str = "") -> MemoryManager:
        """Create a MemoryManager with pre-existing long-term memory."""
        return cls(agent_id=agent_id, long_term=long_term)

    # ── match lifecycle ──────────────────────────────────────────────────────

    def start_match(self, match_id: str) -> None:
        """Begin a new match. Initializes empty short-term memory."""
        if not match_id:
            raise ValueError("match id is required")
        self._current_match_id = match_id
        self.short_term[match_id] = ""
        while len(self.short_term) > MAX_RETAINED_MATCHES:
            self.short_term.pop(next(iter(self.short_term)))

    def end_match(self) -> None:
        """End the current match."""
        self._current_match_id = ""

    # ── short-term memory (per-hand reflection) ──────────────────────────────

    def get_short_term(self, match_id: str | None = None) -> str:
        """Get short-term memory for the current (or specified) match."""
        mid = match_id or self._current_match_id
        return self.short_term.get(mid, "")

    def update_short_term(self, memory: str, match_id: str | None = None) -> None:
        """Update short-term memory (called after each hand's reflection)."""
        mid = match_id or self._current_match_id
        if not mid:
            raise ValueError("start a match before updating short-term memory")
        self.short_term[mid] = validate_memory_text(memory, max_chars=MAX_SHORT_TERM_CHARS)

    # ── long-term memory (post-match summary) ────────────────────────────────

    def get_long_term(self) -> str:
        return self.long_term

    def update_long_term(self, memory: str) -> None:
        """Update long-term memory (called after match summary)."""
        self.long_term = validate_memory_text(memory, max_chars=MAX_LONG_TERM_CHARS)

src/backend/arena/agent/parser.py:
"""Output parser — parses LLM JSON responses with validation and retry feedback.

Validation tiers:
1. JSON is well-formed
2. Required fields present and correctly typed
3. Cards exist in hand (for play decisions)
4. Play forms a valid pattern (via rules.recognize)
5. Play can beat current trick (via rules.can_beat)
6. Bid is valid (0-3, > current_high_bid if > 0)
"""

from __future__ import annotations

import json
import re
from typing import Any

from ..engine.card import Card
from ..engine.hand import Hand
from ..engine.rules import InvalidPlayError, can_beat, recognize
from ..engine.trick import Trick


class ParseError(Exception):
    """Raised when LLM output cannot be parsed or is invalid.

    The message is suitable as retry feedback to the LLM.
    """
    pass


def _extract_json(text: str) -> str:
    """Extract JSON from LLM output, handling markdown code fences and extra text."""
    text = text.strip()

    # Some compatible gateways return reasoning inline instead of in a separate
    # field. Only the answer after a complete leading think block is actionable;
    # examples or abandoned actions inside reasoning are not model proposals.
    while text.lower().startswith('<think>'):
        block = re.match(r'<think>.*?</think>\s*', text, re.DOTALL | re.IGNORECASE)
        if block is None:
            raise ParseError('思考内容尚未结束，缺少最终 JSON 回复。')
        text = text[block.end():].strip()

    # Try to find JSON in markdown code fences ```json ... ```
    fence_match = re.search(r'```(?:json)?\s*\n?(.*?)\n?```', text, re.DOTALL)
    if fence_match:
        return fence_match.group(1).strip()

    # Try to find JSON object directly
    brace_start = text.find('{')
    if brace_start == -1:
        raise ParseError(
            f"输出中未找到 JSON 对象。请确保你的回复包含一个 "
            f"完整的 JSON 对象，以 {{ 开始，以 }} 结束。\n"
            f"你的输出：{text[:500]}"
        )

    # Find matching closing brace
    depth = 0
    for i in range(brace_start, len(text)):
        if text[i] == '{':
            depth += 1
        elif text[i] == '}':
            depth -= 1
            if depth == 0:
                return text[brace_start:i + 1]

    raise ParseError(
        f"JSON 对象未正确闭合。请确保回复以 {{ 开始并以 }} 结束。\n"
        f"你的输出：{text[:500]}"
    )


def _parse_json(text: str) -> dict[str, Any]:
    """Parse JSON from text, returning a dict."""
    json_str = _extract_json(text)
    try:
        result = json.loads(json_str)
    except json.JSONDecodeError as e:
        raise ParseError(
            f"JSON 解析错误：{e}。请确保输出是有效的 JSON 格式。\n"
            f"解析到的 JSON 片段：{json_str[:300]}"
        )
    if not isinstance(result, dict):
        raise ParseError("JSON 输出必须是对象（dict），不能是数组或其他类型。")
    return result


def _find_card_in_hand(card_str: str, hand: list[Card]) -> Card | None:
    """Find a Card in hand by its string representation."""
    for c in hand:
        if str(c) == card_str:
            return c
    # Try case-insensitive match
    card_lower = card_str.strip().lower()
    for c in hand:
        if str(c).lower() == card_lower:
            return c
    return None


# ── bidding parser ──────────────────────────────────────────────────────────────


def parse_bid_response(text: str, ctx_high_bid: int = 0) -> tuple[int, str]:
    """Parse a bidding response from the LLM.

    Args:
        text: Raw LLM output text.
        ctx_high_bid: Current highest bid (for validation).

    Returns:
        (bid, reasoning) tuple. bid is 0/1/2/3.

    Raises:
        ParseError: If parsing fails or the bid is invalid.
    """
    data = _parse_json(text)

    if "bid" not in data:
        raise ParseError(
            f"JSON 中缺少 'bid' 字段。请确保输出包含："
            f'{{"reasoning": "...", "bid": 0}}'
        )

    bid = data["bid"]
    if not isinstance(bid, int) and not (isinstance(bid, float) and bid == int(bid)):
        raise ParseError(
            f"'bid' 必须是整数 (0/1/2/3)，收到：{bid!r} (类型：{type(bid).__name__})"
        )
    bid = int(bid)

    if bid not in (0, 1, 2, 3):
        raise ParseError(
            f"'bid' 必须是 0（不叫）或 1/2/3（叫分），收到：{bid}"
        )

    if bid > 0 and bid <= ctx_high_bid:
        raise ParseError(
            f"你叫了 {bid} 分，但当前最高叫分已经是 {ctx_high_bid} 分。"
            f"叫分必须大于当前最高叫分（或选择不叫）。请重新考虑。"
        )

    reasoning = data.get("reasoning", "")
    return bid, reasoning


# ── playing parser ──────────────────────────────────────────────────────────────


def parse_play_response(
    text: str,
    hand_cards: list[Card],
    current_trick: Trick | None = None,
) -> tuple[list[Card], str]:
    """Parse a play response from the LLM.

    Args:
        text: Raw LLM output text.
        hand_cards: The agent's current hand cards (for card lookup).
        current_trick: The current trick to beat (None = new round leader).

    Returns:
        (cards, reasoning) tuple. Empty cards list = pass.

    Raises:
        ParseError: If parsing fails, cards not in hand, or play is illegal.
    """
    data = _parse_json(text)

    if "action" not in data:
        raise ParseError(
            f"JSON 中缺少 'action' 字段。请确保输出包含："
            f'{{"reasoning": "...", "action": {{"type": "play"|"pass", ...}}}}'
        )

    action = data["action"]
    if not isinstance(action, dict):
        raise ParseError(f"'action' 必须是对象，收到：{type(action).__name__}")

    action_type = action.get("type")
    if action_type not in ("play", "pass"):
        raise ParseError(
            f"'action.type' 必须是 'play' 或 'pass'，收到：{action_type!r}"
        )

    reasoning = data.get("reasoning", "")

    if action_type == "pass":
        if current_trick is None:
            raise ParseError("领出必须出牌，不能 pass（当前没有需要压过的牌型）。")
        return [], reasoning

    # action_type == "play"
    card_strings = action.get("cards")
    if not isinstance(card_strings, list) or len(card_strings) == 0:
        raise ParseError(
            f"'action.cards' 必须是非空数组，每个元素是卡牌字符串（如 ♠A、大王）。"
        )

    # Resolve cards from hand
    cards: list[Card] = []
    hand_copy = list(hand_cards)
    for cs in card_strings:
        if not isinstance(cs, str):
            raise ParseError(f"cards 数组中每个元素必须是字符串，收到：{cs!r}")
        found = _find_card_in_hand(cs, hand_copy)
        if found is None:
            raise ParseError(
                f"卡牌 '{cs}' 不在你的手牌中。你的手牌：\n"
                f"{' '.join(str(c) for c in hand_cards)}\n"
                f"请检查卡牌字符串是否与手牌完全一致。"
            )
        cards.append(found)
        hand_copy.remove(found)

    # Validate the play
    try:
        trick = recognize(cards)
    except InvalidPlayError as e:
        raise ParseError(
            f"你出的牌 {' '.join(str(c) for c in cards)} 不构成合法的斗地主牌型：{e}\n"
            f"请检查牌型是否符合15种合法牌型之一。"
        )

    if current_trick is not None:
        if not can_beat(trick, current_trick):
            raise ParseError(
                f"你出的 {trick.display()}（{trick.pattern.value}）"
                f"无法压下当前牌型 {current_trick.display()}（{current_trick.pattern.value}）。\n"
                f"请出更大的同类型牌型，或使用炸弹/火箭，或选择 Pass。"
            )

    return cards, reasoning


# ── reflection parser ───────────────────────────────────────────────────────────


def parse_reflection_response(text: str) -> dict[str, str]:
    """Parse a reflection response from the LLM.

    Returns:
        {'reflection': str, 'short_term_memory': str}

    Raises:
        ParseError: If parsing fails.
    """
    data = _parse_json(text)

    missing = []
    for field in ("reflection", "short_term_memory"):
        if field not in data:
            missing.append(field)

    if missing:
        raise ParseError(
            f"JSON 中缺少字段：{', '.join(missing)}。"
            f"请确保输出包含 'reflection' 和 'short_term_memory'。"
        )

    return {
        "reflection": str(data.get("reflection", "")),
        "short_term_memory": str(data.get("short_term_memory", "")),
    }


# ── summary parser ──────────────────────────────────────────────────────────────


def parse_summary_response(text: str) -> dict[str, str]:
    """Parse a match summary response from the LLM.

    Returns:
        {'summary': str, 'long_term_memory': str}

    Raises:
        ParseError: If parsing fails.
    """
    data = _parse_json(text)

    missing = []
    for field in ("summary", "long_term_memory"):
        if field not in data:
            missing.append(field)

    if missing:
        raise ParseError(
            f"JSON 中缺少字段：{', '.join(missing)}。"
            f"请确保输出包含 'summary' 和 'long_term_memory'。"
        )

    return {
        "summary": str(data.get("summary", "")),
        "long_term_memory": str(data.get("long_term_memory", "")),
    }

src/backend/arena/agent/random_agent.py:
"""Random agent — makes random (but legal) decisions for baseline testing."""

from __future__ import annotations

import random

from ..engine.card import Card
from ..engine.rules import can_beat, recognize
from ..engine.trick import Trick
from .base import Agent, AgentContext
from .memory import MemoryManager


class RandomAgent:
    """An agent that makes random but rule-compliant decisions.

    Used as a baseline opponent and for tournament engine testing.
    """

    def __init__(self, agent_id: str, seat: str = "", seed: int | None = None) -> None:
        self._agent_id = agent_id
        self._seat = seat
        self._rng = random.Random(seed)
        self._memory = MemoryManager(agent_id=agent_id)

    @property
    def agent_id(self) -> str:
        return self._agent_id

    @property
    def seat(self) -> str:
        return self._seat

    @seat.setter
    def seat(self, value: str) -> None:
        self._seat = value

    @property
    def memory(self) -> MemoryManager:
        return self._memory

    async def decide_bid(self, ctx: AgentContext) -> int:
        """Random bid: 50% pass, otherwise random from valid options."""
        options = [b for b in (0, 1, 2, 3) if b == 0 or b > ctx.current_high_bid]
        return self._rng.choice(options)

    async def decide_play(self, ctx: AgentContext) -> list[Card]:
        """Pick a random legal play.

        If must follow a pattern: find all legal plays that beat current_trick,
        pick one randomly. If none exist, pass.
        If leader (no current_trick): pick a random play from all possible plays.
        """
        if ctx.current_trick is None:
            return self._random_leader_play(ctx)
        else:
            return self._random_follow_play(ctx)

    def _random_leader_play(self, ctx: AgentContext) -> list[Card]:
        """As round leader, pick any valid play from hand."""
        hand = list(ctx.hand_cards)
        if not hand:
            return []
        # Try various play sizes — prefer simpler plays
        # Build a list of all possible single plays, pairs, trios, etc.
        candidates: list[list[Card]] = []

        # Single cards
        for c in hand:
            candidates.append([c])

        # Pairs and trios
        rank_counts: dict[int, list[Card]] = {}
        for c in hand:
            rank_counts.setdefault(c.rank.value, []).append(c)
        for cards in rank_counts.values():
            if len(cards) >= 2:
                candidates.append(cards[:2])
            if len(cards) >= 3:
                candidates.append(cards[:3])
            if len(cards) >= 4:
                candidates.append(cards[:4])

        if not candidates:
            return [hand[-1]]  # fallback

        choice = self._rng.choice(candidates)
        # Verify
        try:
            recognize(choice)
            return choice
        except Exception:
            return [hand[-1]]

    def _random_follow_play(self, ctx: AgentContext) -> list[Card]:
        """Must follow current pattern. Find legal plays or pass."""
        hand = list(ctx.hand_cards)
        target = ctx.current_trick
        if target is None:
            return []

        # Generate candidate plays from hand that could beat target
        candidates = self._find_beating_plays(hand, target)

        if not candidates:
            return []  # pass

        # Prefer passing sometimes (~30%)
        if self._rng.random() < 0.3:
            return []

        choice = self._rng.choice(candidates)
        try:
            recognize(choice)
            return choice
        except Exception:
            return []

    def _find_beating_plays(self, hand: list[Card], target: Trick) -> list[list[Card]]:
        """Find all legal plays from hand that beat the target trick."""
        candidates: list[list[Card]] = []

        # Group by rank
        rank_groups: dict[int, list[Card]] = {}
        for c in hand:
            rank_groups.setdefault(c.rank.value, []).append(c)

        # Only generates singles for SINGLE target (straight/airplane/other complex
        # pattern candidates are not generated). When the target is a complex pattern,
        # the agent can only respond with bombs, rockets, or pass. Acceptable for baseline.
        if target.pattern.value in ("单张",):
            for c in hand:
                trial = [c]
                try:
                    trick = recognize(trial)
                    if can_beat(trick, target):
                        candidates.append(trial)
                except Exception:
                    pass

        # Try pairs that beat target
        for cards in rank_groups.values():
            if len(cards) >= 2:
                trial = cards[:2]
                try:
                    trick = recognize(trial)
                    if can_beat(trick, target):
                        candidates.append(trial)
                except Exception:
                    pass

        # Try trios
        for cards in rank_groups.values():
            if len(cards) >= 3:
                trial = cards[:3]
                try:
                    trick = recognize(trial)
                    if can_beat(trick, target):
                        candidates.append(trial)
                except Exception:
                    pass

        # Try bombs
        for cards in rank_groups.values():
            if len(cards) >= 4:
                trial = cards[:4]
                try:
                    trick = recognize(trial)
                    if can_beat(trick, target):
                        candidates.append(trial)
                except Exception:
                    pass

        # Try rocket
        has_big = any(c.rank.display == "大王" for c in hand)
        has_small = any(c.rank.display == "小王" for c in hand)
        if has_big and has_small:
            from ..engine.card import Card as C, Rank, Suit
            rocket = [c for c in hand if c.rank.display in ("大王", "小王")]
            if len(rocket) >= 2:
                rocket = rocket[:2]
                try:
                    trick = recognize(rocket)
                    if can_beat(trick, target):
                        candidates.append(rocket)
                except Exception:
                    pass

        return candidates

    async def reflect(self, ctx: AgentContext) -> dict[str, str]:
        """No-op reflection for random agent."""
        return {"reflection": "", "short_term_memory": ""}

    async def summarize(self, ctx: AgentContext) -> dict[str, str]:
        """No-op summary for random agent."""
        return {"summary": "", "long_term_memory": ""}

src/backend/arena/agent/tools/plans.py:
"""Compare proposed plays by bounded, exact static hand partition search."""

from __future__ import annotations

from collections import Counter
from math import ceil
from typing import Any

from ...engine.card import Card, Rank
from ...engine.rules import InvalidPlayError, can_beat, recognize
from ...engine.trick import PatternType
from ..base import AgentContext
from .plays import (
    Counts, EMPTY_COUNTS, PATTERN_COVERAGE, Play, SearchBudget,
    SearchLimitExceeded, cards_from_counts, counts_from_cards, generate_plays,
)

DEFAULT_TIME_LIMIT_MS = 90.0
DEFAULT_MAX_NODES = 20_000


def _fits(play: Play, state: Counts) -> bool:
    return all(n <= state[i] for i, n in play.items)


def _subtract(state: Counts, play: Play) -> Counts:
    return tuple(n - used for n, used in zip(state, play.counts))


def _preserves(play: Play, original: Counts) -> bool:
    for i, n in enumerate(original[:13]):
        if n == 4 and play.counts[i]:
            if play.trick.pattern != PatternType.BOMB or play.counts[i] != 4:
                return False
    if original[13] and original[14] and (play.counts[13] or play.counts[14]):
        return play.trick.pattern == PatternType.ROCKET
    return True


def _rank_partition(state: Counts) -> tuple[Counts, ...]:
    """A legal upper-bound witness, available even when generation times out."""
    result = []
    for i, n in enumerate(state[:13]):
        if n:
            group = [0] * 15
            group[i] = n
            result.append(tuple(group))
    if state[13] or state[14]:
        result.append((0,) * 13 + state[13:])
    return tuple(result)


def _partition(
    state: Counts, plays: list[Play], generation_complete: bool,
    budget: SearchBudget,
) -> tuple[tuple[Counts, ...], int, bool]:
    """Iterative depth search with a fixed anchor and failed-state memoization.

    Every partition includes a group containing the lowest remaining rank.
    Restricting the next choice to that group removes permutations without
    excluding any partition. Completing depth k proves a lower bound k+1.
    """
    if not any(state):
        return (), 0, True
    witness = _rank_partition(state)
    usable = [play for play in plays if _fits(play, state)]
    usable.sort(key=lambda play: (-play.size, play.counts))
    greedy: list[Counts] = []
    rest = state
    for play in usable:
        while _fits(play, rest):
            greedy.append(play.counts)
            rest = _subtract(rest, play)
    greedy.extend(_rank_partition(rest))
    if len(greedy) < len(witness):
        witness = tuple(greedy)
    if len(witness) <= 1:
        return witness, len(witness), True
    if not generation_complete:
        # Missing moves may improve any proposed lower bound above one.
        return witness, 1, False

    by_rank = [[play for play in usable if play.counts[i]] for i in range(15)]
    complete_plays = {play.counts for play in usable}
    maximum = max(play.size for play in usable)
    lower = ceil(sum(state) / maximum)
    failed: set[tuple[Counts, int]] = set()

    def search(current: Counts, slots: int) -> tuple[Counts, ...] | None:
        budget.tick()
        if current == EMPTY_COUNTS:
            return ()
        if slots <= 0 or sum(current) > slots * maximum:
            return None
        if current in complete_plays:
            return (current,)
        if slots == 1:
            return None
        key = (current, slots)
        if key in failed:
            return None
        anchor = next(i for i, n in enumerate(current) if n)
        for play in by_rank[anchor]:
            budget.tick()
            if not _fits(play, current):
                continue
            remaining = _subtract(current, play)
            result = search(remaining, slots - 1)
            if result is not None:
                return (play.counts,) + result
        failed.add(key)
        return None

    try:
        while lower < len(witness):
            solution = search(state, lower)
            if solution is not None:
                return solution, lower, True
            lower += 1
    except SearchLimitExceeded:
        return witness, lower, False
    return witness, lower, True


def _parse_action(ctx: AgentContext, value: Any, preserve: bool) -> list[Card]:
    if not isinstance(value, dict) or set(value) != {"cards"}:
        raise ValueError("each action must contain only a cards array")
    strings = value["cards"]
    if not isinstance(strings, list) or len(strings) > 20 or any(
        not isinstance(card, str) for card in strings
    ):
        raise ValueError("cards must be an array of at most 20 full card strings")
    if len(set(strings)) != len(strings):
        raise ValueError("an action cannot use the same physical card twice")
    hand = {str(card): card for card in ctx.hand_cards}
    if any(card not in hand for card in strings):
        raise ValueError("action cards must be full card strings from your hand")
    cards = [hand[string] for string in strings]
    if not cards:
        if ctx.current_trick is None:
            raise ValueError("cannot pass when leading a new trick")
        return cards
    trick = recognize(cards)
    if Counter(trick.all_cards) != Counter(cards):
        raise ValueError("pattern does not account for every submitted card")
    if not can_beat(trick, ctx.current_trick):
        raise ValueError("action does not beat the current trick")
    if preserve:
        candidate = Play(counts_from_cards(cards), tuple(cards), trick, len(cards), ())
        if not _preserves(candidate, counts_from_cards(ctx.hand_cards)):
            raise ValueError("preserve_bombs requires bombs/rocket as standalone plays")
    return cards


def compare_hand_plans(ctx: AgentContext, arguments: dict[str, Any]) -> dict[str, Any]:
    """Return legal remaining-card partitions and honest optimization bounds.

    No turn-by-turn or hidden-hand simulation is performed. Fewer static
    groups does not imply fewer actual turns or a higher probability of winning.
    """
    if not isinstance(arguments, dict) or set(arguments) - {"actions", "constraints"}:
        raise ValueError("expected actions and optional constraints")
    actions = arguments.get("actions")
    if not isinstance(actions, list) or not 1 <= len(actions) <= 3:
        raise ValueError("actions must contain one to three proposed plays")
    constraints = arguments.get("constraints", {})
    if not isinstance(constraints, dict) or set(constraints) - {"preserve_bombs"}:
        raise ValueError("only preserve_bombs is supported as a constraint")
    preserve = constraints.get("preserve_bombs", False)
    if type(preserve) is not bool:
        raise ValueError("preserve_bombs must be boolean")
    if not 0 <= len(ctx.hand_cards) <= 20 or len(set(ctx.hand_cards)) != len(ctx.hand_cards):
        raise ValueError("own hand must contain at most 20 distinct cards")

    budget = SearchBudget(DEFAULT_MAX_NODES, DEFAULT_TIME_LIMIT_MS)
    original = counts_from_cards(ctx.hand_cards)
    prepared: list[list[Card] | None] = []
    results: list[dict[str, Any]] = []
    for index, action in enumerate(actions):
        try:
            cards = _parse_action(ctx, action, preserve)
        except (ValueError, InvalidPlayError) as exc:
            prepared.append(None)
            results.append({"index": index, "valid": False, "error": str(exc)})
        else:
            prepared.append(cards)
            results.append({"index": index, "valid": True, "cards": [str(c) for c in cards]})

    plays: list[Play] = []
    generation_complete = True
    if any(cards is not None for cards in prepared):
        try:
            for play in generate_plays(original, max_size=len(ctx.hand_cards), budget=budget):
                if not preserve or _preserves(play, original):
                    plays.append(play)
        except SearchLimitExceeded:
            generation_complete = False

    # Candidates differing only in suits have the same partition problem.
    partitions: dict[Counts, tuple[tuple[Counts, ...], int, bool]] = {}
    for cards, result in zip(prepared, results):
        if cards is None:
            continue
        used = set(cards)
        remaining = [card for card in ctx.hand_cards if card not in used]
        state = counts_from_cards(remaining)
        if state not in partitions:
            partitions[state] = _partition(state, plays, generation_complete, budget)
        partition, lower, exact = partitions[state]
        pool = list(remaining)
        groups = []
        for group in partition:
            group_cards = cards_from_counts(group, pool)
            selected = set(group_cards)
            pool = [card for card in pool if card not in selected]
            trick = recognize(group_cards)
            groups.append({"cards": [str(c) for c in group_cards],
                           "pattern": trick.pattern.value})
        played_counts = counts_from_cards(cards)
        broken = [{"rank": Rank(i + 3).display, "before": n,
                   "played": played_counts[i], "remaining": state[i]}
                  for i, n in enumerate(original)
                  if n >= 2 and 0 < played_counts[i] < n]
        if original[13] and original[14] and played_counts[13] != played_counts[14]:
            broken.append({"rank": "小王+大王", "before": 2,
                           "played": 1, "remaining": 1})
        result.update({
            "remaining_cards": [str(c) for c in remaining], "groups": groups,
            "lower_bound": lower, "upper_bound": len(groups),
            "minimum_groups": len(groups) if exact else None,
            "exact": exact, "truncated": not exact,
            "singletons": [group["cards"][0] for group in groups
                           if group["pattern"] == PatternType.SINGLE.value],
            "broken_groups": broken,
        })

    return {
        "tool": "compare_hand_plans", "plans": results,
        "constraints": {"preserve_bombs": preserve},
        "semantics": "Static partition only; group count is not actual turns or win probability.",
        "coverage": PATTERN_COVERAGE,
        "stats": {"nodes": budget.nodes, "elapsed_ms": round(budget.elapsed_ms, 3),
                  "node_limit": budget.max_nodes, "time_limit_ms": budget.time_limit_ms,
                  "generation_complete": generation_complete,
                  "stop_reason": budget.reason},
    }

src/backend/arena/agent/tools/plays.py:
"""Bounded enumeration of complete plays, with suits factored out.

The fifteen coordinates are ranks 3 through big joker. A coordinate tuple
represents one play regardless of which equivalent suits are used. Templates
follow this repository's rules (in particular, airplane single wings have
distinct ranks), and every result is checked by the authoritative recognizer.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from itertools import combinations
from time import perf_counter
from typing import Iterable, Iterator

from ...engine.card import ALL_CARDS, Card
from ...engine.rules import InvalidPlayError, recognize
from ...engine.trick import Trick

Counts = tuple[int, ...]
EMPTY_COUNTS: Counts = (0,) * 15
PATTERN_COVERAGE = "all 15 engine patterns with complete card consumption"
_RANK_CARDS = tuple(
    tuple(sorted(c for c in ALL_CARDS if c.rank.value == rank))
    for rank in range(3, 18)
)


class SearchLimitExceeded(RuntimeError):
    """A bounded search stopped; its partial results are still usable."""


@dataclass
class SearchBudget:
    max_nodes: int = 20_000
    time_limit_ms: float = 90.0
    nodes: int = 0
    exhausted: bool = False
    reason: str | None = None
    _started: float = field(default_factory=perf_counter, repr=False)

    @property
    def elapsed_ms(self) -> float:
        return (perf_counter() - self._started) * 1000

    def tick(self) -> None:
        # Check the clock at each expansion, including template enumeration.
        # This is a cooperative limit, not a real-time scheduling guarantee.
        if self.exhausted or self.nodes >= self.max_nodes:
            self.exhausted = True
            self.reason = self.reason or "node_limit"
            raise SearchLimitExceeded(self.reason)
        if self.elapsed_ms >= self.time_limit_ms:
            self.exhausted = True
            self.reason = "time_limit"
            raise SearchLimitExceeded(self.reason)
        self.nodes += 1


@dataclass(frozen=True, slots=True)
class Play:
    counts: Counts
    cards: tuple[Card, ...]
    trick: Trick
    size: int
    items: tuple[tuple[int, int], ...]


def counts_from_cards(cards: Iterable[Card]) -> Counts:
    counts = [0] * 15
    for card in cards:
        counts[card.rank.value - 3] += 1
    return tuple(counts)


def _validate_counts(counts: Counts) -> None:
    if len(counts) != 15 or any(
        type(n) is not int or n < 0 or n > (4 if i < 13 else 1)
        for i, n in enumerate(counts)
    ):
        raise ValueError("counts must contain 15 physical deck rank counts")


def cards_from_counts(counts: Counts, pool: Iterable[Card] | None = None) -> list[Card]:
    """Materialize counts, optionally selecting actual cards from one's hand.

    With no pool the suits are synthetic and must never be reported as an
    opponent's real cards. Hidden-information callers should return ranks only.
    """
    _validate_counts(counts)
    if pool is None:
        buckets = _RANK_CARDS
    else:
        mutable: list[list[Card]] = [[] for _ in range(15)]
        for card in sorted(pool):
            mutable[card.rank.value - 3].append(card)
        buckets = mutable
    if any(len(buckets[i]) < n for i, n in enumerate(counts)):
        raise ValueError("card pool does not contain the requested ranks")
    return [card for i, n in enumerate(counts) for card in buckets[i][:n]]


def _templates(counts: Counts, minimum: int, maximum: int) -> Iterator[Counts]:
    def make(core: Iterable[int], multiplicity: int,
             wings: Iterable[int] = (), wing_size: int = 1) -> Counts:
        result = [0] * 15
        for rank in core:
            result[rank] = multiplicity
        for rank in wings:
            result[rank] = wing_size
        return tuple(result)

    # Same-rank plays, including single jokers.
    for rank, available in enumerate(counts):
        for n in range(max(1, minimum), min(available, maximum) + 1):
            yield make((rank,), n)
    if minimum <= 2 <= maximum and counts[13] and counts[14]:
        yield make((13, 14), 1)

    for rank, available in enumerate(counts[:13]):
        if available >= 3:
            for wing_size in (1, 2):
                if minimum <= 3 + wing_size <= maximum:
                    for other, other_count in enumerate(counts):
                        if other != rank and other_count >= wing_size:
                            yield make((rank,), 3, (other,), wing_size)
        if available == 4:
            for wing_size, wing_count in ((1, 2), (2, 1), (2, 2)):
                if minimum <= 4 + wing_size * wing_count <= maximum:
                    choices = [i for i, n in enumerate(counts)
                               if i != rank and n >= wing_size]
                    for wings in combinations(choices, wing_count):
                        yield make((rank,), 4, wings, wing_size)

    # Sequences never include 2 or jokers. Each prefix is a separate play.
    for multiplicity, shortest in ((1, 5), (2, 3), (3, 2)):
        for start in range(12):
            for end in range(start, 12):
                if counts[end] < multiplicity:
                    break
                length = end - start + 1
                if multiplicity * length > maximum:
                    break
                if length < shortest:
                    continue
                core = range(start, end + 1)
                if minimum <= multiplicity * length <= maximum:
                    yield make(core, multiplicity)
                if multiplicity != 3:
                    continue
                for wing_size in (1, 2):
                    if not minimum <= (3 + wing_size) * length <= maximum:
                        continue
                    choices = [i for i, n in enumerate(counts)
                               if not start <= i <= end and n >= wing_size]
                    for wings in combinations(choices, length):
                        yield make(core, 3, wings, wing_size)


def generate_plays(
    counts: Counts, *, max_size: int | None = None,
    exact_size: int | None = None, budget: SearchBudget | None = None,
) -> Iterator[Play]:
    """Yield all complete legal rank patterns, or raise at the search limit.

    Completeness concerns patterns for which recognize consumes every input
    card. The additional coverage check guards against recognizer regressions
    that might accept a partial airplane and omit extra cards from its Trick.
    """
    _validate_counts(counts)
    for size in (max_size, exact_size):
        if size is not None and (type(size) is not int or size < 0):
            raise ValueError("size limits must be nonnegative integers")
    maximum = min(sum(counts), 20 if max_size is None else max_size)
    minimum = 1
    if exact_size is not None:
        minimum = exact_size
        maximum = min(maximum, exact_size)
    if maximum < max(1, minimum):
        return
    active_budget = budget if budget is not None else SearchBudget()
    for candidate in _templates(counts, minimum, maximum):
        active_budget.tick()
        cards = tuple(cards_from_counts(candidate))
        try:
            trick = recognize(cards)
        except InvalidPlayError:
            continue
        if len(trick.all_cards) != len(cards) or set(trick.all_cards) != set(cards):
            continue
        yield Play(candidate, cards, trick, len(cards),
                   tuple((i, n) for i, n in enumerate(candidate) if n))

src/backend/arena/agent/tools/registry.p:
"""A bounded tool allowlist bound to one player's immutable decision snapshot."""
from __future__ import annotations

import copy
import hashlib
import json
import time
from dataclasses import asdict

from ..base import AgentContext
from ...engine.card import Card, Rank
from ...engine.rules import recognize
from .plays import cards_from_counts, counts_from_cards
from .plans import compare_hand_plans
from .threats import analyze_threat

TOOL_VERSION = "1"
MAX_TOOL_CALLS = 2
MAX_ARGUMENT_CHARS = 4096
MAX_RESULT_CHARS = 8000
_CARD_ARRAY = {"type": "array", "items": {"type": "string", "maxLength": 8}, "maxItems": 20}
TOOL_SCHEMAS = [
    {
        "name": "compare_hand_plans",
        "description": "比较1至3个合法候选出法后的静态剩牌分组。可要求炸弹/火箭作为独立牌组使用。分组数忽略对手干扰，不是实际出完轮数或胜率；仅exact=true时minimum_groups是最优值。",
        "parameters": {
            "type": "object", "additionalProperties": False, "required": ["actions"],
            "properties": {
                "actions": {"type": "array", "minItems": 1, "maxItems": 3,
                    "items": {"type": "object", "additionalProperties": False,
                        "required": ["cards"], "properties": {"cards": _CARD_ARRAY}}},
                "constraints": {"type": "object", "additionalProperties": False,
                    "properties": {"preserve_bombs": {"type": "boolean"}}},
            },
        },
    },
    {
        "name": "analyze_threat",
        "description": "用公开信息检验另一个活跃玩家是否可能一手走完(can_finish)或压过目标牌(can_beat)。可指定自家合法候选cards，否则使用场上牌；无场上牌时can_finish假设获得自由领出权。possible只有假设可行性，ruled_out为完整排除，unknown未算完或信息不足；不返回概率，不推断实际轮次。",
        "parameters": {
            "type": "object", "additionalProperties": False,
            "required": ["event", "target_seat"],
            "properties": {
                "event": {"type": "string", "enum": ["can_finish", "can_beat"]},
                "target_seat": {"type": "string", "enum": ["S", "E", "N", "W"]},
                "cards": {**_CARD_ARRAY, "minItems": 1},
            },
        },
    },
]
TOOL_GUIDANCE = """\n## 可选的本地算法工具
只在需要比较具体出法或检验威胁时调用工具，也可以直接给出最终出牌JSON。
每次决策最多调用两次工具，工具调用也消耗本次模型轮数和时间预算。
工具结果中的假设手牌不是实际手牌；unknown和搜索未完成都不能解释为安全。
最终出牌仍须遵循原JSON格式，不能把工具结果当作已执行的动作。
"""


def canonical(value) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def digest(value: str) -> str:
    return hashlib.sha256(value.encode()).hexdigest()


def _public_snapshot(ctx: AgentContext) -> AgentContext:
    """Explicit allowlist: no reflection hands, other table, seed or reasoning.

    Opponent suit data present in the internal context is removed before any
    algorithm or observation hash sees it. Own actual cards remain usable.
    """
    history = []
    def rank_label(card):
        if isinstance(card, Card):
            return card.rank.display
        try:
            return Rank.from_display(card).display
        except (ValueError, TypeError):
            return Card.from_string(card).rank.display

    for record in ctx.play_history:
        history.append({
            "seat": record.get("seat"), "action_type": record.get("action_type"),
            "cards": [rank_label(card) for card in record.get("cards") or []],
        })
    trick = ctx.current_trick
    if trick is not None:
        trick = recognize(cards_from_counts(counts_from_cards(trick.all_cards)))
    return AgentContext(
        seat=ctx.seat, role=ctx.role, hand_cards=list(ctx.hand_cards), hand_size=ctx.hand_size,
        dizhu_cards=tuple(ctx.dizhu_cards) if ctx.dizhu_cards is not None else None,
        play_history=history, current_trick=trick, trick_leader=ctx.trick_leader,
        landlord=ctx.landlord, active_players=list(ctx.active_players),
        player_hand_sizes=dict(ctx.player_hand_sizes),
    )


def _unique_object(pairs):
    value = {}
    for key, item in pairs:
        if key in value:
            raise ValueError("duplicate JSON object key")
        value[key] = item
    return value


def _validate(value, schema):
    kind = schema["type"]
    if kind == "object":
        if not isinstance(value, dict):
            raise ValueError("expected an object")
        props = schema.get("properties", {})
        if set(value) - set(props) or set(schema.get("required", ())) - set(value):
            raise ValueError("unknown or missing tool arguments")
        for key, item in value.items():
            _validate(item, props[key])
    elif kind == "array":
        if not isinstance(value, list) or not schema.get("minItems", 0) <= len(value) <= schema["maxItems"]:
            raise ValueError("array length exceeds tool limits")
        for item in value:
            _validate(item, schema["items"])
    elif kind == "string":
        if not isinstance(value, str) or len(value) > schema.get("maxLength", 100):
            raise ValueError("invalid string argument")
        if "enum" in schema and value not in schema["enum"]:
            raise ValueError("invalid argument choice")
    elif kind == "boolean" and type(value) is not bool:
        raise ValueError("expected a boolean")


class ToolRegistry:
    def __init__(self, ctx: AgentContext):
        self._ctx = _public_snapshot(ctx)
        # default=str handles Card / Trick without exposing forbidden fields.
        encoded = json.dumps(asdict(self._ctx), default=str, ensure_ascii=False, sort_keys=True)
        self.state_hash = digest(encoded)
        self.calls = 0
        self._cache = {}

    def execute(self, name: str, raw_arguments: str) -> dict:
        started = time.perf_counter()
        self.calls += 1
        response = {"tool": name, "version": TOOL_VERSION, "state_hash": self.state_hash,
                    "cached": False}
        try:
            if self.calls > MAX_TOOL_CALLS:
                raise ValueError("tool call limit exceeded")
            schemas = {schema["name"]: schema["parameters"] for schema in TOOL_SCHEMAS}
            if name not in schemas:
                raise ValueError("unknown tool")
            if not isinstance(raw_arguments, str) or len(raw_arguments) > MAX_ARGUMENT_CHARS:
                raise ValueError("tool arguments exceed size limit")
            arguments = json.loads(raw_arguments, object_pairs_hook=_unique_object)
            _validate(arguments, schemas[name])
            key = (name, canonical(arguments))
            if key in self._cache:
                data = copy.deepcopy(self._cache[key])
                response["cached"] = True
            else:
                function = {"compare_hand_plans": compare_hand_plans, "analyze_threat": analyze_threat}[name]
                data = function(self._ctx, arguments)
                if len(canonical(data)) > MAX_RESULT_CHARS - 500:
                    raise ValueError("tool result exceeds size limit")
                self._cache[key] = copy.deepcopy(data)
            response.update(ok=True, data=data)
        except (ValueError, TypeError, RecursionError) as exc:
            response.update(ok=False, error={"code": "invalid_tool_request", "message": str(exc)[:240]})
        response["elapsed_ms"] = round((time.perf_counter() - started) * 1000, 3)
        return response

src/backend/arena/agent/tools/threats.py:
"""Public-information feasibility checks, without guessing hidden hands.

Rather than enumerating deals, enumerate legal plays and ask whether each can
be extended to a complete allocation of the unseen cards. The remaining
constraints are per-rank lower bounds and hand capacities, so that extension
check is linear in the fifteen ranks. Passes add no ownership constraints.
"""

from __future__ import annotations

from dataclasses import dataclass
from time import perf_counter
from typing import TYPE_CHECKING

from ...engine.card import Card, Rank, SEATS
from ...engine.rules import InvalidPlayError, can_beat, recognize
from ...engine.trick import PatternType, Trick
from .plays import (
    Counts,
    EMPTY_COUNTS,
    SearchBudget,
    SearchLimitExceeded,
    counts_from_cards,
    generate_plays,
)

if TYPE_CHECKING:
    from ..base import AgentContext

MAX_SEARCH_NODES = 20_000
TIME_LIMIT_MS = 80.0
_DECK_COUNTS: Counts = (4,) * 13 + (1, 1)
_SCOPE = (
    "只检验符合公开信息的点数分配是否存在；假设牌不是实际手牌，"
    "possible 不表示概率或一定能赢，也不推断轮次、领出权或其他玩家的行动。"
    "Pass 不作为缺少可压牌的证据。"
)


class _PublicInformationError(ValueError):
    """The observation is incomplete or contradicts a 54-card allocation."""


@dataclass(frozen=True)
class _Observation:
    pool: Counts
    landlord_minimum: Counts
    sizes: dict[str, int]


def _rank_of(value: object) -> Rank:
    # Opponent Card objects may carry suits internally. Only their ranks enter
    # this tool: even physical-card uniqueness checks would reveal extra info.
    if isinstance(value, Card):
        return value.rank
    if isinstance(value, str):
        try:
            return Rank.from_display(value)
        except ValueError:
            return Card.from_string(value).rank
    raise ValueError("history cards must contain cards or rank strings")


def _observe(ctx: AgentContext) -> _Observation:
    active = ctx.active_players
    if (
        len(active) != 3 or len(set(active)) != 3
        or any(seat not in SEATS for seat in active)
        or ctx.seat not in active or ctx.landlord not in active
    ):
        raise _PublicInformationError("需要三个有效活跃座位和已确定的地主。")
    sizes = ctx.player_hand_sizes
    if not isinstance(sizes, dict) or any(seat not in SEATS for seat in sizes):
        raise _PublicInformationError("公开剩余张数的座位无效。")
    for seat in SEATS:
        size = sizes.get(seat, 0)
        maximum = 20 if seat == ctx.landlord else 17
        if type(size) is not int or not 0 <= size <= maximum:
            raise _PublicInformationError("公开剩余张数无效。")
        if seat in active and size == 0:
            raise _PublicInformationError("活跃玩家已有零张手牌，不属于进行中的对战局面。")
        if seat not in active and size != 0:
            raise _PublicInformationError("闲家不应持有对战手牌。")
    if (
        type(ctx.hand_size) is not int or ctx.hand_size != len(ctx.hand_cards)
        or ctx.hand_size != sizes[ctx.seat]
        or any(not isinstance(card, Card) for card in ctx.hand_cards)
        or len(set(ctx.hand_cards)) != len(ctx.hand_cards)
    ):
        raise _PublicInformationError("自己的手牌与公开剩余张数不一致。")

    played = {seat: [0] * 15 for seat in active}
    for record in ctx.play_history:
        if not isinstance(record, dict) or record.get("seat") not in played:
            raise _PublicInformationError("出牌历史包含无效座位。")
        cards = record.get("cards") or []
        action = record.get("action_type")
        if action == "pass" and not cards:
            continue
        if action != "play" or not isinstance(cards, (list, tuple)) or not cards:
            raise _PublicInformationError("出牌历史缺少可计数的公开牌。")
        try:
            for card in cards:
                played[record["seat"]][_rank_of(card).value - 3] += 1
        except (ValueError, TypeError, IndexError):
            raise _PublicInformationError("出牌历史包含无法识别的点数。") from None

    for seat in active:
        initial_size = 20 if seat == ctx.landlord else 17
        if sum(played[seat]) + sizes[seat] != initial_size:
            raise _PublicInformationError("出牌历史与剩余张数不闭合，不能完整排除隐藏牌组合。")
    own = counts_from_cards(ctx.hand_cards)
    pool = tuple(
        _DECK_COUNTS[i] - own[i] - sum(played[seat][i] for seat in active)
        for i in range(15)
    )
    if any(n < 0 for n in pool) or sum(pool) != sum(
        sizes[seat] for seat in active if seat != ctx.seat
    ):
        raise _PublicInformationError("公开牌的点数计数与一副 54 张牌不一致。")

    bottom = ctx.dizhu_cards
    if (
        bottom is None or len(bottom) != 3
        or any(not isinstance(card, Card) for card in bottom)
        or len(set(bottom)) != 3
    ):
        raise _PublicInformationError("需要三张已公开且不重复的底牌。")
    bottom_counts = counts_from_cards(bottom)
    # Bottom cards already belong to a live hand or public play. Never subtract
    # them from the pool a second time. A landlord play of the same rank could
    # have consumed a bottom card irrespective of its hidden suit.
    minimum = tuple(
        max(0, bottom_counts[i] - played[ctx.landlord][i]) for i in range(15)
    )
    landlord_available = own if ctx.landlord == ctx.seat else pool
    if (
        sum(minimum) > sizes[ctx.landlord]
        or any(minimum[i] > landlord_available[i] for i in range(15))
    ):
        raise _PublicInformationError("底牌的地主点数下界与剩余手牌不一致。")
    return _Observation(pool, minimum, dict(sizes))


def _target_trick(ctx: AgentContext, arguments: dict) -> Trick | None:
    if "cards" not in arguments:
        return ctx.current_trick
    values = arguments["cards"]
    if not isinstance(values, list) or not values or len(values) > 20:
        raise ValueError("cards 必须是非空的完整自家出牌数组，最多 20 张。")
    if any(not isinstance(card, str) for card in values):
        raise ValueError("cards 中每张牌必须采用完整牌面字符串，例如 ♠10 或 大王。")
    try:
        cards = [Card.from_string(value) for value in values]
    except ValueError:
        raise ValueError("cards 包含无效的完整牌面字符串。") from None
    if len(set(cards)) != len(cards) or any(card not in ctx.hand_cards for card in cards):
        raise ValueError("cards 不得重复，且必须全部在自己的当前手牌中。")
    try:
        trick = recognize(cards)
    except InvalidPlayError:
        raise ValueError("cards 不构成合法的完整出牌。") from None
    if len(trick.all_cards) != len(cards) or not can_beat(trick, ctx.current_trick):
        raise ValueError("cards 必须是能压过当前牌型的合法完整出牌。")
    return trick


def _extend_hand(
    play: Counts,
    pool: Counts,
    target_minimum: Counts,
    reserved_for_others: Counts,
    target_size: int,
    other_size: int,
) -> Counts | None:
    """Prove existence and construct a target hand, without enumerating deals.

    Once mandatory cards are assigned, every remaining rank is free to go to
    either side. Coordinate capacity plus total capacity is therefore both
    necessary and sufficient; greedy filling supplies an explicit witness.
    """
    hand = [max(play[i], target_minimum[i]) for i in range(15)]
    if (
        sum(hand) > target_size or sum(reserved_for_others) > other_size
        or any(hand[i] + reserved_for_others[i] > pool[i] for i in range(15))
    ):
        return None
    needed = target_size - sum(hand)
    for i in range(15):
        added = min(needed, pool[i] - hand[i] - reserved_for_others[i])
        hand[i] += added
        needed -= added
    return None if needed else tuple(hand)


def _ranks(counts: Counts) -> list[str]:
    return [Rank(i + 3).display for i, n in enumerate(counts) for _ in range(n)]


def analyze_threat(ctx: AgentContext, arguments: dict) -> dict:
    """Answer ``can_finish`` or ``can_beat`` using public information only.

    Optional ``cards`` is a legal proposed own play. Otherwise the current
    trick is used. Without either, ``can_finish`` assumes free lead; it does
    not infer whether the queried player will actually obtain that lead.

    ``complete`` means a certified existential answer, not full enumeration:
    one full feasible witness proves possible; only exhaustive search proves
    ruled_out. Unknown is returned for missing information or a search limit.
    Invalid model arguments raise ValueError for the shared tool dispatcher.
    """
    started = perf_counter()
    if not isinstance(arguments, dict) or set(arguments) - {"event", "target_seat", "cards"}:
        raise ValueError("仅支持 event、target_seat 和可选 cards 参数。")
    event = arguments.get("event")
    if event not in ("can_finish", "can_beat"):
        raise ValueError("event 必须是 can_finish 或 can_beat。")
    target_seat = arguments.get("target_seat")
    if (
        not isinstance(target_seat, str) or target_seat not in SEATS
        or target_seat == ctx.seat or target_seat not in ctx.active_players
    ):
        raise ValueError("target_seat 必须是另一个当前活跃玩家的座位。")
    target = _target_trick(ctx, arguments)
    if event == "can_beat" and target is None:
        raise ValueError("can_beat 需要当前牌型或 cards 中指定的自家合法候选出牌。")
    result = {
        "tool": "analyze_threat",
        "event": event,
        "target_seat": target_seat,
        "status": "unknown",
        "complete": False,
        "condition": "can_follow_target" if target else "if_given_free_lead",
        "scope": _SCOPE,
        "target_play": None if target is None else {
            "pattern": target.pattern.value,
            "ranks": _ranks(counts_from_cards(target.all_cards)),
        },
    }
    try:
        observation = _observe(ctx)
    except _PublicInformationError as exc:
        result.update(reason="inconsistent_public_information", detail=str(exc))
        result["search"] = {"nodes": 0, "exhaustive": False, "elapsed_ms": round((perf_counter() - started) * 1000, 3)}
        return result

    target_minimum = (
        observation.landlord_minimum if target_seat == ctx.landlord else EMPTY_COUNTS
    )
    reserved = (
        observation.landlord_minimum
        if ctx.landlord not in (ctx.seat, target_seat) else EMPTY_COUNTS
    )
    target_size = observation.sizes[target_seat]
    other_size = sum(observation.pool) - target_size
    # A response is either the same-size pattern, a four-card bomb, or a
    # two-card rocket. This safe size ceiling avoids enumerating unrelated
    # airplane attachments when answering a single/pair/bomb threat.
    maximum_play_size = target_size
    if target is not None:
        response_size = (
            2 if target.pattern == PatternType.ROCKET
            else max(4, len(target.all_cards))
        )
        maximum_play_size = min(target_size, response_size)
    budget = SearchBudget(max_nodes=MAX_SEARCH_NODES, time_limit_ms=TIME_LIMIT_MS)
    exhaustive = False
    try:
        for play in generate_plays(
            observation.pool,
            max_size=maximum_play_size,
            exact_size=target_size if event == "can_finish" else None,
            budget=budget,
        ):
            if target is not None and not can_beat(play.trick, target):
                continue
            assumed_hand = _extend_hand(
                play.counts, observation.pool, target_minimum, reserved,
                target_size, other_size,
            )
            if assumed_hand is None:
                continue
            result.update(
                status="possible", complete=True, reason="feasible_allocation_found",
                witness={
                    "hypothetical": True,
                    "play_ranks": _ranks(play.counts),
                    "pattern": play.trick.pattern.value,
                    "assumed_hand_ranks": _ranks(assumed_hand),
                },
            )
            break
        else:
            exhaustive = True
            result.update(status="ruled_out", complete=True, reason="all_legal_plays_excluded")
    except SearchLimitExceeded:
        result.update(reason=budget.reason or "search_limit")
    result["public_constraints"] = {
        "unseen_card_count": sum(observation.pool),
        "target_hand_size": target_size,
        "landlord_minimum_ranks": _ranks(observation.landlord_minimum),
    }
    result["search"] = {
        "nodes": budget.nodes,
        "exhaustive": exhaustive,
        "node_limit": MAX_SEARCH_NODES,
        "time_limit_ms": TIME_LIMIT_MS,
        "elapsed_ms": round((perf_counter() - started) * 1000, 3),
    }
    return result

