"""Single-server match ownership, restart recovery and bounded shutdown."""

from __future__ import annotations

import asyncio
import logging
import sqlite3
import uuid

from ..db import models

logger = logging.getLogger(__name__)

DDL = """
CREATE TABLE IF NOT EXISTS match_start_claims (
    match_id TEXT PRIMARY KEY REFERENCES matches(id) ON DELETE CASCADE,
    acquired_at TEXT NOT NULL, released_at TEXT, release_reason TEXT
);
CREATE TABLE IF NOT EXISTS player_match_claims (
    id TEXT PRIMARY KEY, player_id TEXT NOT NULL,
    match_id TEXT NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
    acquired_at TEXT NOT NULL, released_at TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_player_match_claim_active
    ON player_match_claims(player_id) WHERE released_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_player_match_claim_match
    ON player_match_claims(match_id, released_at);
"""


class MatchStartConflict(ValueError):
    def __init__(self, code: str, message: str):
        super().__init__(message)
        self.code = code


class MatchExecutionInterrupted(RuntimeError):
    """A server stopped before the match's learning phase completed."""


def init_match_lifecycle(repo) -> None:
    count = repo.conn.execute(
        """SELECT COUNT(*) FROM sqlite_master WHERE name IN
           ('match_start_claims', 'player_match_claims',
            'idx_player_match_claim_active', 'idx_player_match_claim_match')"""
    ).fetchone()[0]
    if count != 4:
        with repo.atomic():
            for statement in DDL.split(";"):
                if statement.strip():
                    repo.conn.execute(statement)


def claim_match_start(repo, match_id: str, player_ids, *, writes_memory: bool) -> str:
    """Claim and mark running in one transaction before scheduling a runner."""
    init_match_lifecycle(repo)
    now = models._now()
    try:
        with repo.atomic():
            changed = repo.conn.execute(
                "UPDATE matches SET status='running', started_at=? WHERE id=? AND status='created'",
                (now, match_id),
            )
            if changed.rowcount != 1:
                raise MatchStartConflict("MATCH_ALREADY_STARTED", "Match already started")
            repo.conn.execute(
                "INSERT INTO match_start_claims(match_id, acquired_at) VALUES (?, ?)",
                (match_id, now),
            )
            if writes_memory:
                for player_id in sorted(set(player_ids)):
                    busy = repo.conn.execute(
                        "SELECT match_id FROM player_match_claims WHERE player_id=? AND released_at IS NULL",
                        (player_id,),
                    ).fetchone()
                    if busy:
                        raise MatchStartConflict(
                            "PLAYER_BUSY", "A player is still playing or saving memory in another match",
                        )
                    repo.conn.execute(
                        "INSERT INTO player_match_claims(id, player_id, match_id, acquired_at) VALUES (?, ?, ?, ?)",
                        (uuid.uuid4().hex, player_id, match_id, now),
                    )
    except sqlite3.IntegrityError as exc:
        raise MatchStartConflict("MATCH_ALREADY_CLAIMED", "Match or player already claimed") from exc
    return now


def release_match_claims(repo, match_id: str, reason: str = "completed") -> None:
    with repo.atomic():
        now = models._now()
        repo.conn.execute(
            "UPDATE player_match_claims SET released_at=? WHERE match_id=? AND released_at IS NULL",
            (now, match_id),
        )
        repo.conn.execute(
            """UPDATE match_start_claims SET released_at=?, release_reason=?
               WHERE match_id=? AND released_at IS NULL""",
            (now, reason, match_id),
        )


def match_is_claimed(repo, match_id: str) -> bool:
    init_match_lifecycle(repo)
    return repo.conn.execute(
        "SELECT 1 FROM match_start_claims WHERE match_id=? AND released_at IS NULL", (match_id,),
    ).fetchone() is not None


def player_memory_is_claimed(repo, player_id: str) -> bool:
    init_match_lifecycle(repo)
    return repo.conn.execute(
        "SELECT 1 FROM player_match_claims WHERE player_id=? AND released_at IS NULL",
        (player_id,),
    ).fetchone() is not None


def mark_match_interrupted(repo, match_id: str) -> None:
    """Keep settled scores and report unfinished summary work separately."""
    match = repo.get_match(match_id)
    if match is None:
        return
    if match["status"] in {"created", "running", "paused"}:
        repo.update_match_status(match_id, "interrupted")
    elif match["status"] == "finished":
        players = repo.conn.execute(
            "SELECT player_id FROM player_match_claims WHERE match_id=? AND released_at IS NULL",
            (match_id,),
        ).fetchall()
        for row in players:
            # Recovery only needs the provider kind. It must still work if the
            # credential master key changed or is unavailable after a restart.
            player = repo.conn.execute(
                """SELECT c.provider FROM players p
                   JOIN player_configs c ON c.id=p.config_id WHERE p.id=?""",
                (row["player_id"],),
            ).fetchone()
            if player and player["provider"] == "random":
                continue  # Random agents intentionally produce no summary memory.
            saved = repo.conn.execute(
                "SELECT 1 FROM memory_versions WHERE player_id=? AND match_id=?",
                (row["player_id"], match_id),
            ).fetchone()
            failed = repo.list_memory_failures(player_id=row["player_id"], match_id=match_id,
                                               unresolved_only=True)
            if not saved and not any(item["phase"] == "summary" for item in failed):
                repo.record_memory_failure(row["player_id"], match_id, "summary", "generation",
                                           MatchExecutionInterrupted())


def recover_interrupted_matches(repo, page_size: int = 200) -> int:
    """Drain changing result sets from page one, so no orphan is skipped."""
    init_match_lifecycle(repo)
    recovered = 0
    while True:
        claims = repo.conn.execute(
            "SELECT match_id FROM match_start_claims WHERE released_at IS NULL ORDER BY match_id LIMIT ?",
            (page_size,),
        ).fetchall()
        if not claims:
            break
        for row in claims:
            with repo.atomic():
                mark_match_interrupted(repo, row["match_id"])
                release_match_claims(repo, row["match_id"], "server_restart")
            recovered += 1
    for status in ("running", "paused"):
        while True:
            matches, _ = repo.list_matches(status=status, page=1, page_size=page_size)
            if not matches:
                break
            for match in matches:
                repo.update_match_status(match["id"], "interrupted")
                recovered += 1
    return recovered


def ensure_task_registry(app) -> None:
    for name in ("active_matches", "match_tasks", "match_scopes", "evaluation_tasks",
                 "match_cleanup_pending"):
        if not hasattr(app.state, name):
            setattr(app.state, name, {})
    if not hasattr(app.state, "detached_match_tasks"):
        app.state.detached_match_tasks = set()


def consume_task_result(task) -> None:
    if not task.cancelled():
        task.exception()


def _finish_claim_cleanup(app, match_id: str, cleanup: dict) -> None:
    if cleanup["scope"].active:
        raise RuntimeError("cannot release claims before execution is revoked")
    with app.state.db_repo.atomic():
        if cleanup["reason"] != "completed":
            mark_match_interrupted(app.state.db_repo, match_id)
        release_match_claims(app.state.db_repo, match_id, cleanup["reason"])
    app.state.match_cleanup_pending.pop(match_id, None)


async def cleanup_match_claims(app, match_id: str, scope, reason: str,
                               attempts: int = 3, retry_delay: float = .05) -> bool:
    """Fence this process's owned task before retrying its durable cleanup."""
    ensure_task_registry(app)
    if app.state.match_scopes.get(match_id) is not scope:
        return False  # Shutdown or another cleanup already detached this task.
    try:
        scope.revoke()
    except (Exception, asyncio.CancelledError) as exc:
        logger.warning("Could not finalize cancelled call evidence: %s", type(exc).__name__)
    if scope.active:
        return False
    cleanup = {"scope": scope, "reason": reason,
               "task": app.state.match_tasks.get(match_id)}
    # Register before any await: cancellation or another storage failure must
    # not erase the only in-process record capable of releasing these claims.
    app.state.match_cleanup_pending[match_id] = cleanup
    for attempt in range(attempts):
        try:
            _finish_claim_cleanup(app, match_id, cleanup)
            return True
        except sqlite3.OperationalError as exc:
            cleanup["error_type"] = type(exc).__name__
            if attempt + 1 < attempts:
                await asyncio.sleep(retry_delay)
        except Exception as exc:
            cleanup["error_type"] = type(exc).__name__
            break
    logger.error("Match %s cleanup pending after storage failure; retrying a start request "
                 "will retry cleanup (%s)", match_id, cleanup.get("error_type", "unknown"))
    return False


def recover_pending_match_cleanups(app) -> int:
    """Retry only locally owned, revoked tasks that have actually finished."""
    ensure_task_registry(app)
    recovered = 0
    for match_id, cleanup in list(app.state.match_cleanup_pending.items()):
        task = cleanup.get("task") or app.state.match_tasks.get(match_id)
        if cleanup["scope"].active or (task is not None and not task.done()):
            continue
        try:
            _finish_claim_cleanup(app, match_id, cleanup)
            recovered += 1
        except Exception as exc:
            cleanup["error_type"] = type(exc).__name__
            logger.warning("Match %s cleanup still pending: %s", match_id, type(exc).__name__)
    return recovered


async def shutdown_matches(app, timeout_seconds: float = 5.0) -> set:
    """Cancel managed work; fence a cancellation-resistant task before DB close."""
    ensure_task_registry(app)
    app.state.shutting_down = True
    repo = app.state.db_repo
    for runner in list(getattr(app.state, "active_evaluations", {}).values()):
        runner.cancel()
    tasks = set(app.state.match_tasks.values()) | set(app.state.evaluation_tasks.values())
    for scope in list(app.state.match_scopes.values()):
        scope.cancel_requested = True
    for task in tasks:
        task.cancel()
    pending = set()
    if tasks:
        _, pending = await asyncio.wait(tasks, timeout=timeout_seconds)
    for match_id, scope in list(app.state.match_scopes.items()):
        await cleanup_match_claims(app, match_id, scope, "shutdown")
        app.state.active_matches.pop(match_id, None)
        app.state.match_tasks.pop(match_id, None)
        app.state.match_scopes.pop(match_id, None)
    recover_pending_match_cleanups(app)
    for task in pending:
        app.state.detached_match_tasks.add(task)
        task.add_done_callback(app.state.detached_match_tasks.discard)
        task.add_done_callback(consume_task_result)
    # Evaluation workers already have revocable scopes. Its API task registry
    # lets shutdown wait for the outer status/report cleanup before DB close.
    for runner in list(getattr(app.state, "active_evaluations", {}).values()):
        scope = getattr(runner, "_scope", None)
        if scope:
            try:
                scope.revoke()
            except (Exception, asyncio.CancelledError) as exc:
                logger.warning("Could not finalize cancelled evaluation: %s", type(exc).__name__)
    remaining_evaluations = {task for task in app.state.evaluation_tasks.values() if not task.done()}
    for task in remaining_evaluations:
        task.cancel()
    if remaining_evaluations:
        _, remaining_evaluations = await asyncio.wait(remaining_evaluations, timeout=1.0)
    return remaining_evaluations


def close_database_after_cleanup(repo, pending: set) -> None:
    """An evaluation's outer cleanup must finish before its raw repo closes."""
    remaining = {task for task in pending if not task.done()}
    if not remaining:
        repo.close()
        return

    def finished(task):
        remaining.discard(task)
        if not remaining:
            repo.close()

    for task in remaining:
        task.add_done_callback(finished)

"""Experiment planning and resumable execution API."""

from __future__ import annotations

import asyncio
import json

from fastapi import APIRouter, HTTPException, Request

from ...evaluation.runner import EvaluationRunner
from ...evaluation.spec import ExperimentSpec, PreflightError, RunManifest, build_run_manifest
from ...security.credentials import has_usable_credential
from ...config.paths import PROJECT_ROOT as ROOT, EVALUATION_DIR
from ..match_lifecycle import consume_task_result, ensure_task_registry

router = APIRouter(prefix="/evaluations", tags=["evaluations"])


def _repo(request: Request):
    return request.app.state.db_repo


def _decode(row: dict) -> dict:
    result = dict(row)
    for key in ("manifest_json", "spec_json"):
        if key in result and isinstance(result[key], str):
            result[key[:-5] if key.endswith("_json") else key] = json.loads(result[key])
    return result


def _preflight(repo, spec: ExperimentSpec):
    manifest = build_run_manifest(spec, ROOT, repo)
    errors = []
    for model in spec.models:
        config = repo.get_player_config_by_name(model.config_name)
        if not config and model.provider != "mock":
            errors.append(f"模型配置不存在: {model.config_name}")
        elif config and model.provider not in ("random", "mock") and not has_usable_credential(config.get("api_key")):
            errors.append(f"模型配置缺少 API 密钥: {model.config_name}")
    if len(spec.models) != 1:
        errors.append("阶段 4 首版消融实验要求恰好选择一个模型配置")
    if any(variant.memory_mode == "read_only" for variant in spec.variants) and not spec.memory_artifact_path:
        errors.append("只读记忆变体必须指定冻结的 memory_artifact_path")
    from ...evaluation.spec import validate_execution
    if not errors:
        try:
            validate_execution(spec, manifest, ROOT, repo, mock=manifest.models[0].provider == 'mock')
        except PreflightError as exc:
            errors.append(str(exc))
    return manifest, errors


@router.get('/template')
async def get_template(mode: str = 'mock'):
    from ...evaluation.spec import load_experiment_spec
    if mode not in ('mock', 'real'):
        raise HTTPException(400, detail='mode must be mock or real')
    spec = load_experiment_spec(EVALUATION_DIR / 'experiments/mock-v2.yaml').model_dump(mode='json')
    spec['mock_scenario'] = 'valid_first'
    if mode == 'real':
        from dataclasses import asdict
        from ...engine.timeout import TimeoutConfig
        spec.update(
            experiment_id='reliability-smoke-v2',
            seed_set_path='src/backend/evaluation/seed_sets/smoke-v1.json',
            # Real decisions use the engine's normal limits, not mock latency.
            timeout_config=asdict(TimeoutConfig()),
            task_timeout_seconds=3600,
            pricing_version='user-supplied-v1',
            budget_limit_usd=None,
        )
        spec['models'] = []  # The user supplies the actual model and verified pricing.
    return spec


@router.post("/preflight")
async def preflight(request: Request):
    try:
        spec = ExperimentSpec.model_validate(await request.json())
        manifest, errors = _preflight(_repo(request), spec)
    except (ValueError, PreflightError) as exc:
        raise HTTPException(400, detail={"error": {"code": "PREFLIGHT_FAILED", "message": str(exc)}})
    return {"ok": not errors, "errors": errors, "task_count": len(manifest.seeds) * len(manifest.variants) * spec.seat_rotations, "manifest_sha256": manifest.manifest_sha256, "seed_count": len(manifest.seeds)}


@router.post("", status_code=201)
async def create_evaluation(request: Request):
    try:
        spec = ExperimentSpec.model_validate(await request.json())
        manifest, errors = _preflight(_repo(request), spec)
    except (ValueError, PreflightError) as exc:
        raise HTTPException(400, detail={"error": {"code": "PREFLIGHT_FAILED", "message": str(exc)}})
    if errors:
        raise HTTPException(400, detail={"error": {"code": "PREFLIGHT_FAILED", "message": "; ".join(errors)}})
    run_id = EvaluationRunner(_repo(request), str(ROOT)).create_run(spec, manifest)
    return {"run_id": run_id, "status": "planned", "task_count": len(_repo(request).get_evaluation_tasks(run_id))}


@router.get("")
async def list_evaluations(request: Request):
    return {"runs": [_decode(row) for row in _repo(request).list_evaluation_runs()]}


@router.get("/{run_id}")
async def get_evaluation(run_id: str, request: Request):
    run = _repo(request).get_evaluation_run(run_id)
    if not run:
        raise HTTPException(404, detail={"error": {"code": "RUN_NOT_FOUND", "message": "实验运行不存在"}})
    tasks = _repo(request).get_evaluation_tasks(run_id)
    counts = {status: sum(t["status"] == status for t in tasks) for status in ("planned", "running", "finished", "failed", "cancelled")}
    return {"run": _decode(run), "tasks": tasks, "counts": counts}


def _load_spec(repo, run_id: str):
    run = repo.get_evaluation_run(run_id)
    if not run:
        raise HTTPException(404, detail={"error": {"code": "RUN_NOT_FOUND", "message": "实验运行不存在"}})
    from ...evaluation.spec import load_manifest
    stored = json.loads(run["manifest_json"])
    if not stored.get("frozen_spec"):
        raise HTTPException(409, detail="Legacy run must be replanned with frozen inputs")
    spec = ExperimentSpec.model_validate(stored["frozen_spec"])
    manifest = load_manifest(stored)
    return run, spec, manifest


@router.post("/{run_id}/start")
async def start_evaluation(run_id: str, request: Request):
    ensure_task_registry(request.app)
    if getattr(request.app.state, "shutting_down", False):
        raise HTTPException(503, detail="Server is stopping")
    body = await request.json()
    run, spec, manifest = _load_spec(_repo(request), run_id)
    mock = manifest.models[0].provider == "mock"
    if not mock and body.get("confirm_real_models") is not True:
        raise HTTPException(400, detail={"error": {"code": "CONFIRMATION_REQUIRED", "message": "必须明确确认真实模型调用与成本"}})
    if run_id in request.app.state.active_evaluations:
        return {"run_id": run_id, "status": "running"}
    from ...evaluation.spec import validate_execution
    try:
        validate_execution(spec, manifest, ROOT, _repo(request), mock=mock)
    except PreflightError as exc:
        raise HTTPException(400, detail=str(exc))
    runner = EvaluationRunner(_repo(request), str(ROOT), request.app.state.active_matches)
    request.app.state.active_evaluations[run_id] = runner

    async def execute():
        try:
            await runner.run(run_id, spec, manifest, real_models=not mock, mock=mock)
        finally:
            request.app.state.active_evaluations.pop(run_id, None)
            request.app.state.evaluation_tasks.pop(run_id, None)

    task = asyncio.create_task(execute())
    request.app.state.evaluation_tasks[run_id] = task
    task.add_done_callback(consume_task_result)
    return {"run_id": run_id, "status": "running"}


@router.post("/{run_id}/cancel")
async def cancel_evaluation(run_id: str, request: Request):
    runner = request.app.state.active_evaluations.get(run_id)
    if runner:
        runner.cancel()
    else:
        _repo(request).update_evaluation_run_status(run_id, "cancelled")
    return {"run_id": run_id, "status": "cancelling" if runner else "cancelled"}


@router.post("/{run_id}/resume")
async def resume_evaluation(run_id: str, request: Request):
    return await start_evaluation(run_id, request)


@router.get("/{run_id}/report")
async def get_report(run_id: str, request: Request):
    repo = _repo(request)
    _load_spec(repo, run_id)
    from ...evaluation.report import build_report
    manifest, integrity, summary, metrics, seeds, failures = build_report(repo, run_id)
    return {"integrity": integrity, "summary": summary, "seed_level": seeds, "failures": failures}


@router.get("/{run_id}/artifacts/{filename}")
async def get_artifact(run_id: str, filename: str, request: Request):
    from fastapi.responses import FileResponse
    if filename not in {"manifest.json","integrity.json","summary.json","metrics.csv","seed_level.csv","report.md"}:
        raise HTTPException(404,detail="unknown artifact")
    _load_spec(_repo(request),run_id)
    from ...evaluation.report import export_report
    out=ROOT/"data/evaluations"/run_id
    export_report(_repo(request),run_id,out)
    return FileResponse(out/filename,filename=filename)

src/backend/arena/api/routes/match.py:
"""Match CRUD + control routes — create, list, get, start, pause, resume, delete."""

from __future__ import annotations

import asyncio
import json
from typing import Any

from fastapi import APIRouter, BackgroundTasks, HTTPException, Request

from ...tournament.match import MatchConfig, MatchRunner
from ...tournament.seating import MatchSeating, assign_seating
from ...engine.timeout import TimeoutConfig
from ...security.credentials import has_usable_credential
from ..match_lifecycle import (
    MatchStartConflict, claim_match_start, cleanup_match_claims, consume_task_result,
    ensure_task_registry, match_is_claimed, recover_pending_match_cleanups,
)

router = APIRouter(prefix="/matches", tags=["matches"])


def _repo(request: Request):
    return request.app.state.db_repo


def _match_config_from_dict(d: dict) -> MatchConfig:
    """Build MatchConfig from request JSON, applying server defaults."""
    from ...config.settings import settings

    if not isinstance(d, dict):
        raise HTTPException(400, detail={"error": {"code": "INVALID_REQUEST", "message": "config must be an object"}})
    for key in ("enable_reflection", "enable_summary", "persist_long_term_memory", "enable_tools"):
        if key in d and not isinstance(d[key], bool):
            raise HTTPException(400, detail={"error": {"code": "INVALID_REQUEST", "message": f"{key} must be boolean"}})
    import math
    for key in ("reflection_timeout_seconds", "summary_timeout_seconds"):
        if key in d and (
            isinstance(d[key], bool) or not isinstance(d[key], (int, float))
            or not math.isfinite(d[key]) or d[key] <= 0
        ):
            raise HTTPException(400, detail={"error": {"code": "INVALID_REQUEST", "message": f"{key} must be finite and positive"}})

    return MatchConfig(
        total_hands=d.get("total_hands", settings.total_hands),
        ko_enabled=d.get("ko_enabled", settings.ko_enabled),
        seed=d.get("seed", ""),
        enable_reflection=d.get("enable_reflection", True),
        enable_summary=d.get("enable_summary", True),
        enable_tools=d.get("enable_tools", False),
        persist_long_term_memory=d.get("persist_long_term_memory", True),
        reflection_timeout_seconds=d.get("reflection_timeout_seconds", 30.0),
        summary_timeout_seconds=d.get("summary_timeout_seconds", 45.0),
        timeout_config=TimeoutConfig(
            bidding_seconds=d.get(
                "timeout_bidding_seconds", settings.bidding_timeout_seconds
            ),
            individual_play_seconds=d.get(
                "timeout_individual_seconds", settings.individual_play_timeout_seconds
            ),
            team_pool_seconds=d.get(
                "timeout_team_seconds", settings.team_pool_timeout_seconds
            ),
        ),
    )


def _match_row_to_summary(row: dict) -> dict[str, Any]:
    """Convert a DB match row into the API summary format."""
    config = row.get("config")
    if isinstance(config, str):
        config = json.loads(config)
    total_hands = config.get("total_hands", 0) if config else 0
    return {
        "id": row["id"],
        "name": row["name"],
        "status": row["status"],
        "created_at": row["created_at"],
        "started_at": row.get("started_at"),
        "finished_at": row.get("finished_at"),
        "current_hand": row.get("current_hand", 0),
        "total_hands": total_hands,
        "score": {
            "red": row.get("score_red", 0),
            "blue": row.get("score_blue", 0),
        },
        "ko_result": row.get("ko_result"),
    }


def _match_row_to_detail(row: dict, participants: list[dict]) -> dict[str, Any]:
    """Convert a DB match row into the API detail response."""
    config = row.get("config")
    if isinstance(config, str):
        config = json.loads(config)

    teams: dict[str, dict[str, Any]] = {"red": {"name": "", "agents": []}, "blue": {"name": "", "agents": []}}
    seating: dict[str, dict[str, str]] = {"table_a": {}, "table_b": {}}

    for p in participants:
        team = p["team"]
        player_id = p["player_id"]
        teams[team]["agents"].append(player_id)
        if p.get("seat_table_a"):
            seating["table_a"][p["seat_table_a"]] = player_id
        if p.get("seat_table_b"):
            seating["table_b"][p["seat_table_b"]] = player_id

    # Build score history from hands
    score_history: list[dict[str, Any]] = []

    return {
        "id": row["id"],
        "name": row["name"],
        "status": row["status"],
        "config": config if config else {},
        "teams": teams,
        "seating": seating,
        "score": {
            "red": row.get("score_red", 0),
            "blue": row.get("score_blue", 0),
        },
        "score_history": score_history,
        "current_hand": row.get("current_hand", 0),
        "created_at": row["created_at"],
        "started_at": row.get("started_at"),
        "paused_at": row.get("paused_at"),
        "finished_at": row.get("finished_at"),
    }


@router.get("")
async def list_matches(
    request: Request,
    page: int = 1,
    page_size: int = 20,
    status: str | None = None,
):
    """List matches with optional status filter and pagination."""
    if status and status not in ("created", "running", "paused", "finished", "interrupted"):
        raise HTTPException(400, detail={"error": {"code": "INVALID_REQUEST", "message": f"Invalid status: {status}"}})
    repo = _repo(request)
    matches, total = repo.list_matches(status=status, page=page, page_size=page_size)
    return {
        "total": total,
        "page": page,
        "page_size": page_size,
        "matches": [_match_row_to_summary(m) for m in matches],
    }


@router.post("", status_code=201)
async def create_match(request: Request):
    """Create a new match. Assigns seating from provided agent IDs."""
    body = await request.json()
    repo = _repo(request)

    name = body.get("name", "")
    if not name:
        raise HTTPException(400, detail={"error": {"code": "INVALID_REQUEST", "message": "name is required"}})

    config_dict = body.get("config", {})
    match_config = _match_config_from_dict(config_dict)

    # Validate teams
    team_red = body.get("team_red", {})
    team_blue = body.get("team_blue", {})
    red_agents = team_red.get("agents", [])
    blue_agents = team_blue.get("agents", [])

    if len(red_agents) != 4 or len(blue_agents) != 4:
        raise HTTPException(
            400,
            detail={
                "error": {
                    "code": "INVALID_REQUEST",
                    "message": "Each team must have exactly 4 agent IDs",
                }
            },
        )

    # Verify all players exist
    for pid in red_agents + blue_agents:
        if repo.get_player(pid) is None:
            raise HTTPException(404, detail={"error": {"code": "PLAYER_NOT_FOUND", "message": f"Player not found: {pid}"}})

    # Assign seating
    try:
        seating = assign_seating(red_agents, blue_agents)
    except ValueError as e:
        raise HTTPException(400, detail={"error": {"code": "INVALID_REQUEST", "message": str(e)}})

    # A partial participant insert must not leave a startable, incomplete match.
    with repo.atomic():
        match_id = repo.create_match(name, config_dict, match_config.seed or "")
        for seat, aid in seating.table_a.items():
            repo.add_participant(match_id, aid, seating.table_a_teams[seat], seat_table_a=seat)
        for seat, aid in seating.table_b.items():
            repo.add_participant(match_id, aid, seating.table_b_teams[seat], seat_table_b=seat)

    match = repo.get_match(match_id)
    return {
        "id": match_id,
        "name": name,
        "status": "created",
        "created_at": match["created_at"] if match else "",
        "seating": {
            "table_a": seating.table_a,
            "table_b": seating.table_b,
        },
    }


@router.get("/{match_id}")
async def get_match(match_id: str, request: Request):
    """Get full match details."""
    repo = _repo(request)
    match = repo.get_match(match_id)
    if not match:
        raise HTTPException(404, detail={"error": {"code": "MATCH_NOT_FOUND", "message": f"Match not found: {match_id}"}})

    participants = repo.get_participants(match_id)

    # Build score history from hands
    hands = repo.get_hands_for_match(match_id)
    score_history: list[dict[str, Any]] = []
    for h in hands:
        if h.get("status") == "finished":
            score_history.append({
                "hand": h["hand_num"],
                "red_diff": h.get("diff_score_red", 0),
                "blue_diff": h.get("diff_score_blue", 0),
                "running_total": {
                    "red": match.get("score_red", 0) if h["hand_num"] == match.get("current_hand", 0) else 0,
                    "blue": match.get("score_blue", 0) if h["hand_num"] == match.get("current_hand", 0) else 0,
                },
            })

    # Build running totals from hands
    running_red = 0
    running_blue = 0
    for entry in score_history:
        running_red += entry["red_diff"]
        running_blue += entry["blue_diff"]
        entry["running_total"] = {"red": running_red, "blue": running_blue}

    detail = _match_row_to_detail(match, participants)
    detail["score_history"] = score_history

    # Add time remaining if match is running
    if match["status"] == "running":
        detail["time_remaining"] = {
            "table_a": {"red_team_ms": 0, "blue_team_ms": 0},
            "table_b": {"red_team_ms": 0, "blue_team_ms": 0},
        }

    return detail


@router.post("/{match_id}/start")
async def start_match(match_id: str, request: Request, background_tasks: BackgroundTasks):
    """Start a match — runs the full match async in a background task."""
    repo = _repo(request)
    ensure_task_registry(request.app)
    if getattr(request.app.state, "shutting_down", False):
        raise HTTPException(503, detail={"error": {"code": "SERVER_STOPPING", "message": "Server is stopping"}})
    recover_pending_match_cleanups(request.app)
    match = repo.get_match(match_id)
    if not match:
        raise HTTPException(404, detail={"error": {"code": "MATCH_NOT_FOUND", "message": f"Match not found: {match_id}"}})
    if match["status"] != "created":
        raise HTTPException(409, detail={"error": {"code": "MATCH_ALREADY_STARTED", "message": "Match already started"}})

    config = match.get("config")
    if isinstance(config, str):
        config = json.loads(config)
    match_config = _match_config_from_dict(config if config else {})

    # Load players — each participant references a player ID
    from ...agent.llm_agent import LLMAgent
    from ...agent.random_agent import RandomAgent
    from ...agent.memory import MAX_LONG_TERM_CHARS, validate_memory_text
    from ...llm.base import AbstractLLMProvider
    from ...llm.logging import LoggingLLMProvider
    from ...evaluation.execution import ExecutionScope

    scope = ExecutionScope()
    guarded_repo = scope.guard(repo)

    player_ids_in_match: set[str] = set()
    for p in repo.get_participants(match_id):
        player_ids_in_match.add(p["player_id"])

    # Validate every saved input before allocating any provider clients.
    player_inputs = {}
    for pid in sorted(player_ids_in_match):
        player_row = repo.get_player_with_config(pid)
        if player_row is None:
            raise HTTPException(500, detail={"error": {"code": "INTERNAL_ERROR", "message": f"Player row not found: {pid}"}})

        provider_name = player_row["provider"]
        initial_memory = ""
        if provider_name != "random":
            try:
                initial_memory = validate_memory_text(
                    player_row.get("long_term_memory", ""),
                    max_chars=MAX_LONG_TERM_CHARS, allow_empty=True,
                )
            except ValueError as exc:
                raise HTTPException(422, detail={"error": {
                    "code": "PLAYER_MEMORY_INVALID",
                    "message": f"选手原记忆已保留，请先将长期记忆整理为不超过 {MAX_LONG_TERM_CHARS} 字符的文本，再启动比赛。",
                    "player_id": pid,
                    "max_chars": MAX_LONG_TERM_CHARS,
                }}) from exc
            api_key = player_row.get("api_key", "")
            if not has_usable_credential(api_key):
                raise HTTPException(400, detail={"error": {"code": "CREDENTIAL_UNAVAILABLE", "message": "模型密钥尚未配置或环境变量未解析"}})
        player_inputs[pid] = (player_row, initial_memory)

    agents_dict: dict[str, Any] = {}
    for pid, (player_row, initial_memory) in player_inputs.items():
        provider_name = player_row["provider"]
        if provider_name == "random":
            agents_dict[pid] = RandomAgent(agent_id=pid)
        else:
            api_key = player_row.get("api_key", "")
            base_url = player_row.get("base_url")
            if provider_name == "claude":
                from ...llm.claude import ClaudeProvider
                provider: AbstractLLMProvider = ClaudeProvider(
                    model=player_row["model"], api_key=api_key, base_url=base_url,
                )
            else:
                from ...llm.openai import OpenAIProvider
                provider = OpenAIProvider(
                    model=player_row["model"], api_key=api_key,
                    base_url=base_url,
                )
            agents_dict[pid] = LLMAgent(
                agent_id=pid,
                provider=LoggingLLMProvider(provider, repo=guarded_repo, agent_id=pid,
                                            execution_scope=scope),
                long_term_memory=initial_memory,
                system_prompt_override=player_row.get("system_prompt"),
            )

    # Build seating from DB participants
    participants = repo.get_participants(match_id)
    table_a: dict[str, str] = {}
    table_b: dict[str, str] = {}
    table_a_teams: dict[str, str] = {}
    table_b_teams: dict[str, str] = {}
    agent_seats: dict[str, tuple[str, str]] = {}
    agent_teams: dict[str, str] = {}

    for p in participants:
        if p.get("seat_table_a"):
            table_a[p["seat_table_a"]] = p["player_id"]
            table_a_teams[p["seat_table_a"]] = p["team"]
            agent_seats[p["player_id"]] = ("A", p["seat_table_a"])
            agent_teams[p["player_id"]] = p["team"]
        if p.get("seat_table_b"):
            table_b[p["seat_table_b"]] = p["player_id"]
            table_b_teams[p["seat_table_b"]] = p["team"]
            agent_seats[p["player_id"]] = ("B", p["seat_table_b"])
            agent_teams[p["player_id"]] = p["team"]

    seating = MatchSeating(
        table_a=table_a,
        table_b=table_b,
        table_a_teams=table_a_teams,
        table_b_teams=table_b_teams,
        agent_seats=agent_seats,
        agent_teams=agent_teams,
    )

    runner = MatchRunner(
        config=match_config,
        seating=seating,
        agents=agents_dict,
        db_repo=guarded_repo,
        match_name=match["name"],
    )
    # Override the match_id so it uses the existing DB match
    runner.match_id = match_id
    runner.table_a.match_id = match_id
    runner.table_b.match_id = match_id
    runner._db_initialized = True  # match + participants already in DB via API
    scope.match_runner = runner

    try:
        started_at = claim_match_start(
            repo, match_id, player_ids_in_match,
            writes_memory=match_config.enable_summary and match_config.persist_long_term_memory,
        )
    except MatchStartConflict as exc:
        raise HTTPException(409, detail={"error": {"code": exc.code, "message": str(exc)}}) from exc

    # Store the runner on app state so WebSocket handler can access it
    if not hasattr(request.app.state, "active_matches"):
        request.app.state.active_matches = {}
    request.app.state.active_matches[match_id] = runner
    request.app.state.match_scopes[match_id] = scope

    async def run_and_cleanup():
        reason = "completed"
        try:
            await runner.run()
        except BaseException:
            reason = "interrupted"
            raise
        finally:
            try:
                await cleanup_match_claims(request.app, match_id, scope, reason)
            finally:
                request.app.state.active_matches.pop(match_id, None)
                request.app.state.match_tasks.pop(match_id, None)
                request.app.state.match_scopes.pop(match_id, None)

    task = asyncio.create_task(run_and_cleanup())
    request.app.state.match_tasks[match_id] = task
    task.add_done_callback(consume_task_result)

    return {"status": "running", "started_at": started_at}


@router.post("/{match_id}/pause")
async def pause_match(match_id: str, request: Request):
    """Request a pause. Takes effect after current play completes."""
    repo = _repo(request)
    match = repo.get_match(match_id)
    if not match:
        raise HTTPException(404, detail={"error": {"code": "MATCH_NOT_FOUND", "message": f"Match not found: {match_id}"}})
    if match["status"] != "running":
        raise HTTPException(400, detail={"error": {"code": "INVALID_STATE_TRANSITION", "message": "Match is not running"}})

    runner = getattr(request.app.state, "active_matches", {}).get(match_id)
    if runner is None:
        raise HTTPException(400, detail={"error": {"code": "INVALID_STATE_TRANSITION", "message": "No active runner found — match may be running externally"}})

    runner.request_pause()
    repo.update_match_status(match_id, "paused")
    return {
        "status": "paused",
        "paused_at": MatchRunner._now_iso(),
        "paused_at_hand": match.get("current_hand", 0),
        "reason": "user_requested",
    }


@router.post("/{match_id}/resume")
async def resume_match(match_id: str, request: Request):
    """Resume a paused match."""
    repo = _repo(request)
    match = repo.get_match(match_id)
    if not match:
        raise HTTPException(404, detail={"error": {"code": "MATCH_NOT_FOUND", "message": f"Match not found: {match_id}"}})
    if match["status"] != "paused":
        raise HTTPException(400, detail={"error": {"code": "INVALID_STATE_TRANSITION", "message": "Match is not paused"}})

    runner = getattr(request.app.state, "active_matches", {}).get(match_id)
    if runner is None:
        raise HTTPException(400, detail={"error": {"code": "INVALID_STATE_TRANSITION", "message": "No active runner found"}})

    runner.pause.resume()
    runner.resume_tables()
    repo.update_match_status(match_id, "running")
    return {
        "status": "running",
        "resumed_at": MatchRunner._now_iso(),
    }


@router.delete("/{match_id}", status_code=204)
async def delete_match(match_id: str, request: Request):
    """Delete a match. Running matches must be stopped first."""
    repo = _repo(request)
    match = repo.get_match(match_id)
    if not match:
        raise HTTPException(404, detail={"error": {"code": "MATCH_NOT_FOUND", "message": f"Match not found: {match_id}"}})
    if match["status"] in ("running", "paused") or match_is_claimed(repo, match_id):
        raise HTTPException(400, detail={"error": {"code": "INVALID_STATE_TRANSITION", "message": "Cannot delete a running match — stop it first"}})

    if not repo.delete_match_from_db(match_id):
        raise HTTPException(500, detail={"error": {"code": "INTERNAL_ERROR", "message": "Failed to delete match"}})

