@router.get("/leaderboard")
async def get_player_leaderboard(request: Request, sort: str = "win_rate"):
    """Return every player with fresh per-hand statistics for ranking."""
    if sort not in {"win_rate", "score"}:
        raise HTTPException(400, detail={"error": {"code": "INVALID_REQUEST", "message": "sort must be 'win_rate' or 'score'"}})

    repo = _repo(request)
    records_by_player: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for record in repo.get_player_hand_records():
        records_by_player[record["player_id"]].append(record)

    players = [
        _player_summary(player, build_player_statistics(records_by_player[player["id"]]))
        for player in repo.list_players_with_config()
    ]
    if sort == "score":
        players.sort(key=lambda player: (-player["statistics"]["score_total"], player["display_name"]))
    else:
        players.sort(key=lambda player: (
            -(player["statistics"]["win_rate"] if player["statistics"]["win_rate"] is not None else -1),
            -player["statistics"]["hands_played"],
            player["display_name"],
        ))
    return {"players": players}


@router.post("", status_code=201)
async def create_player(request: Request):
    """Create a new player from an existing config."""
    body = await request.json()
    repo = _repo(request)

    # Accept config_id or config_name
    config_id = body.get("config_id", "")
    config_name = body.get("config_name", "")

    config = None
    if config_id:
        config = repo.get_player_config(config_id)
    elif config_name:
        config = repo.get_player_config_by_name(config_name)

    if config is None:
        raise HTTPException(400, detail={"error": {"code": "INVALID_REQUEST", "message": "config_id or config_name referencing an existing config is required"}})

    display_name = body.get("display_name", "")
    if not display_name:
        # Auto-generate: config name + incrementing number
        existing = repo.list_players(config_id=config["id"])
        display_name = f"{config['name']} #{len(existing) + 1}"

    player_id = repo.create_player(
        config_id=config["id"],
        display_name=display_name,
    )

    player = repo.get_player_with_config(player_id)
    return {
        "id": player["id"],
        "display_name": player["display_name"],
        "config_id": player["config_id"],
        "config_name": player.get("config_name", ""),
        "provider": player.get("provider", ""),
        "model": player.get("model", ""),
        "matches_played": player.get("matches_played", 0),
        "created_at": player["created_at"],
    }


@router.get("/{player_id}")
async def get_player(player_id: str, request: Request):
    """Get a single player with full config details."""
    repo = _repo(request)
    player = repo.get_player_with_config(player_id)
    if not player:
        raise HTTPException(404, detail={"error": {"code": "PLAYER_NOT_FOUND", "message": f"Player not found: {player_id}"}})

    statistics = build_player_statistics(repo.get_player_hand_records(player_id))
    memories = repo.get_agent_memories(player_id, memory_type="long_term")
    versions = repo.list_memory_versions(player_id)
    return {
        "id": player["id"],
        "display_name": player["display_name"],
        "config_id": player["config_id"],
        "config_name": player.get("config_name", ""),
        "provider": player.get("provider", ""),
        "model": player.get("model", ""),
        "base_url": player.get("base_url"),
        "system_prompt": player.get("system_prompt"),
        "long_term_memory": player.get("long_term_memory", ""),
        "memory_versions": versions,
        "memory_failures": repo.list_memory_failures(player_id=player_id),
        "memory_usage": [dict(row) for row in repo.conn.execute(
            """SELECT u.match_id, u.version_id, v.revision, u.created_at
               FROM match_memory_usage u JOIN memory_versions v ON v.id=u.version_id
               WHERE u.player_id=? ORDER BY u.created_at DESC, u.id DESC LIMIT 100""",
            (player_id,),
        )],
        "matches_played": player.get("matches_played", 0),
        "matches_won": player.get("matches_won", 0),
        "total_score": player.get("total_score", 0),
        "statistics": statistics,
        "long_term_memory_history": [
            {
                "content": memory["content"],
                "match_id": memory.get("match_id"),
                "created_at": memory["created_at"],
            }
            for memory in memories
        ],
        "created_at": player["created_at"],
        "updated_at": player["updated_at"],
    }


@router.put("/{player_id}")
async def update_player(player_id: str, request: Request):
    """Update the name or replace memory with a validated, audited version."""
    body = await request.json()
    if not isinstance(body, dict):
        raise HTTPException(400, detail={"error": {"code": "INVALID_REQUEST", "message": "Request must be an object"}})
    repo = _repo(request)

    player = repo.get_player(player_id)
    if not player:
        raise HTTPException(404, detail={"error": {"code": "PLAYER_NOT_FOUND", "message": f"Player not found: {player_id}"}})

    updates = {}
    if "display_name" in body:
        updates["display_name"] = body["display_name"]

    version = None
    with repo.atomic():
        if "long_term_memory" in body:
            from ..match_lifecycle import player_memory_is_claimed
            from ...db.repository import MemoryConflictError
            from ...agent.memory import MAX_LONG_TERM_CHARS

            if player_memory_is_claimed(repo, player_id):
                raise HTTPException(409, detail={"error": {
                    "code": "PLAYER_BUSY", "message": "该选手正在比赛或保存总结，请结束后再修改记忆。",
                }})
            try:
                version = repo.save_long_term_memory(
                    player_id, body["long_term_memory"], None,
                    expected_content=body.get("expected_long_term_memory", player.get("long_term_memory") or ""),
                )
            except MemoryConflictError as exc:
                raise HTTPException(409, detail={"error": {
                    "code": "MEMORY_CONFLICT", "message": "选手记忆已更新，请刷新后重新编辑。",
                }}) from exc
            except ValueError as exc:
                raise HTTPException(422, detail={"error": {
                    "code": "PLAYER_MEMORY_INVALID",
                    "message": f"长期记忆必须是 1–{MAX_LONG_TERM_CHARS} 字符的文本。",
                    "max_chars": MAX_LONG_TERM_CHARS,
                }}) from exc
        if updates:
            repo.update_player_by_id(player_id, **updates)

    updated = repo.get_player_with_config(player_id)
    return {
        "id": updated["id"],
        "display_name": updated["display_name"],
        "config_id": updated["config_id"],
        "config_name": updated.get("config_name", ""),
        "matches_played": updated.get("matches_played", 0),
        "matches_won": updated.get("matches_won", 0),
        "total_score": updated.get("total_score", 0),
        "long_term_memory": updated.get("long_term_memory", ""),
        "memory_version_id": version["id"] if version else None,
        "memory_revision": version["revision"] if version else None,
        "created_at": updated["created_at"],
        "updated_at": updated["updated_at"],
    }


@router.delete("/{player_id}", status_code=204)
async def delete_player(player_id: str, request: Request):
    """Delete a player."""
    repo = _repo(request)
    player = repo.get_player(player_id)
    if not player:
        raise HTTPException(404, detail={"error": {"code": "PLAYER_NOT_FOUND", "message": f"Player not found: {player_id}"}})

    if not repo.delete_player(player_id):
        raise HTTPException(500, detail={"error": {"code": "INTERNAL_ERROR", "message": "Failed to delete player"}})

src/backend/arena/api/routes/replay.py:
"""Replay routes — hand history queries for post-match review."""

from __future__ import annotations

import json
from typing import Any

from fastapi import APIRouter, HTTPException, Request

router = APIRouter(tags=["replay"])


def _repo(request: Request):
    return request.app.state.db_repo


def _build_table_detail(
    repo,
    table_hand: dict,
    match_id: str,
    hand_num: int,
    dealer: str,
    idle_seat: str,
    seed: str,
) -> dict[str, Any]:
    """Build the full table detail response for a single table_hand."""
    th_id = table_hand["id"]
    table = table_hand["table"]

    # Get participants for this match
    participants = repo.get_participants(match_id)
    agent_map: dict[str, dict] = {}
    for p in participants:
        player = repo.get_player(p["player_id"])
        if player:
            agent_map[p["player_id"]] = player
        # Determine seat on this table
    seat_agent: dict[str, str] = {}
    seat_team: dict[str, str] = {}
    for p in participants:
        seat_key = f"seat_table_{table.lower()}"
        seat = p.get(seat_key)
        if seat:
            seat_agent[seat] = p["player_id"]
            seat_team[seat] = p["team"]

    # Determine roles
    landlord_seat = table_hand.get("landlord_seat")
    idle_participation = table_hand.get("idle_participation")
    if isinstance(idle_participation, str) and idle_participation:
        try:
            idle_participation = json.loads(idle_participation)
        except json.JSONDecodeError:
            idle_participation = {}
    # Double-encoded JSON edge case (e.g. '"{}"' becomes the string '{}')
    if isinstance(idle_participation, str):
        try:
            idle_participation = json.loads(idle_participation)
        except json.JSONDecodeError:
            idle_participation = {}
    if not isinstance(idle_participation, dict):
        idle_participation = {}

    # Build players dict
    players: dict[str, dict[str, str]] = {}
    for seat in ["S", "E", "N", "W"]:
        aid = seat_agent.get(seat, "")
        team = seat_team.get(seat, "")
        role = "idle" if seat == idle_seat else "farmer"
        if seat == landlord_seat:
            role = "landlord"
        if idle_participation and idle_participation.get("triggered"):
            if seat == idle_participation.get("replaced_by_idle"):
                role = "farmer"
            if seat == idle_participation.get("original_farmer"):
                role = "idle"
        display_name = agent_map.get(aid, {}).get("display_name") or aid
        players[seat] = {
            "agent_id": aid,
            "agent_name": display_name,
            "team": team,
            "role": role,
        }

    # Bidding
    bidding_records = repo.get_bidding_records(th_id)
    bidding = [
        {"seq": r["seq"], "seat": r["seat"], "bid": r["bid"], "timestamp_ms": r["timestamp_ms"]}
        for r in bidding_records
    ]

    # Play history
    play_actions = repo.get_play_actions_for_table(th_id)
    play_history = []
    for a in play_actions:
        cards = a.get("cards")
        if isinstance(cards, str):
            cards = json.loads(cards)
        play_history.append({
            "seq": a["seq"],
            "round": a["round"],
            "sub_round": a["sub_round"],
            "seat": a["seat"],
            "action": {
                "type": a["action_type"],
                "cards": cards if a["action_type"] == "play" else None,
                "pattern": a.get("pattern") if a["action_type"] == "play" else None,
            },
            "timestamp_ms": a["timestamp_ms"],
        })

    # Initial hands
    initial_hands = repo.get_initial_hands_for_table(th_id)

    # Remaining hands
    remaining_hands = repo.get_remaining_hands_for_table(th_id)

    # Result
    result = None
    if table_hand.get("status") in ("finished",):
        result = {
            "winner_team": table_hand.get("winner_team"),
            "winner_role": table_hand.get("winner_role"),
            "base_score": table_hand.get("base_score"),
            "multiplier": table_hand.get("multiplier"),
            "final_score": table_hand.get("final_score"),
            "bombs_played": table_hand.get("bombs_played", 0),
            "spring": bool(table_hand.get("spring")),
            "anti_spring": bool(table_hand.get("anti_spring")),
        }

    # Agent thoughts
    thoughts = repo.get_agent_thoughts_for_table(th_id)
    agent_thoughts = []
    for t in thoughts:
        decision = t.get("decision", "{}")
        if isinstance(decision, str):
            try:
                decision = json.loads(decision)
            except json.JSONDecodeError:
                decision = {"raw": decision}
        agent_thoughts.append({
            "seat": t["seat"],
            "phase": t["phase"],
            "round": t.get("round"),
            "sub_round": t.get("sub_round"),
            "timestamp_ms": t["timestamp_ms"],
            "reasoning": t["reasoning"],
            "decision": decision,
        })

    # Reflections
    reflection_rows = repo.get_reflections_for_table(th_id)
    reflections = []
    for r in reflection_rows:
        reflections.append({
            "player_id": r["player_id"],
            "seat": r["seat"],
            "actual_role": r["actual_role"],
            "reflection": r["reflection"],
            "short_term_memory": r["short_term_memory"],
        })

    # Idle participation detail
    idle_detail = {
        "triggered": False,
        "idle_seat": idle_seat,
        "reason": "No idle participation triggered",
    }
    if idle_participation and isinstance(idle_participation, dict):
        idle_detail = {
            "triggered": idle_participation.get("triggered", False),
            "original_farmer": idle_participation.get("original_farmer", idle_seat),
            "replaced_by_idle": idle_participation.get("replaced_by_idle", ""),
            "reason": idle_participation.get("reason", ""),
        }

    return {
        "table_id": table,
        "is_void": bool(table_hand.get("void")),
        "players": players,
        "bidding": bidding,
        "landlord": landlord_seat,
        "final_bid": table_hand.get("final_bid", 0),
        "dizhu_cards": _parse_cards_str(table_hand.get("dizhu_cards", "[]")),
        "initial_hands": initial_hands,
        "play_history": play_history,
        "result": result,
        "remaining_hands": remaining_hands,
        "agent_thoughts": agent_thoughts,
        "reflections": reflections,
        "idle_participation": idle_detail,
    }


def _parse_cards_str(cards_str: str) -> list[str]:
    """Parse cards from DB storage format (comma-separated or JSON array)."""
    if not cards_str or cards_str == "[]":
        return []
    if cards_str.startswith("["):
        return json.loads(cards_str)
    # comma-separated format
    return [c.strip() for c in cards_str.split(",") if c.strip()]


@router.get("/matches/{match_id}/hands")
async def list_hand_summaries(match_id: str, request: Request):
    """Get summaries of all hands in a match, with AB table diff results."""
    repo = _repo(request)
    match = repo.get_match(match_id)
    if not match:
        raise HTTPException(404, detail={"error": {"code": "MATCH_NOT_FOUND", "message": f"Match not found: {match_id}"}})

    hands = repo.get_hands_for_match(match_id)
    participants = repo.get_participants(match_id)

    # Build player_id → name map
    agent_names: dict[str, str] = {}
    for p in participants:
        player = repo.get_player(p["player_id"])
        agent_names[p["player_id"]] = player["display_name"] if player else p["player_id"]

    total_hands = len(hands)
    hand_summaries = []
    running_red = 0
    running_blue = 0

    for h in hands:
        hand_num = h["hand_num"]
        table_hands = repo.get_table_hands_for_hand(h["id"])

        table_a_data = None
        table_b_data = None

        for th in table_hands:
            entry = _build_table_summary(th, participants, agent_names)
            if th["table"] == "A":
                table_a_data = entry
            else:
                table_b_data = entry

        # Diff result
        hand_diff = {"red_diff": 0, "running_total": {"red": running_red, "blue": running_blue}}
        if h.get("status") == "finished":
            red_diff = h.get("diff_score_red", 0) or 0
            blue_diff = h.get("diff_score_blue", 0) or 0
            running_red += red_diff
            running_blue += blue_diff
            hand_diff = {
                "red_diff": red_diff,
                "blue_diff": blue_diff,
                "running_total": {"red": running_red, "blue": running_blue},
            }

        hand_summaries.append({
            "hand_num": hand_num,
            "dealer": h["dealer"],
            "table_a": table_a_data,
            "table_b": table_b_data,
            "diff_result": hand_diff,
        })

    return {
        "match_id": match_id,
        "total_hands": total_hands,
        "hands": hand_summaries,
    }


def _build_table_summary(
    table_hand: dict,
    participants: list[dict],
    agent_names: dict[str, str],
) -> dict[str, Any]:
    """Build a compact table summary for the hands list."""
    th_id = table_hand["id"]
    table = table_hand["table"]

    # Find landlord player
    landlord_seat = table_hand.get("landlord_seat", "")
    landlord_agent = ""
    for p in participants:
        if p.get(f"seat_table_{table.lower()}") == landlord_seat:
            landlord_agent = p["player_id"]
            break

    return {
        "landlord_seat": landlord_seat,
        "landlord_agent": landlord_agent,
        "bid": table_hand.get("final_bid", 0),
        "score": {
            "red": table_hand.get("final_score", 0) if table_hand.get("winner_team") == "red" else 0,
            "blue": table_hand.get("final_score", 0) if table_hand.get("winner_team") == "blue" else 0,
        },
        "bombs_played": table_hand.get("bombs_played", 0),
        "spring": bool(table_hand.get("spring")),
        "void": bool(table_hand.get("void")),
    }


@router.get("/matches/{match_id}/hands/{hand_num}")
async def get_hand_detail(match_id: str, hand_num: int, request: Request):
    """Get full detail for a single hand, including both tables."""
    repo = _repo(request)
    match = repo.get_match(match_id)
    if not match:
        raise HTTPException(404, detail={"error": {"code": "MATCH_NOT_FOUND", "message": f"Match not found: {match_id}"}})

    hand = repo.get_hand_by_num(match_id, hand_num)
    if not hand:
        raise HTTPException(404, detail={"error": {"code": "HAND_NOT_FOUND", "message": f"Hand {hand_num} not found"}})

    table_hands = repo.get_table_hands_for_hand(hand["id"])
    if not table_hands:
        raise HTTPException(404, detail={"error": {"code": "HAND_NOT_FOUND", "message": f"No table hands found for hand {hand_num}"}})

    table_a_detail = None
    table_b_detail = None

    for th in table_hands:
        detail = _build_table_detail(
            repo, th, match_id, hand_num,
            hand["dealer"], hand["idle_seat"], hand["seed"],
        )
        if th["table"] == "A":
            table_a_detail = detail
        else:
            table_b_detail = detail

    # Diff score
    red_diff = hand.get("diff_score_red", 0) or 0
    blue_diff = hand.get("diff_score_blue", 0) or 0

    return {
        "hand_num": hand_num,
        "dealer": hand["dealer"],
        "seed": hand["seed"],
        "idle_seat": hand["idle_seat"],
        "table_a": table_a_detail,
        "table_b": table_b_detail,
        "diff_score": {
            "red_net": red_diff,
            "blue_net": blue_diff,
            "diff": max(red_diff, blue_diff),
            "capped": bool(hand.get("diff_capped")),
        },
    }


@router.get("/matches/{match_id}/hands/{hand_num}/table/{table_id}")
async def get_single_table_hand(
    match_id: str, hand_num: int, table_id: str, request: Request,
):
    """Get detailed replay data for a single table in a single hand."""
    if table_id not in ("a", "b", "A", "B"):
        raise HTTPException(400, detail={"error": {"code": "INVALID_REQUEST", "message": "table must be 'a' or 'b'"}})
    table_id = table_id.upper()

    repo = _repo(request)
    match = repo.get_match(match_id)
    if not match:
        raise HTTPException(404, detail={"error": {"code": "MATCH_NOT_FOUND", "message": f"Match not found: {match_id}"}})

    hand = repo.get_hand_by_num(match_id, hand_num)
    if not hand:
        raise HTTPException(404, detail={"error": {"code": "HAND_NOT_FOUND", "message": f"Hand {hand_num} not found"}})

    table_hands = repo.get_table_hands_for_hand(hand["id"])
    target_th = None
    for th in table_hands:
        if th["table"] == table_id:
            target_th = th
            break

    if target_th is None:
        raise HTTPException(404, detail={"error": {"code": "HAND_NOT_FOUND", "message": f"Table {table_id} data not found for hand {hand_num}"}})

    return _build_table_detail(
        repo, target_th, match_id, hand_num,
        hand["dealer"], hand["idle_seat"], hand["seed"],
    )


@router.get("/matches/{match_id}/events")
async def get_events(match_id: str, request: Request, after: int = 0, limit: int = 500):
    repo = _repo(request)
    if not repo.get_match(match_id):
        raise HTTPException(404, detail="match not found")
    if after < 0 or limit < 1 or limit > 1000:
        raise HTTPException(400, detail="invalid cursor or limit")
    rows = repo.conn.execute("SELECT event_json FROM match_events WHERE match_id=? AND seq>? ORDER BY seq LIMIT ?", (match_id, after, limit)).fetchall()
    watermark = repo.conn.execute("SELECT COALESCE(MAX(seq),0) FROM match_events WHERE match_id=?", (match_id,)).fetchone()[0]
    return {"stream_id": match_id, "watermark": watermark, "events": [json.loads(r[0]) for r in rows]}

src/backend/arena/api/ws.py:
"""WebSocket handler for real-time match streaming.

Implements the WS protocol defined in the API design plan:
- Client connects to /ws/match/{match_id}
- Server sends match_state (full snapshot) on connect
- Server continuously polls MatchEventBus and streams events to clients
- Client can send: subscribe, pause_request, resume_request, ping
"""

from __future__ import annotations

import asyncio
import json
import logging
from typing import Any

from fastapi import APIRouter, WebSocket, WebSocketDisconnect

from .event_bus import MatchEventBus

logger = logging.getLogger(__name__)

router = APIRouter()

# Global registry of active WebSocket connections per match
_connections: dict[str, set[WebSocket]] = {}


def _get_repo(ws: WebSocket):
    return ws.app.state.db_repo


def _get_active_matches(ws: WebSocket) -> dict:
    if not hasattr(ws.app.state, "active_matches"):
        ws.app.state.active_matches = {}
    return ws.app.state.active_matches


async def broadcast(match_id: str, event: dict[str, Any]) -> None:
    """Send an event to all connected clients for a given match."""
    if match_id not in _connections:
        return
    dead: list[WebSocket] = []
    message = json.dumps(event, ensure_ascii=False)
    for ws in list(_connections[match_id]):
        try:
            await ws.send_text(message)
        except Exception:
            dead.append(ws)
    for ws in dead:
        _connections[match_id].discard(ws)
    if not _connections[match_id]:
        del _connections[match_id]


async def _send_error(ws: WebSocket, code: str, message: str, table: str = "", hand_num: int = 0, seat: str = "") -> None:
    """Send an error event to a single WebSocket client."""
    await ws.send_json({
        "type": "error",
        "payload": {
            "code": code,
            "table": table,
            "hand_num": hand_num,
            "seat": seat,
            "message": message,
            "severity": "error",
        },
    })


def _build_match_state(repo, match: dict, runner) -> dict[str, Any]:
    """Build the full match_state snapshot payload."""
    tables: dict[str, dict[str, Any]] = {}
    for table_key in ("A", "B"):
        table_runner = runner.table_a if table_key == "A" else runner.table_b
        state = table_runner._state
        players: dict[str, dict[str, Any]] = {}
        for seat in ["S", "E", "N", "W"]:
            player_id = state.seat_agents.get(seat, "")
            player = repo.get_player(player_id) if player_id else None
            team = state.seat_teams.get(seat, "")
            role = state.role_of(seat) if state.phase and state.phase.value not in ("dealing",) else ""
            hand = state.live_hands.get(seat)
            hand_size = hand.size if hand else 0
            # Include hand cards for spectator view (god mode)
            hand_cards = [str(c) for c in hand.cards] if hand else []
            players[seat] = {
                "agent_name": player["display_name"] if player else "",
                "player_id": player_id,
                "team": team,
                "role": role,
                "hand_size": hand_size,
                "hand_cards": hand_cards,
            }

        play_history = []
        for r in state.play_history:
            play_history.append({
                "round": r.round_num,
                "sub_round": r.sub_round,
                "seat": r.seat,
                "action": {
                    "type": r.action_type,
                    "cards": [str(c) for c in r.cards] if r.cards else None,
                    "pattern": r.trick.pattern.value if r.trick else None,
                    "display": r.trick.display() if r.trick else None,
                },
                "timestamp_ms": r.timestamp_ms,
            })

        current_pattern = None
        if state.current_trick:
            current_pattern = {
                "pattern": state.current_trick.pattern.value,
                "length": state.current_trick.length,
                "max_rank": str(state.current_trick.main_rank) if state.current_trick.main_rank else None,
            }

        # Build bidding_order from game state
        bidding_order = list(state.bidding_order) if state.bidding_order else []
        idle_seat = getattr(state, 'original_idle', '')
        effective_idle = getattr(state, 'effective_idle', idle_seat)

        # Build bidding_history from game state
        bidding_history = [
            {"seat": r.seat, "bid": r.bid}
            for r in state.bidding_history
        ]

        # Determine current_seat for all phases
        current_seat = ""
        if state.phase:
            if state.phase.value == "playing":
                current_seat = state.current_player
            elif state.phase.value == "bidding" and state.bidding_order and state.current_bidder_idx < len(state.bidding_order):
                current_seat = state.bidding_order[state.current_bidder_idx]

        tables[table_key] = {
            "phase": state.phase.value if state.phase else "",
            "hand_num": state.hand_num,
            "current_seat": current_seat,
            "current_pattern": current_pattern,
            "dealer": state.dealer,
            "landlord": state.landlord,
            "dizhu_cards": [str(c) for c in state.dizhu_cards] if state.dizhu_cards else [],
            "players": players,
            "play_history": play_history,
            "bidding_order": bidding_order,
            "idle_seat": idle_seat,
            "effective_idle": effective_idle,
            "bidding_history": bidding_history,
            "current_high_bid": state.current_high_bid,
            "current_high_bidder": state.current_high_bidder,
            "time_remaining": {
                "red_team_ms": 0,
                "blue_team_ms": 0,
            },
            "turn_timer": getattr(table_runner, "active_turn", None),
        }

    announced = runner.event_bus.announced_hand if runner.event_bus else None
    if announced:
        for key in ("A", "B"):
            if tables[key]["hand_num"] < announced["hand_num"]:
                tables[key] = {**announced["tables"][key], "hand_num": announced["hand_num"]}

    return {
        "match_id": match["id"],
        "status": match["status"],
        "current_hand": max(match.get("current_hand", 0), announced["hand_num"] if announced else 0),
        "score": {
            "red": match.get("score_red", 0),
            "blue": match.get("score_blue", 0),
        },
        "tables": tables,
    }


def build_persisted_match_state(repo, match):
    """An inactive match still has an authoritative snapshot on reconnect."""
    from .routes.replay import _build_table_detail
    bus = MatchEventBus(match['id'], repo=repo)
    tables = {}
    hands = repo.get_hands_for_match(match['id'])
    if hands:
        hand = hands[-1]
        for th in repo.get_table_hands_for_hand(hand['id']):
            detail = _build_table_detail(repo, th, match['id'], hand['hand_num'], hand['dealer'], hand['idle_seat'], hand['seed'])
            remaining = repo.get_remaining_hands_for_table(th['id'])
            players = {}
            for seat, player in detail.get('players', {}).items():
                cards = remaining.get(seat, detail.get('initial_hands', {}).get(seat, []))
                players[seat] = {**player, 'hand_cards': cards, 'hand_size': len(cards)}
            effective_idle = next((s for s, p in players.items() if p['role'] == 'idle'), hand['idle_seat'])
            tables[th['table']] = {**detail, 'phase': th['status'], 'players': players,
                'hand_num': hand['hand_num'], 'dealer': hand['dealer'], 'current_seat': '',
                'current_pattern': None, 'turn_timer': None,
                'idle_seat': hand['idle_seat'], 'effective_idle': effective_idle}
    bus.snapshot_factory = lambda: {'match_id': match['id'], 'status': match['status'],
        'current_hand': hands[-1]['hand_num'] if hands else 0,
        'score': {'red': match['score_red'], 'blue': match['score_blue']}, 'tables': tables, 'live': False}
    return bus.snapshot()


@router.websocket("/ws/match/{match_id}")
async def match_ws(ws: WebSocket, match_id: str):
    """WebSocket endpoint for real-time match viewing."""
    await ws.accept()
    repo = _get_repo(ws)

    match = repo.get_match(match_id)
    if not match:
        await _send_error(ws, "MATCH_NOT_FOUND", f"Match not found: {match_id}")
        await ws.close()
        return

    _connections.setdefault(match_id, set()).add(ws)

    runner = _get_active_matches(ws).get(match_id)
    bus = runner.event_bus if runner else None
    subscription = bus.subscribe() if bus else None
    # Subscribe and capture snapshot synchronously on this event loop. No event
    # can be published between these operations; queued events follow watermark.
    if bus:
        state = bus.snapshot()
        watermark = state["watermark"]
        await ws.send_json({"type": "match_state", "payload": state})
    else:
        state = build_persisted_match_state(repo, match)
        watermark = state['watermark']
        await ws.send_json({'type': 'match_state', 'payload': state})
    relay_task = asyncio.create_task(_relay_events(ws, subscription, watermark)) if subscription else None

    try:
        while True:
            try:
                data = await asyncio.wait_for(ws.receive_text(), timeout=30.0)
            except asyncio.TimeoutError:
                await ws.send_json({"type": "pong"})
                continue

            try:
                msg = json.loads(data)
            except json.JSONDecodeError:
                await _send_error(ws, "INVALID_REQUEST", "Invalid JSON")
                continue

            msg_type = msg.get("type", "")

            if msg_type == "ping":
                await ws.send_json({"type": "pong"})

            elif msg_type == "pong":
                pass

            elif msg_type == "subscribe":
                # State events are never filtered: filtering would create sequence gaps.
                # Clients may filter presentation locally.
                if bus:
                    await ws.send_json({"type": "match_state", "payload": bus.snapshot()})

            elif msg_type == "pause_request":
                active_matches = _get_active_matches(ws)
                r = active_matches.get(match_id)
                if r:
                    r.request_pause()
                    repo.update_match_status(match_id, "paused")
                    bus2 = r.event_bus if hasattr(r, 'event_bus') else None
                    if bus2:
                        await bus2.emit_match_paused("user_requested", match.get("current_hand", 0), _now_ms())

            elif msg_type == "resume_request":
                active_matches = _get_active_matches(ws)
                r = active_matches.get(match_id)
                if r:
                    # Resume match-level pause (unblocks _check_pause in run() loop)
                    r.pause.resume()
                    # Resume table-level pauses (unblocks _check_pause in play/bid loops)
                    r.resume_tables()
                    repo.update_match_status(match_id, "running")
                    bus2 = r.event_bus if hasattr(r, 'event_bus') else None
                    if bus2:
                        await bus2.emit_match_resumed(match.get("current_hand", 0), _now_ms())

            else:
                await _send_error(ws, "INVALID_REQUEST", f"Unknown message type: {msg_type}")

    except WebSocketDisconnect:
        pass
    finally:
        if bus and subscription:
            bus.unsubscribe(subscription)
        if relay_task and not relay_task.done():
            relay_task.cancel()
            try:
                await relay_task
            except asyncio.CancelledError:
                pass
        conns = _connections.get(match_id, set())
        conns.discard(ws)
        if not conns:
            _connections.pop(match_id, None)


async def _relay_events(ws, subscription, watermark=0):
    while True:
        event = await subscription.get()
        if event is None:
            break
        if event.get("seq", watermark + 1) <= watermark:
            continue
        try:
            await asyncio.wait_for(ws.send_json(event), timeout=5.0)
            if event["type"] == "resync_required":
                await ws.close(code=1013)
                break
        except (asyncio.TimeoutError, Exception):
            await ws.close(code=1013)
            break


def _now_ms() -> int:
    import time
    return int(time.time() * 1000)

src/backend/arena/config/paths.py:
"""Shared paths for the repository layout used locally and under /app in Docker."""

from pathlib import Path


def find_project_root(source: Path) -> Path:
    for candidate in source.resolve().parents:
        if (candidate / "src/backend/arena").is_dir():
            return candidate
    raise RuntimeError("Deployment must contain src/backend/arena under its project root")


PROJECT_ROOT = find_project_root(Path(__file__))
BACKEND_DIR = PROJECT_ROOT / "src/backend"
CONFIG_DIR = BACKEND_DIR / "arena/config"
EVALUATION_DIR = BACKEND_DIR / "evaluation"


def project_path(value: str | Path) -> Path:
    """Configuration paths are relative to the project, never the working directory."""
    return (PROJECT_ROOT / Path(value).expanduser()).resolve()


def sqlite_path(url: str) -> str:
    if not url.startswith("sqlite:///"):
        raise ValueError("DATABASE_URL must use sqlite:///relative/path or sqlite:////absolute/path")
    value = url.removeprefix("sqlite:///")
    if not value:
        raise ValueError("DATABASE_URL must include a database path")
    return value if value == ":memory:" else str(project_path(value))

src/backend/arena/db/memory.py:
"""Atomic match settlement and traceable, immutable memory snapshots."""

from __future__ import annotations

import hashlib
import json
import re
from typing import Any

from . import models


class MemoryConflictError(ValueError):
    """A memory snapshot changed or an idempotency key was reused."""


DDL = """
CREATE TABLE IF NOT EXISTS memory_schema_migrations (
    name TEXT PRIMARY KEY, applied_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS match_settlements (
    match_id TEXT PRIMARY KEY REFERENCES matches(id) ON DELETE CASCADE,
    winner_team TEXT NOT NULL, source TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS memory_versions (
    id TEXT PRIMARY KEY, player_id TEXT NOT NULL, match_id TEXT,
    content TEXT NOT NULL, content_hash TEXT NOT NULL, revision INTEGER NOT NULL,
    previous_id TEXT REFERENCES memory_versions(id), source_json TEXT NOT NULL,
    created_at TEXT NOT NULL, UNIQUE(player_id, revision)
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_memory_version_match
    ON memory_versions(player_id, match_id) WHERE match_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_memory_version_player
    ON memory_versions(player_id, revision DESC);
CREATE TABLE IF NOT EXISTS match_memory_usage (
    id TEXT PRIMARY KEY, match_id TEXT NOT NULL, player_id TEXT NOT NULL,
    version_id TEXT NOT NULL REFERENCES memory_versions(id), created_at TEXT NOT NULL,
    UNIQUE(match_id, player_id)
);
CREATE TABLE IF NOT EXISTS memory_failures (
    id TEXT PRIMARY KEY, player_id TEXT NOT NULL, match_id TEXT NOT NULL,
    table_hand_id TEXT, phase TEXT NOT NULL, stage TEXT NOT NULL,
    error_type TEXT NOT NULL, created_at TEXT NOT NULL, resolved_at TEXT,
    resolution_version_id TEXT REFERENCES memory_versions(id)
);
CREATE INDEX IF NOT EXISTS idx_memory_failure_match
    ON memory_failures(match_id, player_id, phase);
"""


def init(conn) -> None:
    """Add tables without changing old rows or re-counting completed matches."""
    conn.executescript(DDL)
    marker = "memory_persistence_v1"
    if conn.execute(
        "SELECT 1 FROM memory_schema_migrations WHERE name = ?", (marker,)
    ).fetchone():
        return
    # Old finished matches may already have incremented player statistics. Their
    # historical counters are retained, rather than guessed or counted again.
    conn.execute(
        """INSERT OR IGNORE INTO match_settlements
           (match_id, winner_team, source, created_at)
           SELECT id, CASE WHEN score_red > score_blue THEN 'red'
                           WHEN score_blue > score_red THEN 'blue' ELSE 'tie' END,
                  'legacy', COALESCE(finished_at, created_at)
           FROM matches WHERE status = 'finished'"""
    )
    conn.execute(
        "INSERT INTO memory_schema_migrations(name, applied_at) VALUES (?, ?)",
        (marker, models._now()),
    )
    conn.commit()


def settle_match(repo, match_id: str, winner_team: str,
                 player_teams: dict[str, str], **finish_fields: Any) -> bool:
    if winner_team not in {"red", "blue", "tie"}:
        raise ValueError("invalid winner team")
    if any(team not in {"red", "blue"} for team in player_teams.values()):
        raise ValueError("invalid player team")
    with repo.atomic():
        if repo.conn.execute(
            "SELECT 1 FROM match_settlements WHERE match_id = ?", (match_id,)
        ).fetchone():
            return False
        if repo.get_match(match_id) is None:
            raise ValueError("match does not exist")
        repo.conn.execute(
            "INSERT INTO match_settlements VALUES (?, ?, 'match', ?)",
            (match_id, winner_team, models._now()),
        )
        repo.update_match_status(match_id, "finished", **finish_fields)
        settled = repo.get_match(match_id)
        for player_id, team in player_teams.items():
            # UPDATE deliberately affects zero rows for programmatic/evaluation
            # agents that have no persistent player identity.
            repo.update_player_stats(
                player_id, matches_played_delta=1,
                matches_won_delta=int(team == winner_team),
                total_score_delta=settled[f"score_{team}"] or 0,
            )
    return True


def _hash(content: str) -> str:
    return hashlib.sha256(content.encode("utf-8")).hexdigest()


def _source(source: dict | str | None, default: str) -> dict:
    """Provenance is structured metadata, never credentials or request bodies."""
    if isinstance(source, str):
        source = {"kind": source}
    source = source or {"kind": default}
    allowed = {"kind", "provider", "model", "prompt_sha256", "source_revision",
               "artifact_sha256", "source_match_id", "schema_version"}
    return {
        key: value for key, value in source.items()
        if key in allowed and isinstance(value, (str, int, float, bool))
    }


def _version(row) -> dict | None:
    if row is None:
        return None
    result = dict(row)
    result["source"] = json.loads(result.pop("source_json"))
    return result


def get_memory_version(repo, version_id: str) -> dict | None:
    return _version(repo.conn.execute(
        "SELECT * FROM memory_versions WHERE id = ?", (version_id,)
    ).fetchone())


def list_memory_versions(repo, player_id: str, limit: int = 100) -> list[dict]:
    rows = repo.conn.execute(
        "SELECT * FROM memory_versions WHERE player_id = ? ORDER BY revision DESC LIMIT ?",
        (player_id, max(1, min(limit, 1000))),
    ).fetchall()
    return [_version(row) for row in rows]


def _latest(repo, player_id: str) -> dict | None:
    return _version(repo.conn.execute(
        "SELECT * FROM memory_versions WHERE player_id = ? ORDER BY revision DESC LIMIT 1",
        (player_id,),
    ).fetchone())


def _insert_version(repo, player_id: str, content: str, match_id: str | None,
                    previous: dict | None, source: dict) -> dict:
    version_id = models._uid()
    revision = (previous["revision"] if previous else 0) + 1
    repo.conn.execute(
        """INSERT INTO memory_versions
           (id, player_id, match_id, content, content_hash, revision,
            previous_id, source_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
        (version_id, player_id, match_id, content, _hash(content), revision,
         previous["id"] if previous else None,
         json.dumps(source, ensure_ascii=False, sort_keys=True), models._now()),
    )
    return get_memory_version(repo, version_id)


def freeze_match_memory(repo, match_id: str, player_id: str,
                        content: str | None = None,
                        source: dict | str | None = None) -> dict:
    """Record the exact initial prompt memory once per player and match."""
    from ..agent.memory import MAX_LONG_TERM_CHARS, validate_memory_text

    if not match_id:
        raise ValueError("match id is required")
    if content is not None:
        content = validate_memory_text(content, max_chars=MAX_LONG_TERM_CHARS, allow_empty=True)
    with repo.atomic():
        existing = repo.conn.execute(
            "SELECT * FROM match_memory_usage WHERE match_id = ? AND player_id = ?",
            (match_id, player_id),
        ).fetchone()
        if existing:
            version = get_memory_version(repo, existing["version_id"])
            if content is not None and version["content"] != content:
                raise MemoryConflictError("match memory is already frozen")
            return {**version, "usage_id": existing["id"], "used_in_match_id": match_id}
        previous = _latest(repo, player_id)
        if content is None:
            player = repo.get_player(player_id)
            content = (player.get("long_term_memory") or "") if player else (
                previous["content"] if previous else ""
            )
            content = validate_memory_text(content, max_chars=MAX_LONG_TERM_CHARS, allow_empty=True)
        version = previous
        if version is None or version["content"] != content:
            version = _insert_version(
                repo, player_id, content, None, previous, _source(source, "initial_snapshot"),
            )
        usage_id = models._uid()
        repo.conn.execute(
            "INSERT INTO match_memory_usage VALUES (?, ?, ?, ?, ?)",
            (usage_id, match_id, player_id, version["id"], models._now()),
        )
        return {**version, "usage_id": usage_id, "used_in_match_id": match_id}


def list_match_memory_usage(repo, match_id: str,
                            player_id: str | None = None) -> list[dict]:
    clause = " AND u.player_id = ?" if player_id is not None else ""
    params = (match_id, player_id) if player_id is not None else (match_id,)
    rows = repo.conn.execute(
        """SELECT v.*, u.id AS usage_id, u.match_id AS used_in_match_id,
                  u.created_at AS used_at FROM match_memory_usage u
           JOIN memory_versions v ON v.id = u.version_id WHERE u.match_id = ?"""
        + clause + " ORDER BY u.player_id", params,
    ).fetchall()
    return [_version(row) for row in rows]


def save_long_term_memory(repo, player_id: str, content: str, match_id: str | None,
                          expected_content: str | None = None,
                          source: dict | str | None = None) -> dict:
    from ..agent.memory import MAX_LONG_TERM_CHARS, validate_memory_text

    content = validate_memory_text(content, max_chars=MAX_LONG_TERM_CHARS)
    if expected_content is not None:
        # A manual repair may replace an oversized legacy value. The old text
        # is a comparison token and archival input, never new prompt memory.
        if not isinstance(expected_content, str):
            raise ValueError("expected memory must be text")
        expected_content = expected_content.strip()
    with repo.atomic():
        if match_id:
            existing = _version(repo.conn.execute(
                "SELECT * FROM memory_versions WHERE player_id = ? AND match_id = ?",
                (player_id, match_id),
            ).fetchone())
            if existing:
                if existing["content"] != content:
                    raise MemoryConflictError("match memory was already saved with different content")
                resolve_memory_failures(repo, player_id, match_id, "summary",
                                        version_id=existing["id"])
                return existing
        player = repo.get_player(player_id)
        previous = _latest(repo, player_id)
        original = (player.get("long_term_memory") or "") if player else (
            previous["content"] if previous else (expected_content or "")
        )
        current = original.strip()
        if match_id:
            current = validate_memory_text(current, max_chars=MAX_LONG_TERM_CHARS, allow_empty=True)
            usage = repo.conn.execute(
                "SELECT version_id FROM match_memory_usage WHERE match_id = ? AND player_id = ?",
                (match_id, player_id),
            ).fetchone()
            # Content alone misses A -> B -> A changes, including a newer
            # successful summary that deliberately retained the same lesson.
            if usage and (previous is None or previous["id"] != usage["version_id"]):
                raise MemoryConflictError("player memory version changed since the match started")
            if usage and previous["content"] != current:
                raise MemoryConflictError("player memory changed since the match started")
        if expected_content is not None and current != expected_content:
            raise MemoryConflictError("player memory changed since the match started")
        # Preserve an imported/legacy value before replacing it, even when the
        # caller did not explicitly freeze a starting snapshot.
        if previous is None or previous["content"] != current:
            previous = _insert_version(
                repo, player_id, original, None, previous, {"kind": "initial_snapshot"},
            )
        repo.update_player_long_term_memory(player_id, content)
        version = _insert_version(
            repo, player_id, content, match_id or None, previous,
            _source(source, "match_summary" if match_id else "manual_update"),
        )
        repo.add_agent_memory(player_id, "long_term", content, match_id=match_id)
        if match_id:
            resolve_memory_failures(repo, player_id, match_id, "summary", version_id=version["id"])
        return version


def save_reflection_memory(repo, table_hand_id: str, player_id: str, seat: str,
                           actual_role: str, reflection: str,
                           short_term_memory: str, match_id: str) -> str:
    from ..agent.memory import MAX_SHORT_TERM_CHARS, validate_memory_text

    short_term_memory = validate_memory_text(
        short_term_memory, max_chars=MAX_SHORT_TERM_CHARS, allow_empty=True,
    )
    with repo.atomic():
        reflection_id = repo.add_reflection(
            table_hand_id, player_id=player_id, seat=seat, actual_role=actual_role,
            reflection=reflection, short_term_memory=short_term_memory,
        )
        if short_term_memory:
            repo.add_agent_memory(player_id, "short_term", short_term_memory, match_id=match_id)
        resolve_memory_failures(repo, player_id, match_id, "reflection", table_hand_id=table_hand_id)
        return reflection_id


def record_memory_failure(repo, player_id: str, match_id: str, phase: str,
                          stage: str, error: BaseException | str,
                          table_hand_id: str | None = None) -> str:
    if phase not in {"reflection", "summary"} or stage not in {"generation", "persistence"}:
        raise ValueError("invalid memory failure phase or stage")
    # Exception messages may contain provider request headers or credentials.
    # Store only a type name or one of the intentionally safe application codes.
    safe_codes = {"empty_response", "memory_conflict", "cancelled", "invalid_response"}
    error_type = type(error).__name__ if isinstance(error, BaseException) else (
        error if error in safe_codes else "OperationFailed"
    )
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,79}", error_type):
        error_type = "OperationFailed"
    failure_id = models._uid()
    repo.conn.execute(
        """INSERT INTO memory_failures
           (id, player_id, match_id, table_hand_id, phase, stage, error_type, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
        (failure_id, player_id, match_id, table_hand_id, phase, stage, error_type, models._now()),
    )
    repo.conn.commit()
    return failure_id


def resolve_memory_failures(repo, player_id: str, match_id: str, phase: str,
                            table_hand_id: str | None = None,
                            version_id: str | None = None) -> None:
    clause = " AND table_hand_id = ?" if table_hand_id is not None else ""
    params = [models._now(), version_id, player_id, match_id, phase]
    if table_hand_id is not None:
        params.append(table_hand_id)
    repo.conn.execute(
        """UPDATE memory_failures SET resolved_at = ?, resolution_version_id = ?
           WHERE player_id = ? AND match_id = ? AND phase = ? AND resolved_at IS NULL"""
        + clause, params,
    )
    repo.conn.commit()


def list_memory_failures(repo, player_id: str | None = None,
                         match_id: str | None = None,
                         unresolved_only: bool = False) -> list[dict]:
    clauses, params = [], []
    for column, value in (("player_id", player_id), ("match_id", match_id)):
        if value is not None:
            clauses.append(f"{column} = ?")
            params.append(value)
    if unresolved_only:
        clauses.append("resolved_at IS NULL")
    where = " WHERE " + " AND ".join(clauses) if clauses else ""
    rows = repo.conn.execute(
        "SELECT * FROM memory_failures" + where + " ORDER BY created_at, id", params,
    ).fetchall()
    return [{**dict(row), "recovered": row["resolved_at"] is not None} for row in rows]

