"""High-level repository — wraps db/models functions with connection lifecycle.

Provides a single DatabaseRepository class that manages a sqlite3 connection
and exposes CRUD operations. Intended to be passed to MatchRunner/TableRunner
for persistence during match execution.
"""

from __future__ import annotations

import sqlite3
from contextlib import contextmanager
from pathlib import Path
from typing import Any

from . import models
from . import memory as memory_storage
from .memory import MemoryConflictError
from ..security.credentials import decrypt_secret, encrypt_secret, master_key_configured


class DatabaseRepository:
    """Repository wrapping a sqlite3 connection for arena data persistence.

    Usage:
        repo = DatabaseRepository("data/arena.db")
        repo.init()
        match_id = repo.create_match("Test Match", config, "seed123")
        # ... pass repo to MatchRunner ...
        repo.close()
    """

    def __init__(self, db_path: str) -> None:
        self._db_path = db_path
        self._conn: sqlite3.Connection | None = None

    # ── lifecycle ───────────────────────────────────────────────────────────────

    def init(self) -> None:
        """Initialize the database — create tables and run migrations."""
        Path(self._db_path).parent.mkdir(parents=True, exist_ok=True)
        self._conn = models.init_db(self._db_path)
        # Upgrade legacy plaintext rows when the deployment has a master key.
        if master_key_configured():
            rows = self.conn.execute("SELECT id, api_key FROM player_configs").fetchall()
            for row in rows:
                value = row[1] or ""
                if value and not value.startswith("enc:v1:") and not value.startswith("${"):
                    self.conn.execute("UPDATE player_configs SET api_key = ?, updated_at = updated_at WHERE id = ?", (encrypt_secret(value), row[0]))
            self.conn.commit()

    def close(self) -> None:
        if self._conn:
            self._conn.close()
            self._conn = None

    @contextmanager
    def atomic(self):
        """One transaction for committed action, thought and resolution."""
        conn = self.conn
        conn.execute("SAVEPOINT reliability_commit")
        conn.atomic_depth += 1
        try:
            yield
        except BaseException:
            conn.execute("ROLLBACK TO reliability_commit")
            raise
        finally:
            conn.execute("RELEASE reliability_commit")
            conn.atomic_depth -= 1

    def begin_decision(self, **data):
        from .reliability import begin_decision
        return begin_decision(self, **data)

    def add_agent_tool_call(self, **data):
        import uuid
        allowed = {"decision_id", "player_id", "model_attempt", "call_index", "tool_call_id",
                   "tool_name", "tool_version", "state_hash", "arguments_sha256", "response_sha256",
                   "elapsed_ms", "output_chars", "status", "metadata_json"}
        if set(data) != allowed:
            raise ValueError("invalid agent tool evidence fields")
        data = {"id": uuid.uuid4().hex, **data}
        columns = list(data)
        self.conn.execute(
            f"INSERT INTO agent_tool_calls ({','.join(columns)}) VALUES ({','.join('?' for _ in columns)})",
            list(data.values()),
        )
        self.conn.commit()

    def resolve_decision(self, decision_id, **data):
        from .reliability import resolve_decision
        return resolve_decision(self, decision_id, **data)

    @property
    def conn(self) -> sqlite3.Connection:
        if self._conn is None:
            raise RuntimeError("DatabaseRepository not initialized. Call init() first.")
        return self._conn

    # ── player_configs ──────────────────────────────────────────────────────────

    def create_player_config(
        self,
        name: str,
        provider: str,
        model: str,
        api_key: str,
        base_url: str | None = None,
        system_prompt: str | None = None,
        config_id: str = "",
    ) -> str:
        return models.insert_player_config(
            self.conn, name, provider, model, encrypt_secret(api_key),
            base_url=base_url, system_prompt=system_prompt, config_id=config_id,
        )

    def get_player_config(self, config_id: str) -> dict | None:
        return self._decrypt_config(models.get_player_config(self.conn, config_id))

