"""Hand — card collection with display ordering, grouping, and dizhu tracking."""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass, field

from .card import STRAIGHT_RANK_VALUES, Card, Rank


@dataclass
class Hand:
    """A player's hand of cards.

    Maintains cards in display order (rank desc, suit ♠>♥>♣>♦).
    Tracks which cards are dizhu cards (底牌) and their played status.
    """

    cards: list[Card] = field(default_factory=list)
    _dizhu_card_ids: set[int] = field(default_factory=set)
    _played_dizhu: set[int] = field(default_factory=set)

    # ── construction ──────────────────────────────────────────────────────

    @classmethod
    def from_cards(cls, cards: tuple[Card, ...] | list[Card]) -> Hand:
        """Create a hand sorted in display order."""
        h = cls()
        h.cards = sorted(cards, key=lambda c: c._sort_key())
        return h

    # ── dizhu tracking ────────────────────────────────────────────────────

    def mark_dizhu_cards(self, dizhu_cards: tuple[Card, ...]) -> None:
        """Mark which cards came from the dizhu (底牌). Call after landlord takes them."""
        self._dizhu_card_ids = {id(c) for c in dizhu_cards}

    def is_dizhu_card(self, card: Card) -> bool:
        return id(card) in self._dizhu_card_ids

    def dizhu_played_status(self) -> dict[str, bool]:
        """Returns {card_str: was_played} for each dizhu card."""
        return {
            str(c): id(c) in self._played_dizhu
            for c in self.cards
            if id(c) in self._dizhu_card_ids
        }

    @property
    def unplayed_dizhu(self) -> list[Card]:
        """Dizhu cards that have not yet been played."""
        return [
            c for c in self.cards
            if id(c) in self._dizhu_card_ids and id(c) not in self._played_dizhu
        ]

    # ── mutations ─────────────────────────────────────────────────────────

    def add_cards(self, cards: list[Card] | tuple[Card, ...]) -> None:
        """Add cards and re-sort."""
        self.cards.extend(cards)
        self.cards.sort(key=lambda c: c._sort_key())

    def remove_cards(self, cards: list[Card]) -> None:
        """Remove specific cards. Raises ValueError if any card not found."""
        remaining = list(self.cards)
        for c in cards:
            try:
                remaining.remove(c)
            except ValueError:
                raise ValueError(f"Card {c} not in hand")
        # Track played dizhu cards
        for c in cards:
            if id(c) in self._dizhu_card_ids:
                self._played_dizhu.add(id(c))
        self.cards = remaining

    def remove_by_ids(self, card_ids: list[int]) -> list[Card]:
        """Remove cards by their Python id(). Returns the removed cards."""
        removed = []
        for c in self.cards:
            if id(c) in card_ids:
                removed.append(c)
                if id(c) in self._dizhu_card_ids:
                    self._played_dizhu.add(id(c))
        if len(removed) != len(card_ids):
            raise ValueError("Some card ids not found in hand")
        self.cards = [c for c in self.cards if id(c) not in card_ids]
        return removed

    # ── queries ───────────────────────────────────────────────────────────

    def __len__(self) -> int:
        return len(self.cards)

    def __contains__(self, card: Card) -> bool:
        return card in self.cards

    def __iter__(self):
        return iter(self.cards)

    @property
    def size(self) -> int:
        return len(self.cards)

    def rank_counts(self) -> dict[Rank, int]:
        """Count cards by rank."""
        counts: Counter[Rank] = Counter()
        for c in self.cards:
            counts[c.rank] += 1
        return dict(counts)

    def cards_of_rank(self, rank: Rank) -> list[Card]:
        return [c for c in self.cards if c.rank == rank]

    def has_rank(self, rank: Rank) -> bool:
        return any(c.rank == rank for c in self.cards)

    def display_str(self) -> str:
        """Space-separated display string (rank desc, ♠→♥→♣→♦)."""
        return " ".join(str(c) for c in self.cards)

    def rank_only_str(self) -> str:
        """Space-separated rank-only string."""
        return " ".join(c.rank_only for c in self.cards)

    def __repr__(self) -> str:
        return f"Hand({self.display_str()})"

src/backend/arena/engine/pause.py:
"""Pause/resume manager with DB-backed state persistence.

Pause granularity: pauses take effect after the current play/bid completes.
State is serialized to a DB temporary table on pause and cleared on resume.
Hard crashes lose in-memory state (accepted limitation for Phase 1).
"""

from __future__ import annotations

import json
import threading
from dataclasses import asdict, dataclass, field
from enum import StrEnum
from typing import Any, Protocol


class PauseState(StrEnum):
    RUNNING = "running"
    PAUSE_REQUESTED = "pause_requested"
    PAUSED = "paused"


# ── persistence interface ────────────────────────────────────────────────────


class PauseStore(Protocol):
    """Protocol for persisting pause state. Implementations: InMemoryStore, SqliteStore."""

    def save(self, table: str, state_json: str) -> None: ...
    def load(self, table: str) -> str | None: ...
    def delete(self, table: str) -> None: ...


class InMemoryPauseStore:
    """In-memory store for testing / no-DB scenarios."""

    def __init__(self) -> None:
        self._store: dict[str, str] = {}

    def save(self, table: str, state_json: str) -> None:
        self._store[table] = state_json

    def load(self, table: str) -> str | None:
        return self._store.get(table)

    def delete(self, table: str) -> None:
        self._store.pop(table, None)


# ── manager ──────────────────────────────────────────────────────────────────


class PauseManager:
    """Per-table pause manager.

    Thread-safe for use by the game engine thread and the API thread.
    """

    def __init__(self, table: str, store: PauseStore | None = None) -> None:
        self.table = table
        self._store = store or InMemoryPauseStore()
        self._state = PauseState.RUNNING
        self._lock = threading.Lock()
        self._paused_at_hand: int = 0
        self._reason: str = ""

    # ── API ─────────────────────────────────────────────────────────────

    @property
    def state(self) -> PauseState:
        with self._lock:
            return self._state

    @property
    def is_paused(self) -> bool:
        return self.state == PauseState.PAUSED

    def request_pause(self, reason: str = "user_requested") -> None:
        """Signal that a pause is desired. Takes effect after current play/bid."""
        with self._lock:
            if self._state == PauseState.RUNNING:
                self._state = PauseState.PAUSE_REQUESTED
                self._reason = reason

    def check_pause(self) -> bool:
        """Called by game engine after each play/bid completes.
        Returns True if the engine should now pause.
        """
        with self._lock:
            if self._state == PauseState.PAUSE_REQUESTED:
                self._state = PauseState.PAUSED
                return True
            return False

    def resume(self) -> None:
        """Resume from pause. Clears persisted state."""
        with self._lock:
            self._state = PauseState.RUNNING
            self._reason = ""
            self._store.delete(self.table)

    # ── persistence ─────────────────────────────────────────────────────

    def persist_state(self, state_dict: dict[str, Any]) -> None:
        """Serialize and persist the current game state."""
        state_dict["_pause_reason"] = self._reason
        state_dict["_paused_at_hand"] = state_dict.get("hand_num", 0)
        self._store.save(self.table, json.dumps(state_dict, default=str))

    def load_state(self) -> dict[str, Any] | None:
        """Load persisted state. Returns None if no state exists."""
        raw = self._store.load(self.table)
        if raw is None:
            return None
        return json.loads(raw)

    @property
    def paused_at_hand(self) -> int:
        return self._paused_at_hand

    @property
    def reason(self) -> str:
        return self._reason

