"""Deterministic, model-independent legal trajectories for a held-out benchmark.

The sampling distribution is a rule-policy fixture, not human play or a model
ranking benchmark. No provider output is used to select an observation.
"""
from __future__ import annotations

from collections import Counter
from dataclasses import asdict
import json
import random

from ..agent.memory import MemoryManager
from ..agent.prompts.bidding import build_bidding_prompt
from ..agent.prompts.playing import build_playing_prompt
from ..engine.card import SEATS, Card
from ..engine.deck import Deck
from ..engine.projection import RULES_VERSION, digest, project
from ..engine.rules import InvalidPlayError, can_beat, recognize
from ..engine.state import GameEngine, TablePhase
from ..tournament.table import TableRunner
from .observations import validate_output

VERSION = "independent-rule-trajectories-v1"
TEAMS = {"S": "red", "N": "red", "E": "blue", "W": "blue"}
QUOTAS = {"bidding": 1, "lead": 3, "follow": 4}
OBSERVATION_FIELDS = {
    "seat", "role", "hand_cards", "hand_size", "dizhu_cards", "bidding_history", "play_history",
    "current_trick", "trick_leader", "landlord", "active_players", "player_hand_sizes",
    "current_high_bid", "current_high_bidder", "hand_score", "winner_team", "winner_role",
    "hand_num", "match_id", "initial_hand", "remaining_hands", "agent_role", "is_idle_observer",
    "match_summary",
}
POST_GAME_DEFAULTS = {
    "hand_score": None, "winner_team": "", "winner_role": "", "hand_num": 0, "match_id": "",
    "initial_hand": None, "remaining_hands": None, "agent_role": "", "is_idle_observer": False,
    "match_summary": None,
}


def _validate_seeds(development_seeds, test_seeds):
    if any(not isinstance(seeds, list) or not seeds or
           any(not isinstance(seed, str) or not seed for seed in seeds)
           for seeds in (development_seeds, test_seeds)):
        raise ValueError("nonempty development/test seed lists required")
    if set(development_seeds) & set(test_seeds):
        raise ValueError("source leakage: development/test seeds overlap")
    if len(set(development_seeds + test_seeds)) != len(development_seeds + test_seeds):
        raise ValueError("duplicate seed")


def _verify_observation(item):
    """Reject hidden/future fields even when callers skip expensive source replay.

    The v1 archive contains engine card identities for already played cards.
    These are replay evidence; providers receive only the frozen prompt strings.
    This check does not silently change that historical visibility convention.
    """
    obs = item["observation"]
    if set(obs) != OBSERVATION_FIELDS:
        raise ValueError("unexpected/missing observation fields")
    if any(obs[key] != default or type(obs[key]) is not type(default)
           for key, default in POST_GAME_DEFAULTS.items()):
        raise ValueError("private/post-game state in observation")
    if obs["seat"] not in SEATS or type(obs["hand_size"]) is not int:
        raise ValueError("invalid observation seat/hand size")
    cards = [Card.from_string(card) for card in obs["hand_cards"]]
    if len(cards) != obs["hand_size"] or not 1 <= len(cards) <= 20 or len(set(cards)) != len(cards):
        raise ValueError("invalid observation hand")
    phase, index = item["phase"], item["source_index"]
    if phase not in ("bidding", "playing") or type(index) is not int or index < 0:
        raise ValueError("invalid observation phase/source index")
    category = "bidding" if phase == "bidding" else ("lead" if obs["current_trick"] is None else "follow")
    if item["category"] != category:
        raise ValueError("category does not match observation")
    expected_id = digest({"seed": item["source_seed"], "phase": phase, "index": index})
    if item["observation_id"] != expected_id:
        raise ValueError("observation/source identity mismatch")
    if any(not isinstance(item[key], str) or not item[key] for key in ("system_prompt", "user_prompt")):
        raise ValueError("missing frozen prompt")
    bids, plays = obs["bidding_history"], obs["play_history"]
    if not isinstance(bids, list) or not isinstance(plays, list):
        raise ValueError("invalid public history")
    high_bid = 0
    for bid in bids:
        if set(bid) != {"seat", "bid"} or bid["seat"] not in SEATS or type(bid["bid"]) is not int:
            raise ValueError("unexpected/invalid bidding history fields")
        if bid["bid"] not in range(4) or (bid["bid"] and bid["bid"] <= high_bid):
            raise ValueError("invalid public bid history")
        high_bid = max(high_bid, bid["bid"])
    for seq, play in enumerate(plays, 1):
        if set(play) != {"round", "sub_round", "seq", "seat", "action_type", "cards", "trick_display"}:
            raise ValueError("unexpected/missing play history fields")
        if play["seq"] != seq or play["seat"] not in SEATS or play["action_type"] not in ("play", "pass"):
            raise ValueError("invalid public play history")
    if phase == "bidding":
        if (index != len(bids) or index >= 3 or plays or obs["dizhu_cards"] is not None
                or obs["current_trick"] is not None or obs["landlord"] or obs["role"] != "bidding"
                or obs["current_high_bid"] != high_bid):
            raise ValueError("future/invalid state in bidding observation")
    elif index != len(plays) or obs["role"] not in ("landlord", "farmer"):
        raise ValueError("future/invalid state in playing observation")
    pattern = obs["current_trick"]["pattern"] if obs["current_trick"] else None
    if item["target_pattern"] != pattern:
        raise ValueError("target pattern mismatch")


def candidates(cards, target=None):
    """A finite rule policy including compound plays; not a complete solver."""
    groups = {}
    for card in cards:
        groups.setdefault(card.rank.value, []).append(card)
    plays = [[c] for c in cards]
    for group in groups.values():
        plays.extend(group[:n] for n in (2, 3, 4) if len(group) >= n)
        if len(group) >= 3:
            for other in groups.values():
                if other[0].rank != group[0].rank:
                    plays.append(group[:3] + other[:1])
                    if len(other) >= 2:
                        plays.append(group[:3] + other[:2])
    for multiplicity, minimum in ((1, 5), (2, 3), (3, 2)):
        for start in range(3, 15):
            run = []
            for end in range(start, 15):
                if len(groups.get(end, [])) < multiplicity:
                    break
                run += groups[end][:multiplicity]
                if end - start + 1 >= minimum:
                    plays.append(list(run))
    jokers = [c for c in cards if c.rank.value >= 16]
    if len(jokers) == 2:
        plays.append(jokers)
    valid = {}
    for play in plays:
        try:
            trick = recognize(play)
        except InvalidPlayError:
            continue
        if target is None or can_beat(trick, target):
            key = tuple(sorted(str(c) for c in play))
            valid[key] = play
    return [valid[key] for key in sorted(valid)]


def snapshot(ctx, seed, phase, index):
    observation = json.loads(json.dumps(asdict(ctx), default=str, ensure_ascii=False))
    observation["hand_cards"] = [str(c) for c in ctx.hand_cards]
    memory = MemoryManager("benchmark-player")
    if phase == "bidding":
        system, user = build_bidding_prompt(ctx, memory, "benchmark-player")
    else:
        system, user = build_playing_prompt(ctx, memory, "benchmark-player", seat_teams=TEAMS)
    return {
        "observation_id": digest({"seed": seed, "phase": phase, "index": index}),
        "source_seed": seed, "source_match": f"rule-policy/{seed}",
        "source_index": index, "phase": phase,
        "category": "bidding" if phase == "bidding" else ("lead" if ctx.current_trick is None else "follow"),
        "observation": observation, "system_prompt": system, "user_prompt": user,
        "target_pattern": ctx.current_trick.pattern.value if ctx.current_trick else None,
    }


def trajectory(seed):
    """Use production context builders and engine; archive legal source actions."""
    rng = random.Random(f"{VERSION}/policy/{seed}")
    table = TableRunner("A", {}, TEAMS, enable_reflection=False)
    state = table._state
    state.seat_teams = dict(TEAMS)
    GameEngine.init_hand(state, hand_num=1, dealer="S", idle_seat="W", deal_result=Deck(seed).deal())
    GameEngine.start_bidding(state)
    observations, actions = [], []
    while not state.landlord:
        seat = state.bidding_order[state.current_bidder_idx]
        ctx = table._build_bidding_context(seat)
        observations.append(snapshot(ctx, seed, "bidding", len(state.bidding_history)))
        options = [n for n in (0, 1, 2) if n == 0 or n > state.current_high_bid]
        # Guarantee a playing trajectory, independent of model outcomes.
        if state.current_bidder_idx == 2 and state.current_high_bid == 0:
            options = [1, 2, 3]
        bid = rng.choice(options)
        GameEngine.submit_bid(state, seat, bid, 0)
        actions.append({"phase": "bidding", "seat": seat, "bid": bid})
    GameEngine.finalize_bidding(state)
    GameEngine.start_playing(state)
    while state.phase == TablePhase.PLAYING:
        if state.global_seq >= 1000:
            raise ValueError("rule trajectory exceeded its action bound")
        seat = state.current_player
        ctx = table._build_play_context(seat)
        observations.append(snapshot(ctx, seed, "playing", state.global_seq))
        choices = candidates(ctx.hand_cards, ctx.current_trick)
        if ctx.current_trick is not None:
            choices.append([])
        play = rng.choice(choices)
        raw = json.dumps({"action": {"type": "play", "cards": [str(c) for c in play]}} if play
                         else {"action": {"type": "pass"}})
        validate_output(observations[-1], raw)
        GameEngine.submit_play(state, seat, play, 0)
        actions.append({"phase": "playing", "seat": seat, "cards": [str(c) for c in play]})
    return observations, {"source_seed": seed, "actions": actions, "terminal_state_sha256": digest(project(state))}


def build_corpus(development_seeds, test_seeds):
    _validate_seeds(development_seeds, test_seeds)
    items, sources = [], []
    for split, seeds in (("development", development_seeds), ("test", test_seeds)):
        for seed in seeds:
            pool, source = trajectory(seed)
            source["split"] = split
            sources.append(source)
            rng = random.Random(f"{VERSION}/sample/{seed}")
            for category, count in QUOTAS.items():
                eligible = [item for item in pool if item["category"] == category]
                if len(eligible) < count:
                    raise ValueError(f"{seed}: insufficient {category} states; do not silently replace a seed")
                # One sample per temporal bin: cover early through late play.
                for index in range(count):
                    lo, hi = index * len(eligible) // count, (index + 1) * len(eligible) // count
                    item = dict(rng.choice(eligible[lo:hi]))
                    item["split"] = split
                    item["temporal_bin"] = index
                    items.append(item)
    corpus = {
        "version": VERSION, "rules_version": RULES_VERSION,
        "provenance": "deterministic legal rule-policy trajectories; no LLM sampling or error injection",
        "sampling": {"quotas_per_seed": QUOTAS, "method": "uniform within temporal bins per category",
                     "policy": "seeded uniform legal candidate, forced nonvoid bidding; finite compound-play candidates"},
        "development_seeds": development_seeds, "test_seeds": test_seeds,
        "observations": items, "sources": sources,
    }
    corpus["sha256"] = digest(corpus)
    return corpus


def verify_corpus(corpus, *, replay=True):
    """Check membership/visibility before optional deterministic source replay."""
    try:
        return _verify_corpus(corpus, replay=replay)
    except (KeyError, TypeError, AttributeError, IndexError) as exc:
        raise ValueError(f"malformed fixed corpus: {exc}") from exc


def _verify_corpus(corpus, *, replay):
    if corpus.get("sha256") != digest({k: v for k, v in corpus.items() if k != "sha256"}):
        raise ValueError("corpus hash mismatch")
    if corpus.get("version") != VERSION or corpus.get("rules_version") != RULES_VERSION:
        raise ValueError("unsupported corpus/rules version")
    ids = [item["observation_id"] for item in corpus["observations"]]
    if len(ids) != len(set(ids)):
        raise ValueError("duplicate observation")
    dev, test = corpus["development_seeds"], corpus["test_seeds"]
    _validate_seeds(dev, test)
    expected_splits = {seed: split for split, seeds in (("development", dev), ("test", test)) for seed in seeds}
    if Counter(source["source_seed"] for source in corpus["sources"]) != Counter(expected_splits.keys()):
        raise ValueError("source trajectory coverage mismatch")
    for source in corpus["sources"]:
        if source["split"] != expected_splits[source["source_seed"]]:
            raise ValueError("source trajectory split mismatch")
    for item in corpus["observations"]:
        seed = item["source_seed"]
        if seed not in expected_splits or item["split"] != expected_splits[seed]:
            raise ValueError("unexpected source/split in observation")
        if item["source_match"] != f"rule-policy/{seed}":
            raise ValueError("source match identity/leakage mismatch")
        _verify_observation(item)
    for seed in dev + test:
        items = [item for item in corpus["observations"] if item["source_seed"] == seed]
        if Counter(item["category"] for item in items) != Counter(QUOTAS):
            raise ValueError("category quota mismatch")
        expected = "development" if seed in dev else "test"
        if any(item["split"] != expected for item in items):
            raise ValueError("source split mismatch")
        for category, count in QUOTAS.items():
            bins = [item["temporal_bin"] for item in items if item["category"] == category]
            if any(type(index) is not int for index in bins) or sorted(bins) != list(range(count)):
                raise ValueError("temporal bin coverage mismatch")
    if replay:
        rebuilt = build_corpus(dev, test)
        if rebuilt != corpus:
            raise ValueError("source replay or frozen prompt mismatch")
    return {"complete": True, "sources": len(dev) + len(test), "observations": len(ids),
            "test_observations": sum(item["split"] == "test" for item in corpus["observations"])}

src/backend/arena/evaluation/fixed_study:
"""Budgeted shared-first-response experiment with durable physical call evidence.

The baseline response is paid for once, then referenced by all three protocols.
Only failed first responses branch. This estimates feedback's incremental value
for this frozen observation/first-response sample, not self-play strength.
"""
from __future__ import annotations

import asyncio
from dataclasses import asdict
import json
import random
import time
from pathlib import Path
from typing import Literal

from pydantic import BaseModel, ConfigDict, Field

from ..agent.llm_agent import LLMAgent
from ..agent.parser import ParseError
from ..llm.logging import LoggingLLMProvider
from ..llm.openai import OpenAIProvider
from ..llm.claude import ClaudeProvider
from .budget import BudgetExceeded, BudgetLedger
from .execution import ExecutionScope
from .fixed_corpus import verify_corpus
from .observations import validate_output
from .spec import PreflightError, canonical_hash, validate_execution

ARMS = ("generic_retry", "rule_feedback")
GENERIC = "\n\n请重新独立生成一个完整 JSON 回复。"
DDL = """
CREATE TABLE IF NOT EXISTS fixed_items (
 run_id TEXT NOT NULL REFERENCES evaluation_runs(id), observation_id TEXT NOT NULL,
 status TEXT NOT NULL, outcome_json TEXT, PRIMARY KEY(run_id, observation_id)
);
CREATE TABLE IF NOT EXISTS fixed_calls (
 call_id TEXT PRIMARY KEY REFERENCES llm_call_logs(id), run_id TEXT NOT NULL,
 observation_id TEXT NOT NULL, arm TEXT NOT NULL, attempt INTEGER NOT NULL,
 validation_json TEXT NOT NULL, UNIQUE(run_id, observation_id, arm, attempt)
);
"""


class FixedProtocol(BaseModel):
    model_config = ConfigDict(extra="forbid")
    version: Literal["shared-first-response-v1"] = "shared-first-response-v1"
    split: str = Field(default="test", pattern="^(development|test)$")
    concurrency: int = Field(default=2, ge=1, le=4)
    call_timeout_seconds: float = Field(default=300, gt=0, le=600)
    decision_timeout_seconds: float = Field(default=600, gt=0, le=1800)
    cancellation_deadline_seconds: float = Field(default=5, gt=0, le=30)
    retry_limit: int = Field(default=2, ge=1, le=2)
    schedule_seed: str = "fixed-feedback-order-20260926-v1"
    bootstrap_seed: str = "fixed-feedback-bootstrap-20260926-v1"
    bootstrap_resamples: int = Field(default=20000, ge=1000, le=100000)
    primary_phase: Literal["playing"] = "playing"
    primary_contrast: Literal["rule_feedback_minus_generic_retry"] = "rule_feedback_minus_generic_retry"
    first_response: str = "one physical response shared across all protocols"
    provider_errors: str = "same generic retry in both branches"
    latency_estimand: str = "sum of own provider call durations, including shared first; excludes queue and branch scheduling"
    model_version_policy: str = "freeze requested model; record all returned names/fingerprints; mixed names limit version-specific conclusions"


class FixedStudyBudget(BudgetLedger):
    """Enforce the frozen token limits even when token prices are zero."""

    def settle(self, reservation, call_id, usage):
        # Preserve the response and its actual cost before stopping the run.
        super().settle(reservation, call_id, usage)
        if usage is not None and any(
            count is not None and not 0 <= count <= limit
            for count, limit in (
                (usage.prompt_tokens, self.input_limit),
                (usage.completion_tokens, self.output_limit),
            )
        ):
            self.stopped = True
            raise BudgetExceeded("fixed-study provider usage exceeds declared token allowance")


def assess(item, call):
    if call["provider_status"] != "returned":
        return {"valid": False, "action": None, "error_kind": "provider_error",
                "error": call["error_message"] or "provider did not return a response"}
    try:
        action = validate_output(item, call["raw_output"] or "")
        return {"valid": True, "action": action, "error_kind": None, "error": None}
    except ParseError as exc:
        return {"valid": False, "action": None, "error_kind": "invalid_output", "error": str(exc)}


def retry_prompt(user, validation, arm, attempt):
    if arm == "rule_feedback" and validation["error_kind"] == "invalid_output":
        return LLMAgent._append_retry_feedback(user, validation["error"], attempt)
    return user + GENERIC


def order_for(protocol, observation_id, round_index):
    arms = list(ARMS)
    random.Random(f"{protocol.schedule_seed}/{observation_id}/{round_index}").shuffle(arms)
    return arms


def read_call(repo, call_id):
    row = repo.conn.execute("""SELECT l.*,e.system_prompt,e.user_prompt,e.raw_output,e.provider_status
        FROM llm_call_logs l JOIN call_evidence e ON e.call_id=l.id WHERE l.id=?""", (call_id,)).fetchone()
    if row is None:
        raise ValueError("physical call evidence missing")
    return dict(row)


def make_manifest(spec, run_manifest, corpus, protocol):
    if protocol.version != "shared-first-response-v1" or protocol.primary_phase != "playing" or protocol.primary_contrast != "rule_feedback_minus_generic_retry":
        raise ValueError("unsupported fixed protocol")
    selected = [item for item in corpus["observations"] if item["split"] == protocol.split]
    seeds = corpus[f"{protocol.split}_seeds"]
    if list(run_manifest.seeds) != seeds:
        raise ValueError("manifest seeds must exactly match the selected corpus split")
    expected = {"single_generation": (0, False), "generic_retry": (protocol.retry_limit, False),
                "rule_feedback": (protocol.retry_limit, True)}
    actual = {v.variant_id: (v.retry_limit, v.rule_feedback) for v in spec.variants}
    if actual != expected:
        raise ValueError("protocol retry controls differ from frozen experiment")
    if run_manifest.models[0].system_prompt:
        raise ValueError("fixed corpus owns prompts; use an explicit empty system_prompt override")
    bound = len(selected) * (1 + 2 * protocol.retry_limit)
    if spec.max_calls != bound:
        raise ValueError(f"max_calls must equal the predeclared physical bound {bound}")
    if spec.cancellation_deadline_seconds != protocol.cancellation_deadline_seconds:
        raise ValueError("cancellation controls disagree")
    manifest = {"kind": "fixed-observation-effect-study", "run_manifest": asdict(run_manifest),
                "protocol": protocol.model_dump(mode="json"), "corpus_sha256": corpus["sha256"],
                "observation_ids": [item["observation_id"] for item in selected], "physical_call_bound": bound}
    manifest["sha256"] = canonical_hash(manifest)
    return manifest


class FixedStudyRunner:
    def __init__(self, repo, root, spec, run_manifest, corpus, protocol, *, provider_factory=None):
        self.repo, self.root, self.spec = repo, Path(root), spec
        self.base_manifest, self.corpus, self.protocol = run_manifest, corpus, protocol
        self.manifest = make_manifest(spec, run_manifest, corpus, protocol)
        self.provider_factory = provider_factory
        self.cancelled = False
        self.tasks = set()
        self.detached = set()
        self.run_id = None

    def cancel(self):
        self.cancelled = True
        for task in list(self.tasks):
            task.cancel()

    def _consume(self, task):
        self.detached.discard(task)
        if not task.cancelled():
            task.exception()

    async def _stop_call(self, worker, scope):
        scope.cancel_requested = True
        worker.cancel()
        done, _ = await asyncio.wait({worker}, timeout=self.protocol.cancellation_deadline_seconds)
        scope.revoke()
        if done:
            await asyncio.gather(worker, return_exceptions=True)
        else:
            self.detached.add(worker)
            worker.add_done_callback(self._consume)

    def _provider(self):
        if self.provider_factory:
            return self.provider_factory()
        model = self.base_manifest.models[0]
        credential = self.repo.get_player_config_by_name(model.config_name)["api_key"]
        kwargs = {k: v for k, v in model.parameters.items() if v is not None}
        if model.provider == "claude":
            kwargs.pop("seed", None)
        return (ClaudeProvider if model.provider == "claude" else OpenAIProvider)(
            model=model.model, api_key=credential, base_url=model.base_url, **kwargs)

    async def _call(self, item, arm, attempt, user, remaining):
        scope = ExecutionScope()
        inner = self._provider()
        provider = LoggingLLMProvider(inner, repo=scope.guard(self.repo), agent_id=self.player_id,
                                      budget=scope.guard(self.budget), execution_scope=scope)
        provider.set_context(run_id=self.run_id, variant_id=arm, decision_id=item["observation_id"],
                             attempt=attempt, phase=item["phase"])
        worker = asyncio.create_task(provider.generate(user, item["system_prompt"]))
        try:
            try:
                done, _ = await asyncio.wait({worker}, timeout=min(remaining, self.protocol.call_timeout_seconds))
            except asyncio.CancelledError:
                await self._stop_call(worker, scope)
                raise
            if not done:
                await self._stop_call(worker, scope)
            else:
                from ..llm.base import LLMError
                try:
                    await worker
                except LLMError:
                    pass  # Recorded provider failure participates in both protocols.
            row = self.repo.conn.execute("""SELECT id FROM llm_call_logs
                WHERE run_id=? AND decision_id=? AND variant_id=? AND attempt=?""",
                (self.run_id, item["observation_id"], arm, attempt)).fetchone()
            if row is None:
                raise RuntimeError("call did not produce durable evidence")
            call = read_call(self.repo, row[0])
            validation = assess(item, call)
            self.repo.conn.execute("INSERT INTO fixed_calls VALUES(?,?,?,?,?,?)", (
                call["id"], self.run_id, item["observation_id"], arm, attempt, json.dumps(validation, ensure_ascii=False)))
            self.repo.conn.commit()
            return {"call_id": call["id"], "validation": validation, "latency_ms": call["latency_ms"]}
        finally:
            if worker.done():
                client = getattr(inner, "_client", None)
                if client is not None:
                    try:
                        await asyncio.wait_for(client.close(), 5)
                    except (Exception, asyncio.CancelledError):
                        pass

    async def _observation(self, item, semaphore):
        oid = item["observation_id"]
        try:
            async with semaphore:
                if self.cancelled:
                    raise asyncio.CancelledError
                self.repo.conn.execute("UPDATE fixed_items SET status='running' WHERE run_id=? AND observation_id=?", (self.run_id, oid))
                self.repo.conn.commit()
                first = await self._call(item, "shared_first", 1, item["user_prompt"], self.protocol.decision_timeout_seconds)
                chains = {arm: [first] for arm in ARMS}
                prompts = {arm: item["user_prompt"] for arm in ARMS}
                schedule = []
                for retry_index in range(1, self.protocol.retry_limit + 1):
                    for arm in order_for(self.protocol, oid, retry_index):
                        chain = chains[arm]
                        remaining = self.protocol.decision_timeout_seconds - sum(c["latency_ms"] for c in chain) / 1000
                        if chain[-1]["validation"]["valid"] or remaining <= 0:
                            continue
                        prompts[arm] = retry_prompt(prompts[arm], chain[-1]["validation"], arm, retry_index)
                        call = await self._call(item, arm, retry_index + 1, prompts[arm], remaining)
                        chain.append(call)
                        schedule.append({"arm": arm, "attempt": retry_index + 1, "call_id": call["call_id"]})
                outcome = {"first_call_id": first["call_id"], "schedule": schedule, "branches": {}}
                for arm, chain in chains.items():
                    outcome["branches"][arm] = {
                        "call_ids": [c["call_id"] for c in chain], "success": chain[-1]["validation"]["valid"],
                        "action": chain[-1]["validation"]["action"],
                        "stop_reason": "valid" if chain[-1]["validation"]["valid"] else (
                            "exhausted" if len(chain) == 1 + self.protocol.retry_limit else "deadline"),
                    }
                self.repo.conn.execute("UPDATE fixed_items SET status='finished',outcome_json=? WHERE run_id=? AND observation_id=?",
                                       (json.dumps(outcome, ensure_ascii=False), self.run_id, oid))
                self.repo.conn.commit()
        except asyncio.CancelledError:
            self.repo.conn.execute("UPDATE fixed_items SET status='cancelled' WHERE run_id=? AND observation_id=?", (self.run_id, oid))
            self.repo.conn.commit()
        except Exception as exc:
            self.repo.conn.execute("UPDATE fixed_items SET status='failed',outcome_json=? WHERE run_id=? AND observation_id=?",
                                   (json.dumps({"error": f"{type(exc).__name__}: {exc}"}), self.run_id, oid))
            self.repo.conn.commit()
            # An infrastructure/budget/evidence fault invalidates the batch.
            self.cancelled = True
            for task in list(self.tasks):
                if task is not asyncio.current_task():
                    task.cancel()

    async def run(self, *, real_models=False, mock=False):
        if real_models == mock:
            raise ValueError("select exactly one explicit real/mock execution mode")
        if real_models and self.provider_factory is not None:
            raise PreflightError("real fixed studies cannot use an injected provider_factory")
        validate_execution(self.spec, self.base_manifest, self.root, self.repo, mock=mock)
        verify_corpus(self.corpus)
        if self.manifest != make_manifest(self.spec, self.base_manifest, self.corpus, self.protocol):
            raise ValueError("fixed manifest changed before execution")
        self.repo.conn.executescript(DDL)
        eid = self.repo.create_experiment(self.spec.experiment_id, self.spec.model_dump(mode="json"), self.base_manifest.spec_sha256)
        self.run_id = self.repo.create_evaluation_run(eid, self.manifest, self.manifest["sha256"])
        model = self.base_manifest.models[0]
        self.repo.add_model_snapshot(self.run_id, asdict(model))
        config = self.repo.get_player_config_by_name(model.config_name)
        if config is None and mock:
            cid = self.repo.create_player_config(model.config_name, "mock", model.model, "")
        else:
            cid = config["id"]
        self.player_id = self.repo.create_player(cid, "fixed-observation benchmark")
        self.budget = FixedStudyBudget(self.repo, self.run_id, self.spec.budget_limit_usd, self.spec.max_calls,
                                      self.spec.max_input_tokens, model.parameters["max_tokens"], model.pricing)
        items = [item for item in self.corpus["observations"] if item["split"] == self.protocol.split]
        self.repo.conn.executemany("INSERT INTO fixed_items VALUES(?,?,'planned',NULL)",
                                  [(self.run_id, item["observation_id"]) for item in items])
        self.repo.conn.commit()
        self.repo.update_evaluation_run_status(self.run_id, "running")
        # Mix seeds/categories across time while keeping the ordering reproducible.
        random.Random(self.protocol.schedule_seed).shuffle(items)
        semaphore = asyncio.Semaphore(self.protocol.concurrency)
        self.tasks = {asyncio.create_task(self._observation(item, semaphore)) for item in items}
        try:
            await asyncio.gather(*self.tasks)
        except asyncio.CancelledError:
            self.cancel()
            await asyncio.gather(*self.tasks, return_exceptions=True)
        finally:
            self.repo.conn.execute("UPDATE fixed_items SET status='cancelled' WHERE run_id=? AND status IN ('planned','running')", (self.run_id,))
            self.repo.conn.commit()
            states = [r[0] for r in self.repo.conn.execute("SELECT status FROM fixed_items WHERE run_id=?", (self.run_id,))]
            status = "failed" if "failed" in states else ("cancelled" if self.cancelled else "finished")
            self.repo.update_evaluation_run_status(self.run_id, status)
        return self.run_id

src/backend/arena/evaluation/memory_stud:
"""Independent, read-only memory ablation on frozen visible observations.

This protocol measures output legality and cost, never playing strength. It does
not change the first-round reliability protocol or the historical fixed study.
"""
from __future__ import annotations

import asyncio
import hashlib
import importlib.metadata
import json
import random
from decimal import Decimal
from pathlib import Path
from typing import Literal
from urllib.parse import urlsplit

from pydantic import BaseModel, ConfigDict, Field

from ..agent.parser import ParseError
from ..llm.base import AbstractLLMProvider, LLMError, LLMUsage
from ..llm.logging import LoggingLLMProvider
from ..security.credentials import has_usable_credential
from .budget import BudgetExceeded, BudgetLedger
from .execution import ExecutionScope
from .fixed_corpus import verify_corpus
from .observations import validate_output
from .spec import ModelSpec, canonical_hash

ARMS = ("no_memory", "fixed_initial", "frozen_memory")
RETRY = "\n\n请重新独立生成一个完整 JSON 回复。"
DDL = """CREATE TABLE IF NOT EXISTS memory_study_decisions (
 run_id TEXT NOT NULL REFERENCES evaluation_runs(id), observation_id TEXT NOT NULL,
 arm TEXT NOT NULL, status TEXT NOT NULL, outcome_json TEXT,
 PRIMARY KEY(run_id, observation_id, arm));"""


class MemoryProtocol(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)
    version: Literal["memory-fixed-observations-v1"] = "memory-fixed-observations-v1"
    memory_slot: str = "player-0"
    retry_limit: int = Field(default=1, ge=0, le=2)
    max_input_tokens: int = Field(default=32768, gt=1024)
    budget_limit_usd: float = Field(default=1, ge=0)
    call_timeout_seconds: float = Field(default=60, gt=0, le=600)
    cancellation_deadline_seconds: float = Field(default=1, gt=0, le=30)
    schedule_seed: str = "memory-study-order-v1"


def implementation_snapshot(root):
    root = Path(root)
    paths = sorted((root / "src/backend/arena").rglob("*.py"))
    paths += [root / "scripts/memory_effect_study.py"]
    hashes = {str(p.relative_to(root)): hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}
    dependencies = {}
    for relative in ("pyproject.toml", "src/backend/pyproject.toml", "src/backend/requirements.txt"):
        path = root / relative
        if path.exists():
            dependencies[relative] = hashlib.sha256(path.read_bytes()).hexdigest()
    versions = {}
    for package in ("openai", "anthropic", "pydantic"):
        try:
            versions[package] = importlib.metadata.version(package)
        except importlib.metadata.PackageNotFoundError:
            versions[package] = "unavailable"
    return {"source_files": hashes, "source_sha256": canonical_hash(hashes),
            "dependencies": dependencies, "sdk_versions": versions}


def validate_artifact(artifact, corpus, model, slot, *, mock):
    if not isinstance(artifact, dict) or artifact.get("schema_version") != 1:
        raise ValueError("unsupported frozen memory artifact schema")
    if artifact.get("artifact_sha256") != canonical_hash({
        k: v for k, v in artifact.items() if k != "artifact_sha256"
    }):
        raise ValueError("frozen memory artifact hash mismatch")
    seeds = artifact.get("training_seeds")
    if (not isinstance(seeds, list) or not seeds
            or not all(isinstance(s, str) and s for s in seeds)
            or len(seeds) != len(set(seeds))):
        raise ValueError("artifact requires nonempty unique training seeds")
    if set(seeds) & set(corpus["test_seeds"]):
        raise ValueError("training and test seeds overlap")
    seed_hash = canonical_hash({"seed_set_id": artifact.get("training_seed_set_id"), "seeds": seeds})
    if seed_hash != artifact.get("training_seed_set_sha256"):
        raise ValueError("training seed set hash mismatch")
    memories = artifact.get("memories")
    if not isinstance(memories, dict) or not all(isinstance(k, str) and isinstance(v, str) for k, v in memories.items()):
        raise ValueError("artifact memories must be a string-to-string object")
    memory = memories.get(slot)
    if not isinstance(memory, str) or not memory.strip():
        raise ValueError("selected memory slot must contain nonempty frozen text")
    training_model = artifact.get("model_snapshot", {})
    if not isinstance(training_model, dict):
        raise ValueError("artifact requires a training model snapshot")
    for key in ("provider", "model", "parameters", "base_url"):
        if training_model.get(key) != model[key]:
            raise ValueError(f"training/evaluation model mismatch: {key}")
    if artifact.get("provenance") != ("mock" if mock else "real"):
        raise ValueError("artifact requires explicit matching real/mock provenance")
    for key in ("memory_artifact_id", "training_run_id", "training_seed_set_id", "source_revision"):
        if not isinstance(artifact.get(key), str) or not artifact[key]:
            raise ValueError(f"artifact requires training provenance: {key}")
    for key in ("training_plan_sha256", "source_sha256", "dependency_sha256"):
        value = artifact.get(key)
        if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
            raise ValueError(f"artifact requires training fingerprint: {key}")
    if not mock:
        if (type(artifact.get("training_total_hands")) is not int or artifact["training_total_hands"] <= 0
                or set(memories) != {f"player-{i}" for i in range(8)}):
            raise ValueError("real artifact requires training hand count and all eight player slots")
        runtime = artifact.get("runtime_model_config", {})
        if not isinstance(runtime, dict) or any(runtime.get(k) != training_model.get(k)
                                              for k in ("provider", "model", "base_url")):
            raise ValueError("real artifact runtime model provenance mismatch")
        expected_prompt = hashlib.sha256((training_model.get("system_prompt") or "").encode()).hexdigest()
        if runtime.get("system_prompt_sha256") != expected_prompt:
            raise ValueError("real artifact training prompt provenance mismatch")
    return memory


def prompts(plan, item, arm, attempt=1):
    text = {"no_memory": "", "fixed_initial": plan["initial_strategy"],
            "frozen_memory": plan["memory_artifact"]["memories"][plan["protocol"]["memory_slot"]]}[arm]
    system = item["system_prompt"]
    if text:
        system += "\n\n## 固定策略经验（本次评测只读）\n" + text
    return system, item["user_prompt"] + RETRY * (attempt - 1)


def make_plan(root, corpus, artifact, initial_strategy, model, protocol, *, mock):
    verify_corpus(corpus)
    model = ModelSpec.model_validate(model).model_dump(mode="json")
    protocol = MemoryProtocol.model_validate(protocol).model_dump(mode="json")
    if model["provider"] not in (("mock",) if mock else ("openai", "claude")):
        raise ValueError("model provider disagrees with execution mode")
    if not model["model"].strip() or (not mock and model["model"].lower() in {"mock", "random"}):
        raise ValueError("explicit model name required")
    if model["system_prompt"] not in (None, ""):
        raise ValueError("corpus owns the shared system prompt; put the control in initial_strategy")
    if not initial_strategy.strip():
        raise ValueError("fixed initial strategy is required")
    if model["provider"] == "claude" and model["parameters"]["seed"] is not None:
        raise ValueError("Claude does not accept a sampling seed")
    endpoint = model["base_url"]
    if not endpoint:
        raise ValueError("explicit base_url required")
    url = urlsplit(endpoint)
    if url.username or url.password or url.query or url.fragment:
        raise ValueError("base_url must not contain credentials, query or fragment")
    if not mock and (url.scheme not in ("https", "http") or not url.hostname):
        raise ValueError("real base_url must be an HTTP(S) endpoint")
    pricing = model["pricing"]
    if (not pricing or pricing["currency"] != "USD"
            or not pricing["source"].strip() or not pricing["effective_date"].strip()):
        raise ValueError("explicit USD pricing, source and effective date required")
    validate_artifact(artifact, corpus, model, protocol["memory_slot"], mock=mock)
    selected = [i for i in corpus["observations"] if i["split"] == "test"]
    max_calls = len(selected) * len(ARMS) * (protocol["retry_limit"] + 1)
    reserve = (Decimal(protocol["max_input_tokens"]) * Decimal(str(pricing["input_per_million"]))
               + Decimal(model["parameters"]["max_tokens"]) * Decimal(str(pricing["output_per_million"]))) / 1_000_000
    if reserve * max_calls > Decimal(str(protocol["budget_limit_usd"])):
        raise ValueError("budget must cover the predeclared worst-case call reservations")
    plan = {"kind": "memory-fixed-observations", "mock": mock, "model": model,
            "protocol": protocol, "corpus": corpus, "memory_artifact": artifact,
            "initial_strategy": initial_strategy, "initial_strategy_sha256": canonical_hash(initial_strategy),
            "max_calls": max_calls, "maximum_reserved_usd": str(reserve * max_calls),
            "implementation": implementation_snapshot(root)}
    prompt_hashes = {}
    for item in selected:
        for arm in ARMS:
            system, user = prompts(plan, item, arm, protocol["retry_limit"] + 1)
            if len((system + user).encode()) + 1024 > protocol["max_input_tokens"]:
                raise ValueError("frozen prompts exceed input allowance, including retries")
            prompt_hashes[f"{item['observation_id']}/{arm}"] = canonical_hash(prompts(plan, item, arm))
    plan["prompt_sha256"] = canonical_hash(prompt_hashes)
    plan["sha256"] = canonical_hash(plan)
    return plan


def verify_plan(plan, root=None):
    if plan.get("sha256") != canonical_hash({k: v for k, v in plan.items() if k != "sha256"}):
        raise ValueError("plan hash mismatch")
    verify_corpus(plan["corpus"])
    MemoryProtocol.model_validate(plan["protocol"])
    ModelSpec.model_validate(plan["model"])
    validate_artifact(plan["memory_artifact"], plan["corpus"], plan["model"],
                      plan["protocol"]["memory_slot"], mock=plan["mock"])
    if root is not None:
        rebuilt = make_plan(root, plan["corpus"], plan["memory_artifact"], plan["initial_strategy"],
                            plan["model"], plan["protocol"], mock=plan["mock"])
        if rebuilt != plan:
            raise ValueError("source/dependencies or frozen controls changed; prepare a new plan")


def arm_order(plan, observation_id):
    arms = list(ARMS)
    random.Random(f"{plan['protocol']['schedule_seed']}/{observation_id}").shuffle(arms)
    return arms


def assess(item, call):
    if call["provider_status"] != "returned":
        return {"valid": False, "action": None, "error_kind": "provider_error"}
    try:
        return {"valid": True, "action": validate_output(item, call["raw_output"] or ""), "error_kind": None}
    except ParseError:
        return {"valid": False, "action": None, "error_kind": "invalid_output"}


def read_calls(repo, run_id):
    return [dict(row) for row in repo.conn.execute("""SELECT l.*, e.system_prompt,
        e.user_prompt,e.raw_output,e.provider_status FROM llm_call_logs l
        JOIN call_evidence e ON e.call_id=l.id WHERE l.run_id=? ORDER BY l.rowid""", (run_id,))]


class MemoryStudyMockProvider(AbstractLLMProvider):
    """Memory-blind fixture: equal synthetic behavior in all arms, no gain claim."""
    provider_name = "mock"
    model = "memory-study-mock"
    last_response_model = "memory-study-mock"
    last_system_fingerprint = None
    last_usage = LLMUsage(20, 10, 30)

    async def generate(self, user_prompt, system_prompt=""):
        import re
        if "叫分规则" in system_prompt:
            return '{"bid":0}'
        if RETRY not in user_prompt:
            return '{"action":{"type":"play","cards":["不存在的牌"]}}'
        if "新一轮，自由出牌" not in user_prompt:
            return '{"action":{"type":"pass"}}'
        hand = re.search(r"你的手牌（\d+张）：\n([^\n]+)", user_prompt).group(1).split()
        return json.dumps({"action": {"type": "play", "cards": hand[:1]}}, ensure_ascii=False)


class MemoryStudyRunner:
    def __init__(self, repo, root, plan, *, provider_factory=None):
        self.repo, self.root, self.plan = repo, Path(root), plan
        self.provider_factory = provider_factory
        self.run_id = None
        self.detached = set()

    def _provider(self, credential):
        if self.plan["mock"]:
            return (self.provider_factory or MemoryStudyMockProvider)()
        from ..llm.claude import ClaudeProvider
        from ..llm.openai import OpenAIProvider
        model = self.plan["model"]
        kwargs = {k: v for k, v in model["parameters"].items() if v is not None}
        if model["provider"] == "claude":
            kwargs.pop("seed", None)
        return (ClaudeProvider if model["provider"] == "claude" else OpenAIProvider)(
            model=model["model"], base_url=model["base_url"], api_key=credential, **kwargs)

    async def _call(self, item, arm, attempt, credential):
        scope, inner = ExecutionScope(), self._provider(credential)
        provider = LoggingLLMProvider(inner, repo=scope.guard(self.repo), agent_id=self.player_id,
                                      budget=scope.guard(self.budget), execution_scope=scope)
        provider.set_context(run_id=self.run_id, variant_id=arm, decision_id=item["observation_id"],
                             attempt=attempt, phase=item["phase"])
        system, user = prompts(self.plan, item, arm, attempt)
        worker = asyncio.create_task(provider.generate(user, system))
        async def stop():
            scope.cancel_requested = True
            worker.cancel()
            done, _ = await asyncio.wait({worker}, timeout=self.plan["protocol"]["cancellation_deadline_seconds"])
            scope.revoke()
            if done:
                await asyncio.gather(worker, return_exceptions=True)
            else:
                self.detached.add(worker)
                def consume(task):
                    self.detached.discard(task)
                    if not task.cancelled():
                        task.exception()
                worker.add_done_callback(consume)
        try:
            try:
                done, _ = await asyncio.wait({worker}, timeout=self.plan["protocol"]["call_timeout_seconds"])
                if not done:
                    await stop()
                else:
                    try:
                        await worker
                    except LLMError:
                        pass  # Provider failures are measured; budget/evidence failures stop the run.
            except asyncio.CancelledError:
                await stop()
                raise
            calls = [c for c in read_calls(self.repo, self.run_id)
                     if c["decision_id"] == item["observation_id"] and c["variant_id"] == arm and c["attempt"] == attempt]
            if len(calls) != 1:
                raise RuntimeError("physical call evidence missing or duplicated")
            call = calls[0]
            for field, limit in (("prompt_tokens", self.plan["protocol"]["max_input_tokens"]),
                                 ("completion_tokens", self.plan["model"]["parameters"]["max_tokens"])):
                if call[field] is not None and not 0 <= call[field] <= limit:
                    raise BudgetExceeded(f"provider {field} exceeds declared allowance")
            return call
        finally:
            if worker.done():
                client = getattr(inner, "_client", None)
                if client is not None:
                    try:
                        await asyncio.wait_for(client.close(), 5)
                    except (Exception, asyncio.CancelledError):
                        pass

    async def run(self, *, mock=False, real_models=False, credential=""):
        if mock == real_models or mock != self.plan["mock"]:
            raise ValueError("explicit matching --mock or --real-models mode required")
        verify_plan(self.plan, self.root)
        if real_models and (self.provider_factory or not has_usable_credential(credential)):
            raise ValueError("real evaluation requires a usable credential and production provider")
        plan, repo = self.plan, self.repo
        repo.conn.executescript(DDL)
        experiment = repo.create_experiment("memory-effects-v1", plan, plan["sha256"])
        self.run_id = repo.create_evaluation_run(experiment, plan, plan["sha256"])
        model, protocol = plan["model"], plan["protocol"]
        config = repo.create_player_config(f"memory-study-{self.run_id}", model["provider"], model["model"], "")
        self.player_id = repo.create_player(config, "Frozen memory benchmark")
        self.budget = BudgetLedger(repo, self.run_id, protocol["budget_limit_usd"], plan["max_calls"],
                                   protocol["max_input_tokens"], model["parameters"]["max_tokens"], model["pricing"])
        items = [i for i in plan["corpus"]["observations"] if i["split"] == "test"]
        with repo.atomic():
            for item in items:
                for arm in ARMS:
                    repo.conn.execute("INSERT INTO memory_study_decisions VALUES(?,?,?,'planned',NULL)",
                                      (self.run_id, item["observation_id"], arm))
        repo.update_evaluation_run_status(self.run_id, "running")
        try:
            for item in items:
                for arm in arm_order(plan, item["observation_id"]):
                    chain = []
                    for attempt in range(1, protocol["retry_limit"] + 2):
                        call = await self._call(item, arm, attempt, credential)
                        validation = assess(item, call)
                        chain.append({"call_id": call["id"], "raw_output_sha256": canonical_hash(call["raw_output"]), **validation})
                        if validation["valid"]:
                            break
                    outcome = {"chain": chain, "fallback_required": not chain[-1]["valid"], "executed_fallbacks": 0}
                    repo.conn.execute("UPDATE memory_study_decisions SET status='finished',outcome_json=? WHERE run_id=? AND observation_id=? AND arm=?",
                                      (json.dumps(outcome, ensure_ascii=False), self.run_id, item["observation_id"], arm))
                    repo.conn.commit()
            repo.update_evaluation_run_status(self.run_id, "finished")
        except asyncio.CancelledError:
            repo.update_evaluation_run_status(self.run_id, "cancelled")
        except Exception as exc:
            repo.update_evaluation_run_status(self.run_id, "failed", f"{type(exc).__name__}: {exc}")
        return self.run_id

src/backend/arena/evaluation/report.py:
"""Evidence-first audits and offline reports. Ratios always retain denominators."""
from __future__ import annotations
import csv
import json
import math
from collections import Counter, defaultdict
from dataclasses import asdict
from pathlib import Path

from ..engine.projection import digest, project
from .spec import ExperimentSpec


def rows(repo, sql, args=()):
    return [dict(r) for r in repo.conn.execute(sql, args)]


def ratio(n, d):
    return {"numerator": n, "denominator": d, "value": n/d if d else None}


def latency(values):
    values = sorted(v for v in values if v is not None)
    n = len(values)
    return {"n": n, "p50": values[math.ceil(n*.5)-1] if n else None,
            "p95": values[math.ceil(n*.95)-1] if n else None,
            "mean": sum(values)/n if n else None, "max": max(values) if n else None}


def replay_audit(repo, match_id):
    """Re-execute stored bids and plays with the same engine, verify every hash."""
    from ..engine.deck import Deck
    from ..engine.state import GameEngine, TableState, TablePhase
    from ..engine.card import Card
    from ..engine.scoring import calculate_hand_score, calculate_diff_score
    issues, hashes = [], {}
    total_red = total_blue = 0
    for hand in repo.get_hands_for_match(match_id):
        scores = {}
        for th in repo.get_table_hands_for_hand(hand["id"]):
            state = TableState(table=th["table"])
            GameEngine.init_hand(state, hand_num=hand["hand_num"], dealer=hand["dealer"], idle_seat=hand["idle_seat"], deal_result=Deck(hand["seed"]).deal())
            state.seat_teams = {"S":"red", "N":"red", "E":"blue", "W":"blue"} if th["table"] == "A" else {"S":"blue", "N":"blue", "E":"red", "W":"red"}
            try:
                GameEngine.start_bidding(state)
                decisions = rows(repo, "SELECT * FROM decisions WHERE table_hand_id=? AND action_id IS NOT NULL ORDER BY CASE phase WHEN 'bidding' THEN 0 ELSE 1 END, action_seq", (th["id"],))
                for d in decisions:
                    action = json.loads(d["actual_action"])
                    if d["phase"] == "bidding":
                        GameEngine.submit_bid(state, d["seat"], action["bid"], 0)
                    else:
                        if state.phase != TablePhase.PLAYING:
                            GameEngine.finalize_bidding(state)
                            GameEngine.start_playing(state)
                        GameEngine.submit_play(state, d["seat"], [Card.from_string(c) for c in action["cards"]], 0)
                    if digest(project(state)) != d["state_hash_after"]:
                        issues.append(f"state hash mismatch: {d['decision_id']}")
                if th["status"] == "finished":
                    if state.phase != TablePhase.FINISHED or not state.winner_seat:
                        issues.append(f"no normal terminal state: {th['id']}")
                    remaining = repo.get_remaining_hands_for_table(th["id"])
                    expected = {s:[str(c) for c in cards] for s,cards in GameEngine.get_remaining_hands(state).items()}
                    if expected != remaining:
                        issues.append(f"remaining hands mismatch: {th['id']}")
                if th['status'] in ('finished', 'void'):
                    is_void = state.phase == TablePhase.VOID
                    if is_void != (th['status'] == 'void') or bool(th['void']) != is_void:
                        issues.append(f"void terminal mismatch: {th['id']}")
                    score = calculate_hand_score(final_bid=state.final_bid,
                        winner_seat=state.winner_seat, winner_team=state.winner_team,
                        landlord_seat=state.landlord, bombs_played=state.bombs_played,
                        spring=state.winner_role == 'landlord' and state.farmer_has_not_played,
                        anti_spring=state.winner_role == 'farmer' and state.landlord_play_count <= 1,
                        void=is_void)
                    scores[th['table']] = score
                    fields = {'winner_team': score.winner_team, 'winner_role': score.winner_role,
                        'base_score': score.base_score, 'multiplier': score.multiplier,
                        'final_score': score.final_score, 'bombs_played': score.bombs,
                        'spring': int(score.spring), 'anti_spring': int(score.anti_spring)}
                    if any((th[k] or 0 if isinstance(v, int) else th[k] or '') != v for k, v in fields.items()):
                        issues.append(f"terminal score mismatch: {th['id']}")
                hashes[th["id"]] = digest(project(state))
            except Exception as exc:
                issues.append(f"replay failed {th['id']}: {exc}")
        if set(scores) == {'A', 'B'}:
            red, blue = calculate_diff_score(scores['A'], scores['B'])
            if (hand['diff_score_red'], hand['diff_score_blue']) != (red, blue):
                issues.append(f"hand score mismatch: {hand['id']}")
            total_red += red
            total_blue += blue
    match = repo.get_match(match_id)
    if match and match['status'] == 'finished' and (match['score_red'], match['score_blue']) != (total_red, total_blue):
        issues.append(f'match score mismatch: {match_id}')
    return issues, hashes


def audit_match(repo, match_id, spec):
    issues = []
    match = repo.get_match(match_id) if match_id else None
    if not match or match["status"] != "finished":
        return ["match missing or not finished"]
    hands = repo.get_hands_for_match(match_id)
    if not spec.total_hands <= len(hands) <= spec.total_hands + spec.max_tiebreaker_hands:
        issues.append("configured hand count not satisfied")
    for h in hands:
        tables = repo.get_table_hands_for_hand(h["id"])
        if h["status"] != "finished" or len(tables) != 2 or {t["table"] for t in tables} != {"A","B"}:
            issues.append(f"incomplete hand pair: {h['id']}")
        for t in tables:
            if t["status"] not in ("finished","void"):
                issues.append(f"nonterminal table: {t['id']}")
    stream = rows(repo, "SELECT * FROM match_events WHERE match_id=? ORDER BY seq", (match_id,))
    if [e['seq'] for e in stream] != list(range(1,len(stream)+1)):
        issues.append("event stream gap")
    linked = Counter(json.loads(e['event_json']).get('payload',{}).get('decision_id') for e in stream)
    for d in rows(repo,"SELECT decision_id FROM decisions WHERE match_id=? AND action_id IS NOT NULL",(match_id,)):
        if linked[d['decision_id']] != 1: issues.append(f"action event linkage: {d['decision_id']}")
    issues.extend(audit_decisions(repo, match_id=match_id))
    replay_issues, _ = replay_audit(repo, match_id)
    return issues + replay_issues


def audit_decisions(repo, *, match_id=None, run_id=None):
    key, value = ("match_id", match_id) if match_id else ("run_id", run_id)
    decisions = rows(repo, f"SELECT * FROM decisions WHERE {key}=?", (value,))
    issues = []
    for d in decisions:
        if d["resolution"] is None:
            issues.append(f"unresolved decision: {d['decision_id']}")
        committed = d["resolution"] in ("model_first","model_retry","system_fallback","system_autoplay")
        if committed:
            table = "bidding_records" if d["phase"] == "bidding" else "play_actions"
            a = repo.conn.execute(f"SELECT * FROM {table} WHERE id=?", (d["action_id"],)).fetchone()
            if not a:
                issues.append(f"missing committed action: {d['decision_id']}")
            else:
                action = {"bid": a["bid"]} if d["phase"] == "bidding" else {"type": a["action_type"], "cards": json.loads(a["cards"] or '[]')}
                if action != json.loads(d["actual_action"] or 'null') or a["seq"] != d["action_seq"] or a["seat"] != d["seat"]:
                    issues.append(f"actual action differs: {d['decision_id']}")
        calls = rows(repo, "SELECT l.*,e.provider_status,e.call_id AS evidence_id FROM llm_call_logs l LEFT JOIN call_evidence e ON e.call_id=l.id WHERE l.decision_id=? ORDER BY attempt", (d["decision_id"],))
        if d["resolution"] in ("model_first","model_retry") and not calls:
            issues.append(f"model success without call: {d['decision_id']}")
        if [c["attempt"] for c in calls] != list(range(1,len(calls)+1)):
            issues.append(f"noncontiguous attempts: {d['decision_id']}")
        for call in calls:
            if not call["evidence_id"]:
                issues.append(f"missing call evidence: {call['id']}")
            events = rows(repo, "SELECT * FROM decision_events WHERE decision_id=? AND attempt=?", (d["decision_id"],call["attempt"]))
            if call["success"] and len(events) != 1:
                issues.append(f"missing/duplicate validation: {call['id']}")
        from .audit import decision_issues
        issues.extend(decision_issues(repo, d, calls))
    calls = rows(repo, f"SELECT l.id FROM llm_call_logs l LEFT JOIN decisions d ON d.decision_id=l.decision_id WHERE l.{key}=? AND l.phase IN ('bidding','playing') AND d.decision_id IS NULL", (value,))
    issues += [f"orphan call: {c['id']}" for c in calls]
    # Every persisted action in this scope needs exactly one decision, including
    # actions whose resolution transaction might otherwise have been lost.
    for table in ("bidding_records","play_actions"):
        sql = f"""SELECT a.id,COUNT(d.decision_id) AS n FROM {table} a
            JOIN table_hands th ON th.id=a.table_hand_id JOIN hands h ON h.id=th.hand_id
            LEFT JOIN decisions d ON d.action_id=a.id
            WHERE h.match_id IN (SELECT DISTINCT match_id FROM decisions WHERE {key}=?)
            GROUP BY a.id HAVING n != 1"""
        issues += [f"action linkage: {r['id']}" for r in rows(repo,sql,(value,))]
    return issues


def metric_group(decisions, calls, events):
    by_call, by_event = defaultdict(list), defaultdict(list)
    for c in calls: by_call[c["decision_id"]].append(c)
    for e in events: by_event[e["decision_id"]].append(e)
    L = [d for d in decisions if by_call[d["decision_id"]]]
    first = {d["decision_id"]: min(by_call[d["decision_id"]],key=lambda c:c["attempt"]) for d in L}
    returned = {k for k,c in first.items() if c["success"]}
    valid = {k for k in returned if any(e["attempt"]==1 and not e["is_illegal"] and not e["error_code"] for e in by_event[k])}
    illegal = {k for k in returned if any(e["attempt"]==1 and e["is_illegal"] for e in by_event[k])}
    success = set()
    for d in L:
        cs = by_call[d['decision_id']]
        last = max(cs, key=lambda c: c['attempt'])
        expected = 'model_first' if len(cs) == 1 else 'model_retry'
        valid_final = any(e['attempt'] == last['attempt'] and not e['is_illegal'] and not e['error_code'] for e in by_event[d['decision_id']])
        if d['resolution'] == expected and last['success'] and valid_final:
            success.add(d['decision_id'])
    retried = {k for k,cs in by_call.items() if len(cs)>1}
    available_error = set(first)-returned
    counts = Counter(d["resolution"] or "running" for d in decisions)
    result = {"D":len(decisions),"L":len(L),"calls":len(calls),"resolutions":dict(counts),
        "first_availability":ratio(len(returned),len(L)),"first_output_legality":ratio(len(valid),len(returned)),
        "first_decision_success":ratio(len(valid),len(L)),"model_success":ratio(len(success),len(L)),
        "illegal_recovery":ratio(len(illegal & success),len(illegal)),
        "provider_error_recovery":ratio(len(available_error & success),len(available_error)),
        "fallback":ratio(counts['system_fallback'],len(decisions)),"autoplay":ratio(counts['system_autoplay'],len(decisions)),
        "retry":ratio(len(retried),len(L)),"attempt_distribution":dict(Counter(len(by_call[d['decision_id']]) for d in L)),
        "provider_latency_ms":latency([c['latency_ms'] for c in calls]),
        "decision_latency_ms":latency([d['latency_ms'] for d in decisions]),
        "success_latency_ms":latency([d['latency_ms'] for d in decisions if d['decision_id'] in success]),
        "failure_latency_ms":latency([d['latency_ms'] for d in decisions if d['decision_id'] not in success]),
        "timeout_latency_ms":latency([d['latency_ms'] for d in decisions if d['reason']=='timeout']),
        "usage_coverage":ratio(sum(c['prompt_tokens'] is not None and c['completion_tokens'] is not None for c in calls),len(calls)),
        "prompt_tokens_known":sum(c['prompt_tokens'] or 0 for c in calls),
        "completion_tokens_known":sum(c['completion_tokens'] or 0 for c in calls)}
    return result


def build_report(repo, run_id):
    run = repo.get_evaluation_run(run_id)
    manifest = json.loads(run['manifest_json'])
    spec = ExperimentSpec.model_validate(manifest['frozen_spec'])
    tasks = repo.get_evaluation_tasks(run_id)
    decisions = rows(repo,"SELECT * FROM decisions WHERE run_id=?",(run_id,))
    calls = rows(repo,"SELECT * FROM llm_call_logs WHERE run_id=?",(run_id,))
    events = repo.get_decision_events(run_id=run_id)
    attempts = rows(repo,"SELECT a.*,t.seed,t.variant_id FROM task_attempts a JOIN evaluation_tasks t ON t.id=a.task_id WHERE t.run_id=?",(run_id,))
    issues = audit_decisions(repo, run_id=run_id)
    from .audit import budget_issues
    issues.extend(budget_issues(repo, run_id, manifest))
    terminal_hashes = {}
    tables = []
    for attempt in attempts:
        if not attempt['match_id']: continue
        tables += rows(repo,"SELECT th.* FROM table_hands th JOIN hands h ON h.id=th.hand_id WHERE h.match_id=?",(attempt['match_id'],))
        if attempt['status']=='finished': issues += audit_match(repo,attempt['match_id'],spec)
        replay_issues, hashes = replay_audit(repo, attempt['match_id'])
        issues += replay_issues
        terminal_hashes.update(hashes)
    for task in tasks:
        if task['status']=='finished' and not any(a['task_id']==task['id'] and a['status']=='finished' for a in attempts):
            issues.append(f"finished task lacks audited attempt: {task['id']}")
    if any(t['status'] in ('planned','running') for t in tasks): issues.append('run contains nonterminal tasks')
    integrity = {'complete':not issues,'issues':sorted(set(issues)), 'run_status':run['status'], 'terminal_state_hashes':terminal_hashes}
    metrics = []
    for variant in manifest['variants']:
        for phase in ('bidding','playing'):
            ds=[d for d in decisions if d['variant_id']==variant['variant_id'] and d['phase']==phase]
            ids={d['decision_id'] for d in ds}
            metrics.append({'variant':variant['variant_id'],'phase':phase,**metric_group(ds,[c for c in calls if c['decision_id'] in ids],[e for e in events if e['decision_id'] in ids])})
    seed_level=[]
    for variant in manifest['variants']:
        for seed in manifest['seeds']:
            aids={a['id'] for a in attempts if a['seed']==seed and a['variant_id']==variant['variant_id']}
            ds=[d for d in decisions if d['task_attempt_id'] in aids]
            ids={d['decision_id'] for d in ds}
            seed_level.append({'variant':variant['variant_id'],'seed':seed,**metric_group(ds,[c for c in calls if c['decision_id'] in ids],[e for e in events if e['decision_id'] in ids])})
    ledger=rows(repo,'SELECT * FROM budget_ledger WHERE run_id=?',(run_id,))
    links = Counter(r['call_id'] for r in ledger)
    call_ids = {c['id'] for c in calls}
    covered = [r for r in ledger if r['call_id'] in call_ids and links[r['call_id']] == 1 and r['actual_usd'] is not None]
    normal=sum(t['status']=='finished' for t in tables)
    known=sum(r['actual_usd'] or 0 for r in ledger)
    summary={'metric_version':'reliability-v2','execution_kind':'mock' if manifest['models'][0]['provider']=='mock' else 'real',
        'run_id':run_id,'manifest_sha256':manifest['manifest_sha256'],'integrity_complete':integrity['complete'],
        'task_counts':dict(Counter(t['status'] for t in tasks)),'planned_tasks':len(tasks),'started_attempts':len(attempts),
        'planned_table_hands':len(tasks)*spec.total_hands*2,'started_table_hands':len(tables),
        'table_status_counts':dict(Counter(t['status'] for t in tables)),
        'normal_table_completion':ratio(normal,len(tables)),
        'match_latency_ms':latency([(a['finished_at']-a['started_at'])*1000 for a in attempts if a['finished_at']]),
        'known_cost_usd':known,'cost_coverage':ratio(len(covered),len(calls)),
        'budget_exposure_usd':sum(r['actual_usd'] if r['actual_usd'] is not None else r['reserved_usd'] for r in ledger),
        'cost_per_normal_table_usd':known/normal if normal and len(ledger)==len(calls) and all(r['actual_usd'] is not None for r in ledger) else None,
        'metrics':metrics,'limits':['mock results measure plumbing only','self-play does not establish competitive advantage',
        'seed is the independent cluster; decision counts are correlated','P95 uses nearest-rank; small samples are descriptive',
        'unknown usage retains reservation; known totals are lower bounds when coverage is incomplete']}
    failures=[]
    for d in decisions:
        if d['resolution'] not in ('model_first','system_autoplay') or any(e['decision_id']==d['decision_id'] and e['is_illegal'] for e in events):
            evidence=rows(repo,'SELECT l.*,e.system_prompt,e.user_prompt,e.raw_output,e.provider_status FROM llm_call_logs l LEFT JOIN call_evidence e ON e.call_id=l.id WHERE decision_id=? ORDER BY attempt',(d['decision_id'],))
            failures.append({'decision':d,'attempts':evidence,'validation':[e for e in events if e['decision_id']==d['decision_id']]})
    return manifest,integrity,summary,metrics,seed_level,failures


def export_report(repo,run_id,out):
    out=Path(out); out.mkdir(parents=True,exist_ok=True)
    manifest,integrity,summary,metrics,seeds,failures=build_report(repo,run_id)
    for name,data in [('manifest',manifest),('integrity',integrity),('summary',summary)]:
        (out/f'{name}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
    for name,data in [('metrics',metrics),('seed_level',seeds)]:
        flattened=[]
        for row in data:
            flat={}
            for key,value in row.items():
                if isinstance(value,dict):
                    for sub,v in value.items(): flat[f'{key}_{sub}']=v
                else: flat[key]=value
            flattened.append(flat)
        with (out/f'{name}.csv').open('w',encoding='utf-8',newline='') as handle:
            writer=csv.DictWriter(handle,fieldnames=list(dict.fromkeys(k for r in flattened for k in r)))
            writer.writeheader();writer.writerows(flattened)
    failure_dir=out/'failure-cases';failure_dir.mkdir(exist_ok=True)
    for failure in failures:
        (failure_dir/(failure['decision']['decision_id']+'.json')).write_text(json.dumps(failure,ensure_ascii=False,indent=2),encoding='utf-8')
    lines=[f"# Reliability run {run_id}",f"Execution: {summary['execution_kind']}; integrity: {integrity['complete']}; status: {integrity['run_status']}",
        f"Manifest: {manifest['manifest_sha256']}",f"Tasks: {summary['task_counts']}; table-hands: {summary['table_status_counts']}",
        f"Known cost USD: {summary['known_cost_usd']}; coverage: {summary['cost_coverage']}",
        '', '| Variant | Phase | First availability | First output legality | Model success | Fallback |', '|---|---|---|---|---|---|']
    def fmt(r): return f"{r['numerator']}/{r['denominator']} ({r['value']:.1%})" if r['denominator'] else 'N/A (0/0)'
    for m in metrics: lines.append('| '+' | '.join([m['variant'],m['phase'],*[fmt(m[k]) for k in ('first_availability','first_output_legality','model_success','fallback')]])+' |')
    lines+=['','## Definitions','D: all started bidding/playing decisions including autoplay; L: decisions with an issued model call. R0: first provider returned (including empty text); V0: first returned output passed parser and rules. Availability R0/L; output legality V0/R0; first success V0/L. Model success counts model_first/model_retry only. Illegal recovery divides by all initially illegal returned outputs, even with no retry allowance. Fallback/autoplay divide by D. Retry divides by L. Normal table completion excludes void from the numerator but includes every started table in the denominator. Task attempts, cancellations, failures and unstarted plans are retained. Provider and end-to-end latency use nearest-rank, including failed calls. Unknown usage/cost is NULL, never zero.', '', '## Limits',*summary['limits'], '', '## Integrity issues', *(integrity['issues'] or ['None']), '', f'Failure traces: {len(failures)}; see failure-cases/.']
    # Table rows must be contiguous Markdown lines.
    (out/'report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    return summary

src/backend/arena/evaluation/spec.py:
"""Versioned experiment specifications and dry-run safety validation.

This module deliberately does not start matches or make provider calls.  It makes
the inputs to a later evaluation run explicit and hashes the resulting manifest.
"""

from __future__ import annotations

import hashlib
import importlib.metadata
import json
import subprocess
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any

import yaml
from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator
from ..security.credentials import has_usable_credential


class PreflightError(ValueError):
    """Raised when an experiment is not safe or reproducible to run."""


class ProviderParameters(BaseModel):
    model_config = ConfigDict(extra="forbid")

    max_tokens: int = Field(gt=0, le=32768)
    temperature: float | None = Field(default=None, ge=0, le=2)
    top_p: float | None = Field(default=None, gt=0, le=1)
    seed: int | None = None


class PriceSpec(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)
    input_per_million: float = Field(ge=0)
    output_per_million: float = Field(ge=0)
    source: str
    effective_date: str
    currency: str = "USD"


class ModelSpec(BaseModel):
    model_config = ConfigDict(extra="forbid")

    config_name: str
    provider: str
    model: str
    base_url: str | None = None
    parameters: ProviderParameters
    system_prompt: str | None = None
    pricing: PriceSpec | None = None


class VariantSpec(BaseModel):
    model_config = ConfigDict(extra="forbid")

    variant_id: str = Field(pattern=r"^[a-z][a-z0-9_]{2,63}$")
    retry_limit: int = Field(ge=0, le=10)
    rule_feedback: bool
    enable_reflection: bool
    memory_mode: str = Field(pattern=r"^(disabled|train|read_only)$")

    @model_validator(mode="after")
    def validate_controls(self) -> "VariantSpec":
        if self.memory_mode != "disabled" and not self.enable_reflection:
            raise ValueError("memory_mode requires enable_reflection=true")
        return self


class ExperimentSpec(BaseModel):
    model_config = ConfigDict(extra="forbid")

    experiment_id: str = Field(pattern=r"^[a-z][a-z0-9_-]{2,63}$")
    seed_set_path: str
    training_seed_set_path: str | None = None
    memory_training_variant_id: str | None = None
    training_total_hands: int = Field(default=5, gt=0, le=200)
    memory_artifact_path: str | None = None
    total_hands: int = Field(gt=0, le=200)
    ko_enabled: bool = False
    seat_rotations: int = Field(default=1, ge=1, le=8)
    max_tiebreaker_hands: int = Field(default=0, ge=0, le=100)
    max_calls: int = Field(default=1000, gt=0, le=1000000)
    max_input_tokens: int = Field(default=32768, gt=1024)
    task_timeout_seconds: float = Field(default=600, gt=0, le=86400)
    cancellation_deadline_seconds: float = Field(default=5, gt=0, le=30)
    mock_scenario: str = Field(default='initial_error', pattern=r'^(initial_error|valid_first|play_error)$')
    timeout_config: dict[str, float | int]
    pricing_version: str
    budget_limit_usd: float = Field(ge=0, allow_inf_nan=False)
    models: list[ModelSpec] = Field(min_length=1)
    variants: list[VariantSpec] = Field(min_length=1)

    @field_validator("models")
    @classmethod
    def unique_models(cls, models: list[ModelSpec]) -> list[ModelSpec]:
        names = [model.config_name for model in models]
        if len(names) != len(set(names)):
            raise ValueError("model config_name values must be unique")
        return models

    @field_validator("variants")
    @classmethod
    def unique_variants(cls, variants: list[VariantSpec]) -> list[VariantSpec]:
        ids = [variant.variant_id for variant in variants]
        if len(ids) != len(set(ids)):
            raise ValueError("variant_id values must be unique")
        return variants

    @model_validator(mode="after")
    def validate_memory_training(self) -> "ExperimentSpec":
        if self.training_seed_set_path and not self.memory_training_variant_id:
            raise ValueError("training_seed_set_path requires memory_training_variant_id")
        if self.memory_training_variant_id and self.memory_training_variant_id not in {
            variant.variant_id for variant in self.variants
        }:
            raise ValueError("memory_training_variant_id must reference a configured variant")
        return self


@dataclass(frozen=True, slots=True)
class EvaluationContext:
    """Links runtime observations back to the immutable evaluation run."""

    experiment_id: str = ""
    run_id: str = ""
    variant_id: str = ""


@dataclass(frozen=True, slots=True)
class ModelSnapshot:
    config_name: str
    provider: str
    model: str
    base_url: str | None
    parameters: dict[str, Any]
    prompt_sha256: str
    revision: str
    sdk_version: str
    system_prompt: str | None = None
    prompt_templates: dict[str, str] = field(default_factory=dict)
    pricing: dict[str, Any] | None = None


@dataclass(frozen=True, slots=True)
class RunManifest:
    experiment_id: str
    seed_set_id: str
    seed_set_sha256: str
    seeds: tuple[str, ...]
    training_seed_set_sha256: str | None
    memory_artifact_sha256: str | None
    models: tuple[ModelSnapshot, ...]
    variants: tuple[dict[str, Any], ...]
    source_revision: str
    source_dirty: bool
    dependency_sha256: str
    spec_sha256: str
    manifest_sha256: str
    sampling_reproducibility: str
    source_sha256: str = ""
    rules_version: str = ""
    frozen_spec: dict[str, Any] = field(default_factory=dict)


def load_experiment_spec(path: str | Path) -> ExperimentSpec:
    with Path(path).open(encoding="utf-8") as handle:
        return ExperimentSpec.model_validate(yaml.safe_load(handle))


def build_run_manifest(spec: ExperimentSpec, root: str | Path, repo=None) -> RunManifest:
    """Validate fixed inputs and construct a deterministic, serializable manifest."""
    root_path = Path(root)
    seed_set_id, seeds, seed_hash = _load_seed_set(root_path / spec.seed_set_path)
    training_hash = None
    if spec.training_seed_set_path:
        _, training_seeds, training_hash = _load_seed_set(root_path / spec.training_seed_set_path)
        overlap = set(seeds) & set(training_seeds)
        if overlap:
            raise PreflightError("training and evaluation seed sets overlap")
    memory_hash = None
    if spec.memory_artifact_path:
        _, memory_hash = load_memory_artifact(root_path / spec.memory_artifact_path)

    prompt_hash = _prompt_hash(root_path)
    revision = _git_revision(root_path)
    source_dirty = _git_dirty(root_path)
    dependency_hash = _dependency_hash(root_path)
    templates = {p.name: p.read_text(encoding="utf-8") for p in sorted((root_path / "src/backend/arena/agent/prompts").glob("*.py"))}
    snapshots = []
    for model in spec.models:
        config = repo.get_player_config_by_name(model.config_name) if repo else None
        endpoint = model.base_url or (config.get("base_url") if config else None) or {
            "openai": "https://api.openai.com/v1", "claude": "https://api.anthropic.com", "mock": "mock://local"}.get(model.provider)
        if endpoint:
            from urllib.parse import urlsplit
            url = urlsplit(endpoint)
            if url.username or url.password or url.query or url.fragment:
                raise PreflightError("base_url must not contain credentials, query or fragment")
        override = model.system_prompt if model.system_prompt is not None else (config.get("system_prompt") if config else None)
        snapshots.append(ModelSnapshot(
            config_name=model.config_name, provider=model.provider, model=model.model,
            base_url=endpoint, parameters=model.parameters.model_dump(mode="json"),
            system_prompt=override, prompt_templates=templates,
            pricing=model.pricing.model_dump(mode="json") if model.pricing else None,
            prompt_sha256=_canonical_hash({"templates": templates, "override": override}), revision=revision,
            sdk_version=_sdk_version(model.provider)))
    snapshots = tuple(snapshots)
    from ..engine.projection import RULES_VERSION
    source_hash = source_sha256(root_path)
    spec_payload = spec.model_dump(mode="json")
    spec_hash = _canonical_hash(spec_payload)
    raw = {
        "experiment_id": spec.experiment_id, "seed_set_id": seed_set_id,
        "seed_set_sha256": seed_hash, "seeds": seeds,
        "training_seed_set_sha256": training_hash,
        "memory_artifact_sha256": memory_hash,
        "models": [asdict(snapshot) for snapshot in snapshots],
        "variants": [variant.model_dump(mode="json") for variant in spec.variants],
        "source_revision": revision, "spec_sha256": spec_hash,
        "source_dirty": source_dirty, "dependency_sha256": dependency_hash,
        "source_sha256": source_hash, "rules_version": RULES_VERSION, "frozen_spec": spec_payload,
        "sampling_reproducibility": "provider-dependent; all controllable parameters fixed",
    }
    return RunManifest(
        experiment_id=spec.experiment_id,
        seed_set_id=seed_set_id,
        seed_set_sha256=seed_hash,
        seeds=seeds,
        training_seed_set_sha256=training_hash,
        memory_artifact_sha256=memory_hash,
        models=snapshots,
        variants=tuple(variant.model_dump(mode="json") for variant in spec.variants),
        source_revision=revision,
        source_dirty=source_dirty,
        dependency_sha256=dependency_hash,
        spec_sha256=spec_hash,
        sampling_reproducibility="provider-dependent; all controllable parameters fixed",
        manifest_sha256=_canonical_hash(raw), source_sha256=source_hash,
        rules_version=RULES_VERSION, frozen_spec=spec_payload,
    )


def load_memory_artifact(path: str | Path) -> tuple[dict[str, str], str]:
    """Load a frozen long-term-memory artifact keyed by stable player slot."""
    artifact_path = Path(path)
    try:
        payload = json.loads(artifact_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise PreflightError(f"invalid memory artifact {artifact_path}: {exc}") from exc
    recorded_hash = payload.pop("artifact_sha256", None)
    artifact_id = payload.get("memory_artifact_id")
    memories = payload.get("memories")
    if not isinstance(artifact_id, str) or not artifact_id:
        raise PreflightError("memory artifact requires memory_artifact_id")
    if not isinstance(memories, dict) or not all(
        isinstance(key, str) and isinstance(value, str) for key, value in memories.items()
    ):
        raise PreflightError("memory artifact memories must be a string-to-string object")
    artifact_hash = _canonical_hash(payload)
    if recorded_hash is not None and recorded_hash != artifact_hash:
        raise PreflightError("memory artifact sha256 does not match its contents")
    return dict(memories), artifact_hash


def load_seed_set(path: str | Path) -> tuple[str, tuple[str, ...], str]:
    return _load_seed_set(Path(path))


def canonical_hash(value: Any) -> str:
    return _canonical_hash(value)


def _load_seed_set(path: Path) -> tuple[str, tuple[str, ...], str]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise PreflightError(f"invalid seed set {path}: {exc}") from exc
    seed_set_id = payload.get("seed_set_id")
    seeds = payload.get("seeds")
    if not isinstance(seed_set_id, str) or not seed_set_id:
        raise PreflightError("seed set requires seed_set_id")
    if not isinstance(seeds, list) or not seeds or not all(isinstance(seed, str) and seed for seed in seeds):
        raise PreflightError("seed set requires non-empty string seeds")
    if len(seeds) != len(set(seeds)):
        raise PreflightError("seed set contains duplicate seeds")
    canonical = {"seed_set_id": seed_set_id, "seeds": seeds}
    return seed_set_id, tuple(seeds), _canonical_hash(canonical)


def _prompt_hash(root: Path) -> str:
    prompt_dir = root / "src/backend/arena/agent/prompts"
    digest = hashlib.sha256()
    for path in sorted(prompt_dir.glob("*.py")):
        digest.update(path.name.encode())
        digest.update(path.read_bytes())
    return digest.hexdigest()


def _git_revision(root: Path) -> str:
    try:
        return subprocess.check_output(
            ["git", "rev-parse", "HEAD"], cwd=root, text=True, stderr=subprocess.DEVNULL
        ).strip()
    except (OSError, subprocess.CalledProcessError):
        return "unavailable"


def _git_dirty(root: Path) -> bool:
    try:
        output = subprocess.check_output(
            ["git", "status", "--porcelain"], cwd=root, text=True,
            stderr=subprocess.DEVNULL,
        )
        return bool(output.strip())
    except (OSError, subprocess.CalledProcessError):
        return True


def _dependency_hash(root: Path) -> str:
    digest = hashlib.sha256()
    paths = [
        root / "src/backend/pyproject.toml",
        root / "src/backend/requirements.txt",
        root / "src/frontend/package-lock.json",
    ]
    for path in paths:
        digest.update(str(path.relative_to(root)).encode())
        digest.update(path.read_bytes() if path.exists() else b"missing")
    return digest.hexdigest()


def _sdk_version(provider: str) -> str:
    package = "anthropic" if provider == "claude" else "openai"
    try:
        return importlib.metadata.version(package)
    except importlib.metadata.PackageNotFoundError:
        return "unavailable"


def _canonical_hash(value: Any) -> str:
    data = json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(data.encode()).hexdigest()


def source_sha256(root):
    paths = sorted((Path(root)/"src/backend/arena").rglob("*.py"))
    return _canonical_hash({str(p.relative_to(root)): hashlib.sha256(p.read_bytes()).hexdigest() for p in paths})


def load_manifest(raw):
    raw = dict(raw)
    raw["models"] = tuple(ModelSnapshot(**m) for m in raw["models"])
    raw["seeds"] = tuple(raw["seeds"])
    raw["variants"] = tuple(raw["variants"])
    return RunManifest(**raw)


def validate_execution(spec, manifest, root, repo, *, mock=False):
    raw = asdict(manifest)
    raw.pop('manifest_sha256')
    if _canonical_hash(raw) != manifest.manifest_sha256:
        raise PreflightError('manifest hash mismatch')
    if _canonical_hash(spec.model_dump(mode="json")) != manifest.spec_sha256:
        raise PreflightError("spec does not match frozen manifest")
    if not manifest.source_sha256 or source_sha256(root) != manifest.source_sha256:
        raise PreflightError("runtime source differs from frozen manifest; create a new run")
    if _dependency_hash(Path(root)) != manifest.dependency_sha256:
        raise PreflightError('runtime dependency specification differs from frozen manifest')
    if any(_sdk_version(m.provider) != m.sdk_version for m in manifest.models):
        raise PreflightError('runtime SDK differs from frozen manifest')
    if len(manifest.models) != 1:
        raise PreflightError("first round requires one model")
    if any(v.enable_reflection or v.memory_mode != "disabled" for v in spec.variants):
        raise PreflightError("first round disables reflection/memory; read_only requires memory_artifact_path and a separate protocol")
    model = manifest.models[0]
    if model.provider != ("mock" if mock else model.provider) or (not mock and model.provider not in ("openai", "claude")):
        raise PreflightError("provider does not match execution mode")
    if not model.pricing or model.pricing.get("currency") != "USD":
        raise PreflightError("explicit USD pricing with source and effective date required")
    if not mock:
        if not model.model or any(x in model.model.lower() for x in ("replace", "placeholder", "tbd")):
            raise PreflightError("actual model required")
        config = repo.get_player_config_by_name(model.config_name)
        if not config or not has_usable_credential(config.get("api_key")):
            raise PreflightError("credential unavailable")
        if model.provider == "claude" and model.parameters.get("seed") is not None:
            raise PreflightError("Claude does not accept a sampling seed")
        if not model.pricing["source"].strip() or not model.pricing["effective_date"].strip():
            raise PreflightError("explicit real model pricing source and effective date required")
        if spec.budget_limit_usd == 0 and any(model.pricing[key] > 0 for key in (
            "input_per_million", "output_per_million"
        )):
            raise PreflightError("zero budget requires zero input and output prices")

