/**
 * API client — wraps REST calls to the backend.
 */

const BASE = '/api/v1';

async function request(path, options = {}) {
  const res = await fetch(BASE + path, {
    headers: { 'Content-Type': 'application/json', ...options.headers },
    ...options,
  });
  if (res.status === 204) return null;
  const data = await res.json();
  if (!res.ok) {
    const detail = data?.error || data?.detail?.error;
    const err = new Error(detail?.message || (typeof data?.detail === 'string' ? data.detail : res.statusText));
    err.code = detail?.code || 'UNKNOWN';
    err.status = res.status;
    throw err;
  }
  return data;
}

export const api = {
  // ── matches ──
  listMatches(params = {}) {
    const qs = new URLSearchParams(params).toString();
    return request(`/matches${qs ? '?' + qs : ''}`);
  },
  createMatch(body) {
    return request('/matches', { method: 'POST', body: JSON.stringify(body) });
  },
  getMatch(id) {
    return request(`/matches/${id}`);
  },
  startMatch(id) {
    return request(`/matches/${id}/start`, { method: 'POST' });
  },
  pauseMatch(id) {
    return request(`/matches/${id}/pause`, { method: 'POST' });
  },
  resumeMatch(id) {
    return request(`/matches/${id}/resume`, { method: 'POST' });
  },
  deleteMatch(id) {
    return request(`/matches/${id}`, { method: 'DELETE' });
  },

  // ── hands / replay ──
  getHands(matchId) {
    return request(`/matches/${matchId}/hands`);
  },
  getHandDetail(matchId, handNum) {
    return request(`/matches/${matchId}/hands/${handNum}`);
  },
  getTableHand(matchId, handNum, table) {
    return request(`/matches/${matchId}/hands/${handNum}/table/${table.toLowerCase()}`);
  },

  // ── agents (backward compatible — returns players) ──
  listAgents() {
    return request('/agents');
  },
  reloadAgents() {
    return request('/agents/reload', { method: 'POST' });
  },
  createAgent(body) {
    return request('/agents', { method: 'POST', body: JSON.stringify(body) });
  },
  updateAgent(id, body) {
    return request(`/agents/${id}`, { method: 'PUT', body: JSON.stringify(body) });
  },
  deleteAgent(id) {
    return request(`/agents/${id}`, { method: 'DELETE' });
  },

  // ── player configs ──
  listConfigs() {
    return request('/configs');
  },
  createConfig(body) {
    return request('/configs', { method: 'POST', body: JSON.stringify(body) });
  },
  updateConfig(id, body) {
    return request(`/configs/${id}`, { method: 'PUT', body: JSON.stringify(body) });
  },
  deleteConfig(id) {
    return request(`/configs/${id}`, { method: 'DELETE' });
  },
  reloadConfigs() {
    return request('/configs/reload', { method: 'POST' });
  },

  // ── reliability evaluations ──
  getEvaluationTemplate(mode = 'mock') {
    return request(`/evaluations/template?mode=${encodeURIComponent(mode)}`);
  },
  getEvaluationReport(id) {
    return request(`/evaluations/${id}/report`);
  },
  evaluationArtifactUrl(id, filename) {
    return `${BASE}/evaluations/${encodeURIComponent(id)}/artifacts/${encodeURIComponent(filename)}`;
  },
  listEvaluations() {
    return request('/evaluations');
  },
  getEvaluation(id) {
    return request(`/evaluations/${id}`);
  },
  preflightEvaluation(body) {
    return request('/evaluations/preflight', { method: 'POST', body: JSON.stringify(body) });
  },
  createEvaluation(body) {
    return request('/evaluations', { method: 'POST', body: JSON.stringify(body) });
  },
  startEvaluation(id, confirmRealModels = false) {
    return request(`/evaluations/${id}/start`, { method: 'POST', body: JSON.stringify({ confirm_real_models: confirmRealModels }) });
  },
  resumeEvaluation(id, confirmRealModels = false) {
    return request(`/evaluations/${id}/resume`, { method: 'POST', body: JSON.stringify({ confirm_real_models: confirmRealModels }) });
  },
  cancelEvaluation(id) {
    return request(`/evaluations/${id}/cancel`, { method: 'POST' });
  },

  // ── players ──
  listPlayers(configId) {
    const qs = configId ? `?config_id=${encodeURIComponent(configId)}` : '';
    return request(`/players${qs}`);
  },
  createPlayer(body) {
    return request('/players', { method: 'POST', body: JSON.stringify(body) });
  },
  getPlayer(id) {
    return request(`/players/${id}`);
  },
  getPlayerLeaderboard(sort = 'win_rate') {
    return request(`/players/leaderboard?sort=${encodeURIComponent(sort)}`);
  },
  updatePlayer(id, body) {
    return request(`/players/${id}`, { method: 'PUT', body: JSON.stringify(body) });
  },
  deletePlayer(id) {
    return request(`/players/${id}`, { method: 'DELETE' });
  },
};

/**
 * WebSocket client for live match streaming.
 */
export function createMatchSocket(matchId, handlers = {}) {
  const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
  const url = `${protocol}//${location.host}/ws/match/${matchId}`;
  let ws = null;
  let reconnectTimer = null;
  let reconnectDelay = 1000;
  let closed = false;
  let lastSeq = null;
  let awaitingSnapshot = true;

  function connect() {
    if (closed) return;
    awaitingSnapshot = true;
    ws = new WebSocket(url);

    ws.onopen = () => {
      reconnectDelay = 1000;
      handlers.onOpen?.();
    };

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);
      const type = data.type;
      if (type === 'resync_required') { ws.close(); return; }
      if (type === 'match_state') {
        lastSeq = data.payload.watermark;
        awaitingSnapshot = false;
      } else if (Number.isInteger(data.seq)) {
        if (awaitingSnapshot || data.seq <= lastSeq) return;
        if (data.seq !== lastSeq + 1) { awaitingSnapshot = true; ws.close(); return; }
        lastSeq = data.seq;
      }
      if (type === 'pong') {
        handlers.onPong?.();
      } else if (handlers.onEvent) {
        handlers.onEvent(data);
      } else if (handlers[type]) {
        handlers[type](data.payload);
      }
    };

    ws.onclose = () => {
      if (!closed) {
        reconnectTimer = setTimeout(connect, reconnectDelay);
        reconnectDelay = Math.min(reconnectDelay * 2, 30000);
      }
    };

    ws.onerror = () => {
      ws?.close();
    };
  }

  function send(msg) {
    if (ws?.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify(msg));
    }
  }

  connect();

  return {
    send,
    close() {
      closed = true;
      clearTimeout(reconnectTimer);
      ws?.close();
    },
  };
}

