describe('useReplayState', () => {
  it('sorts bidding hands and advances to the next bidder', () => {
    const tableDetail = ref({
      dealer: 'S',
      idle_seat: 'W',
      initial_hands: {
        S: ['♦3', '♠A', '♣2', '大王', '♥2', '小王', '♠2'],
