        { seat: 'E', bid: 2, timestamp_ms: 2 },
        { seat: 'N', bid: 0, timestamp_ms: 3 },
      ],
    });
    const currentStep = ref(0);
    const state = useReplayState({ tableDetail, currentStep });

    expect(state.value.tableData.current_seat).toBe('S');
